INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "施工队正在把水管引至在山坡上的水池。", "corrected_sentence": "施工队正在把水管引至山坡上的水池。", "error_description": "错误在于补语重复：“引至”的“至”已表示到达，后面不能再加“在”。应说“引至山坡上的水池”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
