INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25274, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "水变成水蒸气跑到空气里，不见了。", "primary_collocate": null, "pronunciation": "zhēng fā", "ipa": "ʈʂɤŋ˥ fa˥", "syllable_count": 2, "sentences": [{"text": "洗好的衣服晾在外面，水很快蒸发了。", "target_word": "蒸发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的路面上，积水慢慢蒸发。", "target_word": "蒸发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子没盖，里面的水都蒸发了。", "target_word": "蒸发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热天里，洒在地上的水一下子就蒸发了。", "target_word": "蒸发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小水坑被太阳晒干，水都蒸发了。", "target_word": "蒸发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "池塘里的水一天天蒸发，变少了。", "target_word": "蒸发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿毛巾放在阳光下，水很快蒸发。", "target_word": "蒸发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锅没盖盖子，汤里的水蒸发了不少。", "target_word": "蒸发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天太热，花盆里的水蒸发得快。", "target_word": "蒸发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的水不见了，原来是蒸发了。", "target_word": "蒸发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "蒸发了", "label": "体标"}, {"form": "蒸发着", "label": "体标"}, {"form": "蒸发量", "label": "复合"}, {"form": "蒸發", "label": "繁体"}], "register": "中性", "sense_fingerprint": "日常生活中水跑到空气里而消失、变干", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8873e8b-ebaa-461c-94d4-dce7b35fae3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25274, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蒸发", "is_correct": true, "explanation": "蒸发（zhēng fā）：水变成水蒸气跑到空气里。"}, {"text": "增发", "is_correct": false, "explanation": "zēng 与 zhēng 声母不同（z 与 zh），意思是增加发行。"}, {"text": "生发", "is_correct": false, "explanation": "shēng 与 zhēng 声母不同（sh 与 zh），意思是头发生长。"}, {"text": "政法", "is_correct": false, "explanation": "zhèng 与 zhēng 声调不同，fǎ 与 fā 声调也不同，意思是政治和法律。"}], "explanations": {"蒸发": "蒸发（zhēng fā）：水变成水蒸气跑到空气里。", "增发": "zēng 与 zhēng 声母不同（z 与 zh），意思是增加发行。", "生发": "shēng 与 zhēng 声母不同（sh 与 zh），意思是头发生长。", "政法": "zhèng 与 zhēng 声调不同，fǎ 与 fā 声调也不同，意思是政治和法律。"}, "sentence_index": null, "correct_answer": "蒸发"}, "level_3": {"options": [{"text": "蒸发", "is_correct": true, "explanation": "正确：“水很快蒸发了”指洗好的衣服晾干时水跑到空气里，与语境相符。"}, {"text": "沸腾", "is_correct": false, "explanation": "语义：晾在外面的衣服上的水不会沸腾，与日常晾晒的语境不符。"}, {"text": "融化", "is_correct": false, "explanation": "搭配：“融化”指固体变成液体，水不说融化。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：晾晒的衣服上的水不会凝固，与“水很快”的语境矛盾。"}], "explanations": {"蒸发": "正确：“水很快蒸发了”指洗好的衣服晾干时水跑到空气里，与语境相符。", "沸腾": "语义：晾在外面的衣服上的水不会沸腾，与日常晾晒的语境不符。", "融化": "搭配：“融化”指固体变成液体，水不说融化。", "凝固": "语义：晾晒的衣服上的水不会凝固，与“水很快”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "蒸发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "糖洒进水里，一下子就蒸发了。", "explanation": "这里应该用〈溶解〉。糖是固体，溶于水要说溶解，蒸发只用于液体变成气体。"}, {"text": "雨水慢慢蒸发进了土里。", "explanation": "这里应该用〈渗〉。雨水往土里走要说渗，蒸发是水变成水蒸气跑到空气里，不会钻进土里。"}, {"text": "汗水顺着脸颊蒸发下来。", "explanation": "这里应该用〈流〉。汗水往下淌要说流，蒸发是水变成水蒸气跑到空气里，不会顺着脸往下走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蒸发", "is_correct": true, "explanation": "正确：“湿毛巾放在阳光下，水很快蒸发”指毛巾上的水跑到空气里，与阳光晒的语境相符。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：放在阳光下的湿毛巾不会结冰，与阳光的语境矛盾。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：阳光下的毛巾不会冷却，与“阳光”的语境矛盾。"}, {"text": "喷涌", "is_correct": false, "explanation": "搭配：“喷涌”指液体大量猛烈涌出，毛巾上的水不说喷涌。"}], "explanations": {"蒸发": "正确：“湿毛巾放在阳光下，水很快蒸发”指毛巾上的水跑到空气里，与阳光晒的语境相符。", "结冰": "语义：放在阳光下的湿毛巾不会结冰，与阳光的语境矛盾。", "冷却": "语义：阳光下的毛巾不会冷却，与“阳光”的语境矛盾。", "喷涌": "搭配：“喷涌”指液体大量猛烈涌出，毛巾上的水不说喷涌。"}, "sentence_index": 6, "correct_answer": "蒸发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌上的水不见了，原来是蒸发成了冰。", "explanation": "结果错误：蒸发得到的是水蒸气，变成冰要说结冰，这里把结果说错了。"}, {"text": "桌上的水不见了，原来是从缝里蒸发下去了。", "explanation": "这里应该用〈漏〉。水从缝隙往下掉要说漏，蒸发是水变成水蒸气跑到空气里，不会从缝里往下走。"}, {"text": "杯子倒了，水蒸发到了地上。", "explanation": "这里应该用〈溅〉。水被弄洒出去、落到地上要说溅，蒸发是水变成水蒸气跑到空气里，不会落到地上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晾在阳光下的衣服，水很快就蒸发了干。", "corrected_sentence": "晾在阳光下的衣服，水很快就蒸发干了。", "error_description": "错误：结果补语“干”放在了“了”之后。正确：“蒸发干了”，结果补语要紧跟动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湿毛巾晾在窗边，水一直在蒸发过。", "corrected_sentence": "湿毛巾晾在窗边，水一直在蒸发着。", "error_description": "错误：表示持续进行要用“着”，“过”表示曾经经历，与“一直在”不搭配。正确：“蒸发着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
