INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25276, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "坎儿井是一种在地下挖的水渠，用来把水引到田地里。", "primary_collocate": null, "pronunciation": "kǎn ér jǐng", "ipa": "kʰan˨˩ ɚ˧˥ tɕiŋ˨˩", "syllable_count": 3, "sentences": [{"text": "人们在地下挖了一条坎儿井。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坎儿井的水流进了田地。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坎儿井是新疆人想出来的好办法。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书上读到过坎儿井。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坎儿井很长，水从山下流到村子。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了坎儿井，农民不用到远处挑水。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坎儿井里的水又凉又干净。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了坎儿井的照片。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修坎儿井要挖很多土。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子旁边的坎儿井，已经用了几百年。", "target_word": "坎儿井", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "坎兒井", "label": "繁体"}], "register": "中性", "sense_fingerprint": "地下挖的水渠，把水引到田地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c4f15-32da-40c3-b527-73291bf6ea7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25276, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坎儿井", "is_correct": true, "explanation": "正确。“挖了一条坎儿井”指在地下挖出的水渠，与句意相符。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不是人在地下挖出来的，与“挖”的动作不符。"}, {"text": "绳子", "is_correct": false, "explanation": "语义：绳子是编成或搓成的，不是挖出来的。"}, {"text": "裤子", "is_correct": false, "explanation": "搭配：“挖”不搭配“裤子”，裤子不是挖掘的对象。"}], "explanations": {"坎儿井": "正确。“挖了一条坎儿井”指在地下挖出的水渠，与句意相符。", "鱼": "语义：鱼不是人在地下挖出来的，与“挖”的动作不符。", "绳子": "语义：绳子是编成或搓成的，不是挖出来的。", "裤子": "搭配：“挖”不搭配“裤子”，裤子不是挖掘的对象。"}, "sentence_index": 0, "correct_answer": "坎儿井"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在书上读到过坎儿井，它每天载着乘客穿过城市。", "explanation": "这里应该用〈地铁〉。地铁是载着乘客穿过城市的交通工具；坎儿井是引水灌溉的水渠，不能载客。"}, {"text": "坎儿井把生活污水排出去。", "explanation": "这里应该用〈下水道〉。坎儿井是用来引水灌溉的，不是排污的管道。"}, {"text": "坎儿井里存着冬天的菜。", "explanation": "这里应该用〈地窖〉。坎儿井是引水的水渠，不用来存放蔬菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2635fe9d-2c73-4a0d-8255-fc78d15f067c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25276, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坎儿井", "is_correct": true, "explanation": "正确。坎儿井是地下的水渠，水清凉干净，与句意相符。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线是输电用的导线，里面没有可以饮用的水，“又凉又干净的水”说不通。"}, {"text": "帽子", "is_correct": false, "explanation": "语义：帽子不是储水的地方，“帽子里的水又凉又干净”说不通。"}, {"text": "衣柜", "is_correct": false, "explanation": "搭配：衣柜不是储水的地方，“衣柜里的水”不成立。"}], "explanations": {"坎儿井": "正确。坎儿井是地下的水渠，水清凉干净，与句意相符。", "电线": "语义：电线是输电用的导线，里面没有可以饮用的水，“又凉又干净的水”说不通。", "帽子": "语义：帽子不是储水的地方，“帽子里的水又凉又干净”说不通。", "衣柜": "搭配：衣柜不是储水的地方，“衣柜里的水”不成立。"}, "sentence_index": 6, "correct_answer": "坎儿井"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "坎儿井是一种在山顶上修的高塔。", "explanation": "这里应该用〈烽火台〉。烽火台是建在山顶、用来传递军情的高台；坎儿井是地下挖的水渠，不是地面上的高塔。"}, {"text": "坎儿井把烟排到天上。", "explanation": "这里应该用〈烟囱〉。烟囱是排烟的管道；坎儿井是引水的水渠，不能排烟。"}, {"text": "坎儿井让火车穿过山。", "explanation": "这里应该用〈隧道〉。隧道是为让火车穿过山体挖的通道；坎儿井是引水的水渠，不能让火车通过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2635fe9d-2c73-4a0d-8255-fc78d15f067c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人们在地下修了好一条坎儿井。", "corrected_sentence": "老人们在地下修好了一条坎儿井。", "error_description": "补语位置错误：“修好”是动补结构，不能拆成“修了好”，应为“修好了一条坎儿井”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2635fe9d-2c73-4a0d-8255-fc78d15f067c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去新疆参观过一只坎儿井。", "corrected_sentence": "他去新疆参观过一条坎儿井。", "error_description": "量词错误：坎儿井的量词应为“条”，“只”用于动物等，不能用于坎儿井，应为“参观过一条坎儿井”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2635fe9d-2c73-4a0d-8255-fc78d15f067c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25280, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25280, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25280, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把水送到别的地方。", "primary_collocate": null, "pronunciation": "shū shuǐ", "ipa": "ʂu˥ ʂweɪ˨˩", "syllable_count": 2, "sentences": [{"text": "管子坏了，没法给我们家输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根粗管子负责给小区输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水厂每天给城里的人家输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里新装了管道，可以输水了。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水泵一开，水管就开始输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的水渠向山下输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条旧渠已经不能输水了。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在检查管道能不能输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打开阀门，开始向田里输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条管道一天二十四小时输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "输水管", "label": "复合"}, {"form": "输水了", "label": "体标"}, {"form": "輸水", "label": "繁体"}], "register": "书面", "sense_fingerprint": "管子、水渠或水厂把水送到别处，日常供水场景", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8873e8b-ebaa-461c-94d4-dce7b35fae3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25280, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "输水", "is_correct": true, "explanation": "输水（shū shuǐ）：通过管道或渠道把水送到别处。"}, {"text": "注水", "is_correct": false, "explanation": "zhù（第四声）与 shū（第一声）声母和声调都不同，意思是把水注入。"}, {"text": "需水", "is_correct": false, "explanation": "xū 与 shū 声母不同（x 与 sh），意思是需要水。"}, {"text": "失水", "is_correct": false, "explanation": "shī 与 shū 韵母不同（i 与 u），意思是失去水分。"}], "explanations": {"输水": "输水（shū shuǐ）：通过管道或渠道把水送到别处。", "注水": "zhù（第四声）与 shū（第一声）声母和声调都不同，意思是把水注入。", "需水": "xū 与 shū 声母不同（x 与 sh），意思是需要水。", "失水": "shī 与 shū 韵母不同（i 与 u），意思是失去水分。"}, "sentence_index": null, "correct_answer": "输水"}, "level_3": {"options": [{"text": "输水", "is_correct": true, "explanation": "正确：“没法给我们家输水”指管子无法向家里送水，与管子坏了的语境相符。"}, {"text": "修车", "is_correct": false, "explanation": "语义：“修车”与管子坏了、给家里送水的语境无关。"}, {"text": "放映", "is_correct": false, "explanation": "语义：“放映”指播放影像，与管子和送水的语境不符。"}, {"text": "剪头发", "is_correct": false, "explanation": "配价：“剪头发”需要人作施事和受事，“我们家”指房屋，不能被剪头发。"}], "explanations": {"输水": "正确：“没法给我们家输水”指管子无法向家里送水，与管子坏了的语境相符。", "修车": "语义：“修车”与管子坏了、给家里送水的语境无关。", "放映": "语义：“放映”指播放影像，与管子和送水的语境不符。", "剪头发": "配价：“剪头发”需要人作施事和受事，“我们家”指房屋，不能被剪头发。"}, "sentence_index": 0, "correct_answer": "输水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天用喷壶给院子里的花输水。", "explanation": "这里应该用〈喷〉。输水指用管道、渠道大批量运送水，喷壶少量喷水要说喷水。"}, {"text": "护士给病人输水。", "explanation": "这里应该用〈输液〉。给病人静脉注入液体要说输液，输水指用管道运送水。"}, {"text": "他每天去井边输水。", "explanation": "这里应该用〈挑水〉。输水指通过管道、渠道等大批量送水，一个人用扁担把水挑回家要说挑水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "输水", "is_correct": true, "explanation": "正确：“不能输水了”指旧渠道已无法送水，与渠道的语境相符。"}, {"text": "行走", "is_correct": false, "explanation": "语义：渠道是水利设施，不能行走，与“旧渠”的语境不符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：渠道不能唱歌，“不能唱歌了”与水利设施的语境无关。"}, {"text": "通电", "is_correct": false, "explanation": "搭配：“通电”指接通电流，一般不用于渠道，不说“渠道不能通电了”。"}], "explanations": {"输水": "正确：“不能输水了”指旧渠道已无法送水，与渠道的语境相符。", "行走": "语义：渠道是水利设施，不能行走，与“旧渠”的语境不符。", "唱歌": "语义：渠道不能唱歌，“不能唱歌了”与水利设施的语境无关。", "通电": "搭配：“通电”指接通电流，一般不用于渠道，不说“渠道不能通电了”。"}, "sentence_index": 6, "correct_answer": "输水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台冰箱一天二十四小时输水。", "explanation": "这里误把〈输水〉用于冰箱作主语，把“输水”当成了器物自行送水的义项；输水的施事须是管道、渠道等输水设施，冰箱不是。"}, {"text": "这把雨伞一天二十四小时输水。", "explanation": "这里误把〈输水〉用于雨伞作主语，把“输水”当成了器物自行送水的义项；输水的施事须是管道、渠道等输水设施，雨伞不是。"}, {"text": "这本书一天二十四小时输水。", "explanation": "这里误把〈输水〉用于书作主语，把“输水”当成了器物自行送水的义项；输水的施事须是管道、渠道等输水设施，书不是。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里水泵一开，管子就输水着。", "corrected_sentence": "夜里水泵一开，管子就输水了。", "error_description": "错误：“一……就”表示动作紧接着完成，完成义要用“了”，“着”表示动作持续，不宜用在这里。正确：“输水了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条老管道以前输水过。", "corrected_sentence": "这条老管道以前输过水。", "error_description": "错误：经历体“过”位置错误，应紧跟动词。正确：“输过水”，“过”要放在动词“输”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
