INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "水和水的运动、变化。", "primary_collocate": null, "pronunciation": "shuǐ wén", "ipa": "ʂweɪ˨˩ wən˧˥", "syllable_count": 2, "sentences": [{"text": "这里的水文很复杂，船要小心走。", "target_word": "水文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究水文，可以帮助我们预防洪水。", "target_word": "水文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先看看这条河的水文，再决定去不去。", "target_word": "水文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气一变，湖里的水文也会变。", "target_word": "水文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人熟悉家乡的水文，知道哪里水深。", "target_word": "水文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水文会随着季节发生变化。", "target_word": "水文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天记录这条河的水文变化。", "target_word": "水文", "complexity_tier": "T3", "furigana": "shuǐwén", "sentence_source": "generated"}, {"text": "了解水文，对修水库很重要。", "target_word": "水文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的水文和冬天很不一样。", "target_word": "水文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用新仪器测量海洋的水文。", "target_word": "水文", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "水文站", "label": "复合"}, {"form": "水文地质", "label": "复合"}], "register": "书面", "sense_fingerprint": "水以及水的运动和变化情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdfd7111-582d-4855-ba6d-a26472189441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25290, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水文", "is_correct": true, "explanation": "水文指水和水的运动、变化，地方的水文复杂，船就要小心，与句意相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格与船要小心走无关，不能说“价格很复杂”。"}, {"text": "作息", "is_correct": false, "explanation": "语义：作息指生活起居的安排，与船行的安全无关。"}, {"text": "电压", "is_correct": false, "explanation": "语义：电压是电路中的电势差，与河道的水况无关，不能用来描述这里的情况。"}], "explanations": {"水文": "水文指水和水的运动、变化，地方的水文复杂，船就要小心，与句意相符。", "价格": "语义：价格与船要小心走无关，不能说“价格很复杂”。", "作息": "语义：作息指生活起居的安排，与船行的安全无关。", "电压": "语义：电压是电路中的电势差，与河道的水况无关，不能用来描述这里的情况。"}, "sentence_index": 0, "correct_answer": "水文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湖水的水文变差了，鱼也少了。", "explanation": "这里应该用〈水质〉。水文指水的运动和变化，说水好坏要用水质。"}, {"text": "湖水的水文升高了一米。", "explanation": "这里应该用〈水位〉。水文不能用数值衡量，水位才能升高一米。"}, {"text": "这口井的水文很大，够全村用。", "explanation": "这里应该用〈水量〉。水文指水的运动和变化，不指水的多少，说水多要用水量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca365746-bd7c-4c8d-9d69-e3a51036c268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水文", "is_correct": true, "explanation": "水文指水的运动和变化，记录这条河的水文变化，说的正是这个意思。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格会涨跌，但河流记录的对象不是价格，与水文无关。"}, {"text": "名字", "is_correct": false, "explanation": "语义：记录的是水的变化，河流的名字不会变化，也与水文无关。"}, {"text": "字体", "is_correct": false, "explanation": "语义：字体指字的书写形式，与河流的变化无关。"}], "explanations": {"水文": "水文指水的运动和变化，记录这条河的水文变化，说的正是这个意思。", "价格": "语义：价格会涨跌，但河流记录的对象不是价格，与水文无关。", "名字": "语义：记录的是水的变化，河流的名字不会变化，也与水文无关。", "字体": "语义：字体指字的书写形式，与河流的变化无关。"}, "sentence_index": 6, "correct_answer": "水文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海底的水文很重，潜水员压得喘不过气。", "explanation": "这里应该用〈水压〉。水文指水的运动和变化，不指水对物体的压力，水的压力要用水压。"}, {"text": "这片海的水文很低，游泳的人很少。", "explanation": "这里应该用〈水温〉。水温指水的冷热，可以说“低”，水文不指冷热。"}, {"text": "这片海的水文很咸，岸边的草都长不好。", "explanation": "这里应该用〈海水〉。水文指水的运动和变化，不指水的咸淡，说海水咸要用海水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca365746-bd7c-4c8d-9d69-e3a51036c268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要了解了水文，才能避免洪水。", "corrected_sentence": "我们要了解水文，才能避免洪水。", "error_description": "“要”表示需要或打算，其后的动词不能带“了”。应说“要了解水文”，去掉动词“了解”后的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca365746-bd7c-4c8d-9d69-e3a51036c268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条河的水文变化的很快。", "corrected_sentence": "这条河的水文变化得很快。", "error_description": "程度补语要用“得”引出，说“变化得很快”。“的”是定语标记，不能用来引出补语，这里应把“的”改为“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca365746-bd7c-4c8d-9d69-e3a51036c268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
