INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25292, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "典范是很好的榜样，大家要学习它。", "primary_collocate": null, "pronunciation": "diǎn fàn", "ipa": "tjɛn˨˩ fan˥˩", "syllable_count": 2, "sentences": [{"text": "他是我们班同学学习的典范。", "target_word": "典范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的服务是行业的典范。", "target_word": "典范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷勤劳一生，是全家人的典范。", "target_word": "典范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街很干净，是全市的典范。", "target_word": "典范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她工作认真，成了新同事的典范。", "target_word": "典范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师是我心中的典范。", "target_word": "典范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村的做法是大家学习的典范。", "target_word": "典范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的字写得好，是书法的典范。", "target_word": "典范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要向他学习，他是好学生的典范。", "target_word": "典范", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所学校的环保做法成了各校的典范。", "target_word": "典范", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "典範", "label": "繁体"}], "register": "通用", "sense_fingerprint": "值得大家学习的好榜样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdfd7111-582d-4855-ba6d-a26472189441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25292, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "典范", "is_correct": true, "explanation": "典范指值得学习的榜样，与“学习的”搭配，表示同学可以效仿的对象。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾指废弃物，不能作为同学学习的对象。"}, {"text": "废品", "is_correct": false, "explanation": "语义：废品指无用的废旧物，与“值得学习”的含义相反。"}, {"text": "噪音", "is_correct": false, "explanation": "搭配：“学习的”后接的应是可以模仿的对象，“噪音”不是可以学习的对象。"}], "explanations": {"典范": "典范指值得学习的榜样，与“学习的”搭配，表示同学可以效仿的对象。", "垃圾": "语义：垃圾指废弃物，不能作为同学学习的对象。", "废品": "语义：废品指无用的废旧物，与“值得学习”的含义相反。", "噪音": "搭配：“学习的”后接的应是可以模仿的对象，“噪音”不是可以学习的对象。"}, "sentence_index": 0, "correct_answer": "典范"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的典范比我高半个头。", "explanation": "这里应该用〈身高〉。典范指值得效仿的榜样，不能指人的身高。"}, {"text": "这条街的典范有十米宽，两辆车能并排开过。", "explanation": "这里应该用〈宽度〉。典范指值得效仿的榜样，描述路面宽窄要用宽度。"}, {"text": "这间屋子里的沙发颜色很典范，一看就是红木。", "explanation": "这里应该用〈典型〉。典范指值得效仿的榜样，形容有代表性的外观特征要用典型。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca365746-bd7c-4c8d-9d69-e3a51036c268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25292, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "典范", "is_correct": true, "explanation": "典范指值得学习的榜样，与“大家学习的”搭配，表示值得效仿的做法。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是供玩耍的物品，不能作为大家学习的对象。"}, {"text": "疟疾", "is_correct": false, "explanation": "语义：疟疾是一种疾病，与“值得学习的做法”的含义相反。"}, {"text": "煤渣", "is_correct": false, "explanation": "搭配：“学习”的对象应是可以效仿的做法或榜样，煤渣不能构成学习对象。"}], "explanations": {"典范": "典范指值得学习的榜样，与“大家学习的”搭配，表示值得效仿的做法。", "玩具": "语义：玩具是供玩耍的物品，不能作为大家学习的对象。", "疟疾": "语义：疟疾是一种疾病，与“值得学习的做法”的含义相反。", "煤渣": "搭配：“学习”的对象应是可以效仿的做法或榜样，煤渣不能构成学习对象。"}, "sentence_index": 6, "correct_answer": "典范"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次问卷抽取了三百个典范。", "explanation": "这里应该用〈样本〉。典范指值得效仿的榜样，抽取出来用于统计的对象要用样本。"}, {"text": "那架飞机的典范做得很精细。", "explanation": "这里应该用〈模型〉。典范指榜样，缩小仿制的实物要用模型。"}, {"text": "这只蝴蝶的典范被放在玻璃柜里。", "explanation": "这里应该用〈标本〉。典范指榜样，制成的动物实物要用标本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca365746-bd7c-4c8d-9d69-e3a51036c268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25292, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位厨师是这家饭店的一本典范。", "corrected_sentence": "这位厨师是这家饭店的一个典范。", "error_description": "错误：量词用了“本”。典范是抽象名词，量词应用“个”，“本”用于书籍。正确形式：“一个典范”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca365746-bd7c-4c8d-9d69-e3a51036c268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25292, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告是工作效率典范。", "corrected_sentence": "这份报告是工作效率的典范。", "error_description": "错误：漏掉了“的”。名词前的定语“工作效率”后要加“的”，应为“工作效率的典范”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca365746-bd7c-4c8d-9d69-e3a51036c268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
