INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25294, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不同的东西可以分成不同的组，每组就是一个类型。", "primary_collocate": null, "pronunciation": "lèi xíng", "ipa": "lei˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "动物可以分成好几个类型。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这三个类型各有各的特点。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的衣服是哪个类型的？", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把练习分成两种类型。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店里的书按类型放在不同的架子上。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个表格有四个类型。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的汽车属于同一个类型。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先看看这个类型有什么特点。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影的类型太多，我不知道选哪个。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些问题可以归为三个类型。", "target_word": "类型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}, {"form": "类型学", "label": "复合"}], "register": "中性", "sense_fingerprint": "把事物分组后，其中的每一组", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6f39da0-9e88-4222-8183-2237ea8e061c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25294, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "类型", "is_correct": true, "explanation": "类型：分组后的每一组，与“分成好几个”相合，句意通顺。"}, {"text": "房间", "is_correct": false, "explanation": "语义：动物不能被分成“房间”，句意不通。"}, {"text": "年份", "is_correct": false, "explanation": "语义：“年份”不是分组的单位，句意荒谬。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”应用量词“种”，不能说“几个天气”。"}], "explanations": {"类型": "类型：分组后的每一组，与“分成好几个”相合，句意通顺。", "房间": "语义：动物不能被分成“房间”，句意不通。", "年份": "语义：“年份”不是分组的单位，句意荒谬。", "天气": "搭配：“天气”应用量词“种”，不能说“几个天气”。"}, "sentence_index": 0, "correct_answer": "类型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班的类型是四十人。", "explanation": "这里应该用〈人数〉。类型指分组后的一组，不能用来表示人的数量。"}, {"text": "这块地的类型很大。", "explanation": "这里应该用〈面积〉。类型不能说大小，表示大小要用面积。"}, {"text": "这根绳子的类型是五米。", "explanation": "这里应该用〈长度〉。类型不能表示长短，应说长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9ae051-7401-4cbc-995b-8c9389f3cbb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25294, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "类型", "is_correct": true, "explanation": "类型：汽车所属的一组，句意通顺。"}, {"text": "房子", "is_correct": false, "explanation": "语义：汽车不属于“房子”这一类，句意荒谬。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不是可以归属的分组，汽车不能属于“时间”，句意荒谬。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“同一个年龄”不能用来指车辆所属的分组。"}], "explanations": {"类型": "类型：汽车所属的一组，句意通顺。", "房子": "语义：汽车不属于“房子”这一类，句意荒谬。", "时间": "语义：“时间”不是可以归属的分组，汽车不能属于“时间”，句意荒谬。", "年龄": "搭配：“同一个年龄”不能用来指车辆所属的分组。"}, "sentence_index": 6, "correct_answer": "类型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱苹果的类型是十公斤。", "explanation": "这里应该用〈重量〉。类型指种类，表示轻重要用重量。"}, {"text": "这辆车的类型是每小时一百公里。", "explanation": "这里应该用〈速度〉。类型指种类，表示快慢要用速度。"}, {"text": "这台电视的类型是五十寸。", "explanation": "这里应该用〈尺寸〉。类型指种类，表示屏幕大小要用尺寸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9ae051-7401-4cbc-995b-8c9389f3cbb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批零件可以分成三只类型。", "corrected_sentence": "这批零件可以分成三种类型。", "error_description": "错误形式：“类型”前用了量词“只”。正确形式：“三种类型”。原因：“只”用于动物等，修饰“类型”应用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9ae051-7401-4cbc-995b-8c9389f3cbb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些报告可以分成两类型。", "corrected_sentence": "这些报告可以分成两种类型。", "error_description": "错误形式：“类型”前漏掉了量词。正确形式：“两种类型”。原因：数词与“类型”之间需要量词“种”，漏掉后句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9ae051-7401-4cbc-995b-8c9389f3cbb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25296, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca365746-bd7c-4c8d-9d69-e3a51036c268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
