INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25296, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "利用水来为人们做事，比如浇地、发电。", "primary_collocate": null, "pronunciation": "shuǐ lì", "ipa": "ʂweɪ̯˨˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这个地方的水利很好，田里不缺水。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里新修了水利，今年不怕干旱。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水利可以浇地，也可以发电。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片地靠水利灌溉，年年都有好收成。", "target_word": "水利", "complexity_tier": "T3", "furigana": "shuǐ lì", "sentence_source": "generated"}, {"text": "河边的水利帮农民解决了大问题。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河有很好的水利条件。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区要发展水利，农民才有水浇地。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用水利浇地，秋天收了很多粮食。", "target_word": "水利", "complexity_tier": "T3", "furigana": "shuǐ lì", "sentence_source": "generated"}, {"text": "水利让这片干地变成了好田。", "target_word": "水利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里靠水利发电，家里晚上有了电灯。", "target_word": "水利", "complexity_tier": "T3", "furigana": "shuǐ lì", "sentence_source": "generated"}], "morphological_forms": [{"form": "水利工程", "label": "复合"}, {"form": "水利设施", "label": "复合"}], "register": "通用", "sense_fingerprint": "用水浇地发电为人做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdfd7111-582d-4855-ba6d-a26472189441') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25296, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水利", "is_correct": true, "explanation": "水利：利用水来为人做事，如浇地、发电，是正确答案。"}, {"text": "水里", "is_correct": false, "explanation": "shuǐ lǐ（第三声）与 shuǐ lì（第四声）声调不同，意思是“在水中”。"}, {"text": "税吏", "is_correct": false, "explanation": "shuì lì（第四声）与 shuǐ lì 的第一个音节声调不同，意思是“收税的官吏”。"}, {"text": "水梨", "is_correct": false, "explanation": "shuǐ lí（第二声）与 shuǐ lì 声调不同，意思是一种梨。"}], "explanations": {"水利": "水利：利用水来为人做事，如浇地、发电，是正确答案。", "水里": "shuǐ lǐ（第三声）与 shuǐ lì（第四声）声调不同，意思是“在水中”。", "税吏": "shuì lì（第四声）与 shuǐ lì 的第一个音节声调不同，意思是“收税的官吏”。", "水梨": "shuǐ lí（第二声）与 shuǐ lì 声调不同，意思是一种梨。"}, "sentence_index": null, "correct_answer": "水利"}, "level_3": {"options": [{"text": "水利", "is_correct": true, "explanation": "水利：作主语，指利用水做事的条件，与“田里不缺水”一致。"}, {"text": "干旱", "is_correct": false, "explanation": "语义：“干旱”与“田里不缺水”矛盾，不能说“干旱很好”。"}, {"text": "噪音", "is_correct": false, "explanation": "搭配：“噪音”只能说大小，不能用“很好”来评价。"}, {"text": "洪水", "is_correct": false, "explanation": "语义：“洪水”会淹没农田，与“田里不缺水”的语境相反。"}], "explanations": {"水利": "水利：作主语，指利用水做事的条件，与“田里不缺水”一致。", "干旱": "语义：“干旱”与“田里不缺水”矛盾，不能说“干旱很好”。", "噪音": "搭配：“噪音”只能说大小，不能用“很好”来评价。", "洪水": "语义：“洪水”会淹没农田，与“田里不缺水”的语境相反。"}, "sentence_index": 0, "correct_answer": "水利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把伞很水利，下雨天带着很好。", "explanation": "这里应该用〈方便〉。水利指利用水浇地、发电等，不能用来形容伞好不好用。"}, {"text": "这辆汽车靠水利跑得很快。", "explanation": "这里应该用〈发动机〉。水利指利用水浇地、发电等，不能作汽车的动力来源。"}, {"text": "孩子们在水利里游泳，玩得很开心。", "explanation": "这里应该用〈水域〉。水利指利用水做事，不指水的区域，不能说“在水利里游泳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca365746-bd7c-4c8d-9d69-e3a51036c268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水利", "is_correct": true, "explanation": "水利：作“发展”的宾语，指可以发展的水利事业，与“农民才有水浇地”的目的一致。"}, {"text": "荒漠", "is_correct": false, "explanation": "语义：“荒漠”不能作“发展”的对象，与“农民才有水浇地”的目标矛盾。"}, {"text": "灾害", "is_correct": false, "explanation": "搭配：“发展灾害”搭配不当，与“农民才有水浇地”的因果不符。"}, {"text": "洪涝", "is_correct": false, "explanation": "语义：“洪涝”造成水患，与“农民才有水浇地”的目的相反。"}], "explanations": {"水利": "水利：作“发展”的宾语，指可以发展的水利事业，与“农民才有水浇地”的目的一致。", "荒漠": "语义：“荒漠”不能作“发展”的对象，与“农民才有水浇地”的目标矛盾。", "灾害": "搭配：“发展灾害”搭配不当，与“农民才有水浇地”的因果不符。", "洪涝": "语义：“洪涝”造成水患，与“农民才有水浇地”的目的相反。"}, "sentence_index": 6, "correct_answer": "水利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段音乐的水利很好，听了很舒服。", "explanation": "这里应该用〈旋律〉。水利指利用水做事，不能用来评价音乐的好坏。"}, {"text": "他的水利很好，每天能跑十公里。", "explanation": "水利指利用水来做事，不能用来形容人的体能。"}, {"text": "这本书的水利很好，我一口气读完了。", "explanation": "这里应该用〈好看〉。水利指利用水做事，不能用来评价书的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca365746-bd7c-4c8d-9d69-e3a51036c268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村的一把水利很好，田里不缺水。", "corrected_sentence": "这个村的水利很好，田里不缺水。", "error_description": "“水利”前不能加量词“把”，“把”多用于有柄的器具；应去掉“一把”，说“这个村的水利很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca365746-bd7c-4c8d-9d69-e3a51036c268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民把水利浇地，今年收了很多粮食。", "corrected_sentence": "农民用水利浇地，今年收了很多粮食。", "error_description": "“把”字句要求宾语被处置，“水利”是工具，应用“用”引出，写作“用水利浇地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca365746-bd7c-4c8d-9d69-e3a51036c268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
