INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25298, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "跟着某个规则或做法去做。", "primary_collocate": null, "pronunciation": "yī xún", "ipa": "i˥ ɕyn˧˥", "syllable_count": 2, "sentences": [{"text": "公司依循旧规办事。", "target_word": "依循", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要依循法律处理问题。", "target_word": "依循", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他依循老师的方法学习。", "target_word": "依循", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家依循规定排队进场。", "target_word": "依循", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店依循传统做法做面包。", "target_word": "依循", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生依循流程检查病人。", "target_word": "依循", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校依循国家的规定放假。", "target_word": "依循", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他依循父亲留下的规矩做人。", "target_word": "依循", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人依循说明书安装机器。", "target_word": "依循", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直依循着老办法做事。", "target_word": "依循", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "依循了", "label": "完成体"}, {"form": "依循着", "label": "持续体"}], "register": "书面", "sense_fingerprint": "按照已有的规则、惯例或做法行事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6f39da0-9e88-4222-8183-2237ea8e061c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25298, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "依循", "is_correct": true, "explanation": "依循：遵照旧规行事，与句意一致。"}, {"text": "制定", "is_correct": false, "explanation": "语义：“制定”是订立新规则，与“旧规”矛盾，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能以“规”为宾语，说“吃旧规办事”不成话。"}, {"text": "研发", "is_correct": false, "explanation": "搭配：“研发”的对象是技术或产品，不能用于“旧规”。"}], "explanations": {"依循": "依循：遵照旧规行事，与句意一致。", "制定": "语义：“制定”是订立新规则，与“旧规”矛盾，句意不通。", "吃": "搭配：“吃”不能以“规”为宾语，说“吃旧规办事”不成话。", "研发": "搭配：“研发”的对象是技术或产品，不能用于“旧规”。"}, "sentence_index": 0, "correct_answer": "依循"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们依循大家的力量完成了任务。", "explanation": "这里应该用〈依靠〉。依循指遵照规则行事，凭借他人的力量要用依靠。"}, {"text": "孩子依循玩具，不愿放手。", "explanation": "这里应该用〈依恋〉。依恋指对人或物难以割舍，依循不能表示这种情感。"}, {"text": "他依循着父亲的权势横行乡里。", "explanation": "这里应该用〈依仗〉。依仗指倚仗权势，依循表示遵照规则，两者不能替换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9ae051-7401-4cbc-995b-8c9389f3cbb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25298, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "依循", "is_correct": true, "explanation": "依循：遵照国家规定放假，句意通顺。"}, {"text": "决定", "is_correct": false, "explanation": "语义：“决定”的主体应是制定规定的一方，学校不能决定国家的规定，句意不通。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”不能以“规定”为宾语，句意荒谬。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”不能以“规定”为宾语，句意荒谬。"}], "explanations": {"依循": "依循：遵照国家规定放假，句意通顺。", "决定": "语义：“决定”的主体应是制定规定的一方，学校不能决定国家的规定，句意不通。", "咬": "搭配：“咬”不能以“规定”为宾语，句意荒谬。", "烧": "搭配：“烧”不能以“规定”为宾语，句意荒谬。"}, "sentence_index": 6, "correct_answer": "依循"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个项目依循政府的支持进行。", "explanation": "这里应该用〈依托〉。依循指遵照规则，凭借政府的支持要用依托。"}, {"text": "她依循勤奋考上了大学。", "explanation": "这里应该用〈凭借〉。依循指遵照规则，凭借指依靠某种条件，此处应说凭借勤奋。"}, {"text": "现代人太依循手机了。", "explanation": "这里应该用〈依赖〉。依循指遵照规则，依赖指过分依靠某物，此处不能用依循。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9ae051-7401-4cbc-995b-8c9389f3cbb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25298, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们依循在公司的制度工作。", "corrected_sentence": "我们依循公司的制度工作。", "error_description": "错误形式：“依循”后多加了介词“在”。正确形式：“我们依循公司的制度工作”。原因：“依循”直接带宾语，不需要“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9ae051-7401-4cbc-995b-8c9389f3cbb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25298, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他始终把依循旧例行事。", "corrected_sentence": "他始终依循旧例行事。", "error_description": "错误形式：在“依循”前多加了“把”。正确形式：“他始终依循旧例行事”。原因：“把”字句要求“把+宾语+动词”，此处“依循旧例”不能作“把”的宾语，应删去“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9ae051-7401-4cbc-995b-8c9389f3cbb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
