INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25300, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或身体做事，比如搬东西、种地。", "primary_collocate": null, "pronunciation": "láo dòng", "ipa": "lɑʊ˧˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷每天在地里劳动。", "target_word": "劳动", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们周末在学校里劳动。", "target_word": "劳动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他劳动了一上午，累极了。", "target_word": "劳动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们也要学会劳动。", "target_word": "劳动", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家一起劳动，很快就干完了。", "target_word": "劳动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在花园里劳动着。", "target_word": "劳动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "劳动以后，我们洗手吃饭。", "target_word": "劳动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢劳动，不爱坐着不动。", "target_word": "劳动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在田里劳动，从早到晚。", "target_word": "劳动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人身体好，还能自己劳动。", "target_word": "劳动", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "劳动了", "label": "体标"}, {"form": "劳动着", "label": "体标"}, {"form": "劳动过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用手或身体做事，如搬东西、种地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6f39da0-9e88-4222-8183-2237ea8e061c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25300, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "劳动", "is_correct": true, "explanation": "“劳动”指用身体干活，“在地里劳动”符合句意。"}, {"text": "上课", "is_correct": false, "explanation": "语义：上课是在教室学习，不能在地里进行。"}, {"text": "写字", "is_correct": false, "explanation": "语义：写字是书面活动，与在地里做事的语境不符。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“在地里洗澡”不符合常规的场所搭配。"}], "explanations": {"劳动": "“劳动”指用身体干活，“在地里劳动”符合句意。", "上课": "语义：上课是在教室学习，不能在地里进行。", "写字": "语义：写字是书面活动，与在地里做事的语境不符。", "洗澡": "搭配：“在地里洗澡”不符合常规的场所搭配。"}, "sentence_index": 0, "correct_answer": "劳动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在公园里劳动身体。", "explanation": "这里应该用〈锻炼〉。“劳动”指用身体干活，锻炼身体是为了健康，不叫劳动。"}, {"text": "他躺在床上劳动，不想动。", "explanation": "这里应该用〈休息〉。“劳动”指用身体干活，躺着不动不能说劳动。"}, {"text": "他在沙滩上晒太阳，还说这是劳动。", "explanation": "这里应该用〈休闲〉。“劳动”指用手或身体干活，晒太阳是休闲，不算劳动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9ae051-7401-4cbc-995b-8c9389f3cbb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25300, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "劳动", "is_correct": true, "explanation": "“劳动以后”指干完活之后，接着“洗手吃饭”符合常理。"}, {"text": "劳动者", "is_correct": false, "explanation": "词性：“劳动者”是名词，不能充当“以后”前的动作，句意不通。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：吃完午饭再“洗手吃饭”，重复矛盾，句意不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包以后”无法表示动作的先后，句意荒谬。"}], "explanations": {"劳动": "“劳动以后”指干完活之后，接着“洗手吃饭”符合常理。", "劳动者": "词性：“劳动者”是名词，不能充当“以后”前的动作，句意不通。", "午饭": "语义：吃完午饭再“洗手吃饭”，重复矛盾，句意不通。", "书包": "语义：“书包以后”无法表示动作的先后，句意荒谬。"}, "sentence_index": 6, "correct_answer": "劳动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在舞台上劳动，唱得很好听。", "explanation": "这里应该用〈表演〉。“劳动”指用手或身体干活，舞台上的表演不算劳动。"}, {"text": "孩子们在操场上劳动，跑来跑去。", "explanation": "这里应该用〈玩耍〉。“劳动”指干活，跑来跑去的游戏不算劳动。"}, {"text": "他晚上很早就劳动。", "explanation": "这里应该用〈睡觉〉。“劳动”指做事干活，睡觉不能说劳动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9ae051-7401-4cbc-995b-8c9389f3cbb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶每天在田里劳动了。", "corrected_sentence": "奶奶每天在田里劳动。", "error_description": "表示习惯性的动作不加“了”。“每天”与“了”（表示完成）相冲突，应删去“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9ae051-7401-4cbc-995b-8c9389f3cbb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老大爷每天早上菜园里劳动。", "corrected_sentence": "老大爷每天早上在菜园里劳动。", "error_description": "处所短语前缺少介词“在”。应说“在菜园里劳动”，不能省略“在”直接说“菜园里劳动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9ae051-7401-4cbc-995b-8c9389f3cbb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
