INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25306, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你可以用这个东西的权利。", "primary_collocate": null, "pronunciation": "shǐ yòng quán", "ipa": "ʂɻ̩˨˩˦ jʊŋ˥˩ tɕʰɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "这个房间的使用权是我的。", "target_word": "使用权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友给了我他的车的使用权。", "target_word": "使用权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给每人一台电脑的使用权。", "target_word": "使用权", "complexity_tier": "T3", "furigana": "gōngsī gěi měi rén yī tái diànnǎo de shǐyòngquán。", "sentence_source": "generated"}, {"text": "你有这台打印机的使用权吗？", "target_word": "使用权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把书房的使用权给了弟弟。", "target_word": "使用权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有密码，就没有网络的使用权。", "target_word": "使用权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房东只给我们厨房的使用权。", "target_word": "使用权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会员才有游泳池的使用权。", "target_word": "使用权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆自行车的使用权，我们两个人都有。", "target_word": "使用权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了学生教室的使用权。", "target_word": "使用权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "土地使用权", "label": "复合"}], "register": "中性", "sense_fingerprint": "被允许使用某样东西的权利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6f39da0-9e88-4222-8183-2237ea8e061c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25306, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使用权", "is_correct": true, "explanation": "正确：“这个房间的使用权是我的”，表示我有使用这个房间的权利，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的属性，不能说“是我的”这样归属于某人。"}, {"text": "味道", "is_correct": false, "explanation": "语义：房间的味道是气味，不是可以归属于某人的东西。"}, {"text": "高度", "is_correct": false, "explanation": "配价：“是我的”要求可以归属的事物，“高度”是数值属性，不能这样用。"}], "explanations": {"使用权": "正确：“这个房间的使用权是我的”，表示我有使用这个房间的权利，符合句意。", "颜色": "语义：颜色是事物的属性，不能说“是我的”这样归属于某人。", "味道": "语义：房间的味道是气味，不是可以归属于某人的东西。", "高度": "配价：“是我的”要求可以归属的事物，“高度”是数值属性，不能这样用。"}, "sentence_index": 0, "correct_answer": "使用权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台打印机的使用权很快，一分钟就能打印完。", "explanation": "使用权是抽象的权利，不能形容速度；打印的速度才说“快”。"}, {"text": "他买了两件使用权。", "explanation": "量词错误：使用权应该用〈项〉，“件”不能用于权利。"}, {"text": "我把这台打印机的使用权放进了书包。", "explanation": "使用权是抽象的权利，不是有形物品，不能放进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9ae051-7401-4cbc-995b-8c9389f3cbb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使用权", "is_correct": true, "explanation": "正确：“房东只给我们厨房的使用权”，表示只给我们使用厨房的权利，符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "语义：厨房的声音不能“给”别人，这个词不能用于这里。"}, {"text": "温度", "is_correct": false, "explanation": "配价：“给”后接的是可以转让的权利或物品，“温度”是属性，不能这样搭配。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：厨房的年龄不能被“给”，句子意思说不通。"}], "explanations": {"使用权": "正确：“房东只给我们厨房的使用权”，表示只给我们使用厨房的权利，符合句意。", "声音": "语义：厨房的声音不能“给”别人，这个词不能用于这里。", "温度": "配价：“给”后接的是可以转让的权利或物品，“温度”是属性，不能这样搭配。", "年龄": "语义：厨房的年龄不能被“给”，句子意思说不通。"}, "sentence_index": 6, "correct_answer": "使用权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的使用权很简单，老师一教就会。", "explanation": "这里应该用〈使用方法〉。使用方法可以说“简单”；使用权是权利，不能说“很简单”。"}, {"text": "学生在教室的使用权里上课。", "explanation": "使用权是抽象的权利，不是地点，不能说“在……的使用权里”。"}, {"text": "老师拥有很大的使用权，可以随意开除学生。", "explanation": "这里应该用〈权力〉。使用权只是使用某物的权利，开除学生属于权力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9ae051-7401-4cbc-995b-8c9389f3cbb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板给了我这台电脑的一台使用权。", "corrected_sentence": "老板给了我这台电脑的一项使用权。", "error_description": "量词错误：“使用权”的量词应为“项”，“台”是机器的量词，不能修饰权利。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9ae051-7401-4cbc-995b-8c9389f3cbb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不有这辆车的使用权。", "corrected_sentence": "我没有这辆车的使用权。", "error_description": "错误形式：否定词用“不”。正确形式：“我没有这辆车的使用权”。原因：表示没有某物要用“没有”，“不有”不能成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9ae051-7401-4cbc-995b-8c9389f3cbb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
