INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25310, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在旁边查看并督促别人是否按要求做事。", "primary_collocate": null, "pronunciation": "jiān dū", "ipa": "tɕjɛn˥˥ tu˥˥", "syllable_count": 2, "sentences": [{"text": "老师在旁边监督我们写作业。", "target_word": "监督", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈监督孩子每天早睡早起。", "target_word": "监督", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理每天都在监督员工，看有没有人偷懒。", "target_word": "监督", "complexity_tier": "T3", "furigana": "jīnglǐ měitiān dōu zài jiāndū yuángōng, kàn yǒu méiyǒu rén tōulǎn", "sentence_source": "generated"}, {"text": "工人做事的时候，有人在旁边监督。", "target_word": "监督", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我请朋友监督我每天跑步。", "target_word": "监督", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司请专门的人来监督工作。", "target_word": "监督", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有人监督，他也会认真学习。", "target_word": "监督", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王负责监督大家遵守规定。", "target_word": "监督", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸一直监督我少玩手机。", "target_word": "监督", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的老板会监督工作，也会帮助工人。", "target_word": "监督", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "监督员", "label": "复合"}, {"form": "监督着", "label": "体标"}, {"form": "监督过", "label": "体标"}], "register": "中性", "sense_fingerprint": "在旁边查看并督促别人是否按要求做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e4ba268-bd9c-4b86-82cf-3221d314a81e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "监督", "is_correct": true, "explanation": "正确。监督：在旁边查看并督促别人是否按要求做事，此处指老师看着我们写作业。"}, {"text": "抄袭", "is_correct": false, "explanation": "语义：“抄袭”是照搬别人的东西，老师不会抄学生的作业。"}, {"text": "批改", "is_correct": false, "explanation": "配价：“批改”的对象是作业或文章，不能说“批改我们”。"}, {"text": "修补", "is_correct": false, "explanation": "语义：“修补”是修理破损的东西，与“写作业”不相关。"}], "explanations": {"监督": "正确。监督：在旁边查看并督促别人是否按要求做事，此处指老师看着我们写作业。", "抄袭": "语义：“抄袭”是照搬别人的东西，老师不会抄学生的作业。", "批改": "配价：“批改”的对象是作业或文章，不能说“批改我们”。", "修补": "语义：“修补”是修理破损的东西，与“写作业”不相关。"}, "sentence_index": 0, "correct_answer": "监督"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生监督了我的身体。", "explanation": "这里应该用〈检查〉。监督是看人或工作有没有按要求做，查看身体要用〈检查〉。"}, {"text": "专家监督了这幅画。", "explanation": "这里应该用〈鉴定〉。监督的对象是人的行为或工作，鉴定作品要用〈鉴定〉。"}, {"text": "我们监督了一个美丽的春天。", "explanation": "这里应该用〈欣赏〉。监督的对象是人的行为或工作，欣赏春天要用〈欣赏〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7ce5719-3d14-4759-bacc-f568fe5d44ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "监督", "is_correct": true, "explanation": "正确。监督：在旁边查看并督促别人，此处指没有人督促他。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”与句中督促的意思无关，不能说“没有人出生”。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：“失踪”指不知去向，与“没有人……”的说法不合。"}, {"text": "出版", "is_correct": false, "explanation": "配价：“出版”要带出版物作宾语，句中不能单用。"}], "explanations": {"监督": "正确。监督：在旁边查看并督促别人，此处指没有人督促他。", "出生": "语义：“出生”与句中督促的意思无关，不能说“没有人出生”。", "失踪": "语义：“失踪”指不知去向，与“没有人……”的说法不合。", "出版": "配价：“出版”要带出版物作宾语，句中不能单用。"}, "sentence_index": 6, "correct_answer": "监督"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "消防员冒险监督了被困的老人。", "explanation": "这里应该用〈救〉。监督指查看并督促，救人要用〈救〉。"}, {"text": "这家饭店热情地监督了客人。", "explanation": "这里应该用〈招待〉。监督不用于接待客人，招待客人要用〈招待〉。"}, {"text": "我真心监督你的帮助。", "explanation": "这里应该用〈感谢〉。监督的对象是行为或工作，表达谢意要用〈感谢〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7ce5719-3d14-4759-bacc-f568fe5d44ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天监督了孩子写作业。", "corrected_sentence": "我每天监督孩子写作业。", "error_description": "错误：“每天监督了孩子写作业”。“每天”表示经常性的动作，不能与“了”搭配，应说“我每天监督孩子写作业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7ce5719-3d14-4759-bacc-f568fe5d44ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师监督了很严。", "corrected_sentence": "老师监督得很严。", "error_description": "错误：“监督”后的程度补语要用“得”连接，这里误用了“了”。应说“老师监督得很严。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7ce5719-3d14-4759-bacc-f568fe5d44ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
