INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25312, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让事情可以买卖，变成商品。", "primary_collocate": null, "pronunciation": "shì chǎng huà", "ipa": "ʂɻ̩˥˩ tʂʰɑŋ˨˩˦ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "有些人想把水资源市场化，让水也能卖钱。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市把公共停车位市场化了，现在要收费。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，不是所有东西都能市场化。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想把音乐课程市场化，让学生自己付钱。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的故事市场化，写成书卖钱。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把古村的文化市场化，当地人很不满意。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校食堂市场化以后，饭菜价格变了。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家把电力市场化了，电可以自由买卖。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他反对把爱情市场化，爱不能买卖。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府不想把土地完全市场化，怕价格太高。", "target_word": "市场化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "市場化", "label": "繁体"}, {"form": "市场化了", "label": "体标"}], "register": "中性", "sense_fingerprint": "市场化|动词|让事物可以买卖、变成商品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3d5ba0b-92e4-4094-9bb4-b80d9ebdc31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25312, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市场化", "is_correct": true, "explanation": "正确。“想把水资源市场化，让水也能卖钱”中，动词应表示使事物变成商品。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”与“让水也能卖钱”的意图不符，句意说不通。"}, {"text": "污染", "is_correct": false, "explanation": "语义：“污染”会降低水的价值，与“让水也能卖钱”的意图相反。"}, {"text": "节约", "is_correct": false, "explanation": "搭配：“节约”不能带出“让水也能卖钱”这样的结果，搭配不当。"}], "explanations": {"市场化": "正确。“想把水资源市场化，让水也能卖钱”中，动词应表示使事物变成商品。", "保护": "语义：“保护”与“让水也能卖钱”的意图不符，句意说不通。", "污染": "语义：“污染”会降低水的价值，与“让水也能卖钱”的意图相反。", "节约": "搭配：“节约”不能带出“让水也能卖钱”这样的结果，搭配不当。"}, "sentence_index": 0, "correct_answer": "市场化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把日记市场化了，贴在学校的墙上让大家看。", "explanation": "这里应该用〈公开〉。“市场化”指使事物可以买卖，把日记贴出来给大家看是公开，不是买卖。"}, {"text": "他把孩子市场化了，让孩子去打工。", "explanation": "这里应该用〈雇用〉。“市场化”指使事物可以买卖，不能用来指人；让孩子去打工应说〈雇用〉。"}, {"text": "两家公司在这里市场化股票，每天都很热闹。", "explanation": "这里应该用〈交易〉。股票本来就可以买卖，不需要“市场化”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc805f03-bcda-4e40-af28-b836c66e21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25312, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市场化", "is_correct": true, "explanation": "正确。“学校食堂市场化以后，饭菜价格变了”说的是食堂改为市场运作后的变化。"}, {"text": "关闭", "is_correct": false, "explanation": "语义：食堂关闭后就没有饭菜，“饭菜价格变了”说不通。"}, {"text": "倒闭", "is_correct": false, "explanation": "语义：食堂倒闭后同样没有饭菜，句中“饭菜价格变了”不成立。"}, {"text": "禁止", "is_correct": false, "explanation": "配价：“禁止”需要带出被禁止的对象，“学校食堂禁止以后”的结构不完整。"}], "explanations": {"市场化": "正确。“学校食堂市场化以后，饭菜价格变了”说的是食堂改为市场运作后的变化。", "关闭": "语义：食堂关闭后就没有饭菜，“饭菜价格变了”说不通。", "倒闭": "语义：食堂倒闭后同样没有饭菜，句中“饭菜价格变了”不成立。", "禁止": "配价：“禁止”需要带出被禁止的对象，“学校食堂禁止以后”的结构不完整。"}, "sentence_index": 6, "correct_answer": "市场化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府把煤矿市场化了，工人变成了国家员工。", "explanation": "这里应该用〈国有化〉。市场化是让事物进入买卖，不是收归国家所有。"}, {"text": "政府把公园市场化给所有人，不收门票。", "explanation": "这里应该用〈开放〉。“市场化”指使事物可以买卖，与不收门票、免费向所有人开放的意思相反。"}, {"text": "妈妈把家里的老照片市场化了，给每个孩子留一张。", "explanation": "这里应该用〈赠送〉。“市场化”指使事物可以买卖，与留给孩子、不卖的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc805f03-bcda-4e40-af28-b836c66e21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校把体育课市场化。", "corrected_sentence": "学校把体育课市场化了。", "error_description": "缺少“了”：把字句中动词后要有“了”等成分，“学校把体育课市场化”不完整，应说“学校把体育课市场化了”。错误只在“了”的缺失。", "correct_sentence_indices": [1, 2, 7]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc805f03-bcda-4e40-af28-b836c66e21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市曾经把水厂市场化了过。", "corrected_sentence": "这个城市曾经把水厂市场化过。", "error_description": "“了”与“过”不能同时使用：表示曾经经历过时用“市场化过”，去掉“了”。", "correct_sentence_indices": [2, 6, 7]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc805f03-bcda-4e40-af28-b836c66e21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25314, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc805f03-bcda-4e40-af28-b836c66e21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25314, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc805f03-bcda-4e40-af28-b836c66e21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25314, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "爸爸的爸爸做了大官，后来这个官位传给了爸爸。", "primary_collocate": null, "pronunciation": "shì xí", "ipa": "ʂʅ˥˩ ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "爷爷当过大官，官位后来世袭下来，传到了爸爸手里。", "target_word": "世袭", "complexity_tier": "T3", "furigana": "shì xí", "sentence_source": "generated"}, {"text": "他的官位是世袭的，是从爷爷那里来的。", "target_word": "世袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在古代，大官的儿子可以世袭官位。", "target_word": "世袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个官职世袭了三代，现在由他来做。", "target_word": "世袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，我们家的官位不能世袭。", "target_word": "世袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的官位一代一代世袭下来。", "target_word": "世袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代有些官位是世袭的，不用考试。", "target_word": "世袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为官位世袭，他的儿子从小就想当官。", "target_word": "世袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位大官死了，他的官位世袭下来，由儿子接着做。", "target_word": "世袭", "complexity_tier": "T3", "furigana": "shì xí", "sentence_source": "generated"}, {"text": "世袭的官位不用自己去争，传给你就行。", "target_word": "世袭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "世袭制", "label": "复合词"}], "register": "书面", "sense_fingerprint": "世袭：官位从祖辈传给父辈、子辈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3d5ba0b-92e4-4094-9bb4-b80d9ebdc31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25314, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "世袭", "is_correct": true, "explanation": "正确答案，读作 shì xí，指官位由祖辈传给父辈、子辈。"}, {"text": "实习", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是实习。"}, {"text": "市集", "is_correct": false, "explanation": "jí 与 xí 声母不同（j 与 x），意思是集市。"}, {"text": "世系", "is_correct": false, "explanation": "xì（第四声）与 xí（第二声）声调不同，意思是家族世代相传的系统。"}, {"text": "市旗", "is_correct": false, "explanation": "qí 与 xí 声母不同（q 与 x），意思是城市的旗帜。"}], "explanations": {"世袭": "正确答案，读作 shì xí，指官位由祖辈传给父辈、子辈。", "实习": "shí（第二声）与 shì（第四声）声调不同，意思是实习。", "市集": "jí 与 xí 声母不同（j 与 x），意思是集市。", "世系": "xì（第四声）与 xí（第二声）声调不同，意思是家族世代相传的系统。", "市旗": "qí 与 xí 声母不同（q 与 x），意思是城市的旗帜。"}, "sentence_index": null, "correct_answer": "世袭"}, "level_3": {"options": [{"text": "世袭", "is_correct": true, "explanation": "正确答案。“官位后来世袭下来”指官位代代传承，与下文“传到了爸爸手里”一致。"}, {"text": "辞", "is_correct": false, "explanation": "语义：“辞”指辞去职务，与“传到了爸爸手里”的传承相反。"}, {"text": "考", "is_correct": false, "explanation": "语义：“考”指通过考试获得，官位不是考下来的，与下文的传承不合。"}, {"text": "卖", "is_correct": false, "explanation": "语义：官位不能买卖，“卖”与“传到了爸爸手里”的血缘传承不合。"}], "explanations": {"世袭": "正确答案。“官位后来世袭下来”指官位代代传承，与下文“传到了爸爸手里”一致。", "辞": "语义：“辞”指辞去职务，与“传到了爸爸手里”的传承相反。", "考": "语义：“考”指通过考试获得，官位不是考下来的，与下文的传承不合。", "卖": "语义：官位不能买卖，“卖”与“传到了爸爸手里”的血缘传承不合。"}, "sentence_index": 0, "correct_answer": "世袭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他世袭了县长。", "explanation": "这里应该用〈继任〉。县长靠任命或选举产生，不能世袭；世袭只用于由血缘代代相传的职位。"}, {"text": "他世袭了公务员的职位。", "explanation": "这里应该用〈考取〉。公务员要靠考试录用，世袭只用于由后代承继的职位。"}, {"text": "学校世袭了三名优秀学生去比赛。", "explanation": "这里应该用〈选拔〉。挑选人员去比赛要说选拔，世袭不能用于挑选人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc805f03-bcda-4e40-af28-b836c66e21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25314, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世袭", "is_correct": true, "explanation": "正确答案。“古代有些官位是世袭的”指官位代代相传，与“不用考试”的语境一致。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”用于书籍、报刊，官位不能说出版。"}, {"text": "网购", "is_correct": false, "explanation": "语义：“网购”是现代的购物方式，与“古代”的语境矛盾。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”用于影视、音乐，不能用于官位。"}], "explanations": {"世袭": "正确答案。“古代有些官位是世袭的”指官位代代相传，与“不用考试”的语境一致。", "出版": "搭配：“出版”用于书籍、报刊，官位不能说出版。", "网购": "语义：“网购”是现代的购物方式，与“古代”的语境矛盾。", "播放": "搭配：“播放”用于影视、音乐，不能用于官位。"}, "sentence_index": 6, "correct_answer": "世袭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司世袭了三名员工。", "explanation": "这里应该用〈招聘〉。员工靠招聘录用，世袭只用于职位、爵位、财产的代代承继。"}, {"text": "他世袭了科长一职。", "explanation": "这里应该用〈提拔〉。科长靠上级提拔或任命，不是由血缘传下来的职位，世袭不能用于此。"}, {"text": "他世袭了一种新机器。", "explanation": "这里应该用〈发明〉。世袭只用于职位、爵位、财产的代代承继，不能用于创造新事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc805f03-bcda-4e40-af28-b836c66e21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个官位世袭上来，传给了儿子。", "corrected_sentence": "这个官位世袭下来，传给了儿子。", "error_description": "补语方向错误：官位由上一代传给下一代是向下传承，应用“下来”。这里误用“上来”，方向相反。正确形式为“世袭下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc805f03-bcda-4e40-af28-b836c66e21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他家的官位世袭着四代。", "corrected_sentence": "他家的官位世袭了四代。", "error_description": "“世袭”表示已发生的代代承继，应用“了”。这里误用“着”，“着”表示持续状态，不能说“世袭着四代”。正确形式为“世袭了四代”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc805f03-bcda-4e40-af28-b836c66e21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
