INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25316, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "纽带是像绳子一样的东西，能把两个东西连在一起。", "primary_collocate": null, "pronunciation": "niǔ dài", "ipa": "njoʊ̯˨˩˦ taɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "这条纽带很结实，能把两块木板连在一起。", "target_word": "纽带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一条红色的纽带把两根竹子绑在了一起。", "target_word": "纽带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条细细的纽带把帐篷和大树连在一起。", "target_word": "纽带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纽带断了，两只小船分开了。", "target_word": "纽带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你找一条纽带把这两个箱子连起来。", "target_word": "纽带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔民用粗粗的纽带把船拴在岸边。", "target_word": "纽带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条纽带是用布做的，不太结实。", "target_word": "纽带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个气球中间有一条纽带。", "target_word": "纽带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他剪断了连着两个盒子的纽带。", "target_word": "纽带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈把一条长纽带系在两个篮子中间。", "target_word": "纽带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条纽带", "label": "量词"}, {"form": "紐帶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "具体的带子或绳状物，把两个东西连在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3370b77-fb49-4e42-b46b-5b0a583e1654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25316, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纽带", "is_correct": true, "explanation": "纽带指具体的带子，能把两块木板连在一起，与「很结实」的描述相符，是本句的正确答案。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不能把两块木板连在一起，与「能把两块木板连在一起」的功能冲突。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然水体，不是可以用来连接木板的东西，与句中的功能不符。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：「很结实」形容固体物品的牢固，墨水是液体，不能这样描述。"}], "explanations": {"纽带": "纽带指具体的带子，能把两块木板连在一起，与「很结实」的描述相符，是本句的正确答案。", "玻璃": "语义：玻璃不能把两块木板连在一起，与「能把两块木板连在一起」的功能冲突。", "河流": "语义：河流是自然水体，不是可以用来连接木板的东西，与句中的功能不符。", "墨水": "搭配：「很结实」形容固体物品的牢固，墨水是液体，不能这样描述。"}, "sentence_index": 0, "correct_answer": "纽带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "纽带把两块木板粘在了一起。", "explanation": "这里应该用〈胶水〉。把东西粘在一起靠胶水，纽带是像绳子一样的东西，不能用来粘合。"}, {"text": "这条纽带能照出人的全身。", "explanation": "这里应该用〈镜子〉。镜子能照出人的全身，纽带是像绳子一样的东西，不能照出人影。"}, {"text": "纽带能让两人远距离通话。", "explanation": "这里应该用〈电话〉。远距离通话要靠电话，纽带是像绳子一样的东西，不能用来通话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25316, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纽带", "is_correct": true, "explanation": "纽带指具体的绳状物，「这条……是用布做的，不太结实」描述的正是这类带子，是本句的正确答案。"}, {"text": "铁链", "is_correct": false, "explanation": "语义：铁链是金属制品，不是布做的，与句中「用布做的」矛盾。"}, {"text": "铅丝", "is_correct": false, "explanation": "语义：铅丝是金属丝，与「用布做的」的描述不符。"}, {"text": "钢管", "is_correct": false, "explanation": "搭配：「不太结实」一般用来形容布料或绳子这类软物，用于钢管不合常规，且与「用布做的」矛盾。"}], "explanations": {"纽带": "纽带指具体的绳状物，「这条……是用布做的，不太结实」描述的正是这类带子，是本句的正确答案。", "铁链": "语义：铁链是金属制品，不是布做的，与句中「用布做的」矛盾。", "铅丝": "语义：铅丝是金属丝，与「用布做的」的描述不符。", "钢管": "搭配：「不太结实」一般用来形容布料或绳子这类软物，用于钢管不合常规，且与「用布做的」矛盾。"}, "sentence_index": 6, "correct_answer": "纽带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用纽带把衣服的破口缝了起来。", "explanation": "这里应该用〈针线〉。缝补衣物用的是线，纽带不能用来缝补。"}, {"text": "爸爸用纽带给手机充电。", "explanation": "这里应该用〈充电线〉。给手机充电要用充电线，纽带是绳子一样的东西，不能用来充电。"}, {"text": "电工把纽带接到了插座上。", "explanation": "这里应该用〈电线〉。接插座的是电线，纽带不能接在插座上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25316, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸用一只旧纽带把两个木箱捆在了一起。", "corrected_sentence": "爸爸用一条旧纽带把两个木箱捆在了一起。", "error_description": "量词错误：纽带应用「条」，「只」不用于这类长条状的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25316, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我用一条纽带们把风筝拴在了树上。", "corrected_sentence": "我用一条纽带把风筝拴在了树上。", "error_description": "“们”只能加在指人的名词之后，纽带是物体，应说“一条纽带”，不说“一条纽带们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
