INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25318, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情做得合规矩，没有被说不对的理由。", "primary_collocate": null, "pronunciation": "hé fǎ xìng", "ipa": "xɤ˧˥ fa˨˩˦ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这样做的合法性，你想过吗？", "target_word": "合法性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开店前，他先查了这件事的合法性。", "target_word": "合法性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友问我，网上卖二手车的合法性怎么样。", "target_word": "合法性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有合同，这笔生意的合法性就很难说。", "target_word": "合法性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她担心租房的合法性，所以去问了律师。", "target_word": "合法性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店没有执照，合法性有问题。", "target_word": "合法性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做事前要想想它的合法性。", "target_word": "合法性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条新路的合法性，村民都很关心。", "target_word": "合法性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保证每一步的合法性。", "target_word": "合法性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用假名字开公司，没有合法性可言。", "target_word": "合法性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "合法性问题", "label": "复合"}], "register": "中性", "sense_fingerprint": "合法性|名词|事情做得合规矩、没有被说不对的理由", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3d5ba0b-92e4-4094-9bb4-b80d9ebdc31e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25318, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合法性", "is_correct": true, "explanation": "正确：“合法性”指事情合规矩、没有被说不对的理由，句中问的正是这一点。"}, {"text": "导电性", "is_correct": false, "explanation": "语义：“导电性”指导体传电的性质，与做法是否合规无关。"}, {"text": "挥发性", "is_correct": false, "explanation": "语义：“挥发性”指物质容易散发，用于做法上语义不通。"}, {"text": "可塑性", "is_correct": false, "explanation": "语义：“可塑性”指能被塑造成形的性质，与做法是否合规无关。"}], "explanations": {"合法性": "正确：“合法性”指事情合规矩、没有被说不对的理由，句中问的正是这一点。", "导电性": "语义：“导电性”指导体传电的性质，与做法是否合规无关。", "挥发性": "语义：“挥发性”指物质容易散发，用于做法上语义不通。", "可塑性": "语义：“可塑性”指能被塑造成形的性质，与做法是否合规无关。"}, "sentence_index": 0, "correct_answer": "合法性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的合法性很高，工作很快。", "explanation": "这里应该用〈效率〉。合法性说事情合规矩，机器的工作能力要说效率。"}, {"text": "他做事的合法性很快。", "explanation": "这里应该用〈速度〉。合法性说事情合规矩，做事的快慢要说速度。"}, {"text": "这笔生意有一只合法性。", "explanation": "这里量词应该用〈点〉。“只”一般用于动物，合法性是抽象的，要说“一点合法性”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc805f03-bcda-4e40-af28-b836c66e21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25318, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合法性", "is_correct": true, "explanation": "正确：“做事前要想想它的合法性”指想想做法是否符合法律规矩，句意相合。"}, {"text": "延展性", "is_correct": false, "explanation": "语义：“延展性”指材料能拉长，用在做事前的思考上语义不通。"}, {"text": "可读性", "is_correct": false, "explanation": "语义：“可读性”说文字易读，与做事前的考虑无关。"}, {"text": "放射性", "is_correct": false, "explanation": "搭配：“放射性”多指物质辐射，不能说“想想它的放射性”。"}], "explanations": {"合法性": "正确：“做事前要想想它的合法性”指想想做法是否符合法律规矩，句意相合。", "延展性": "语义：“延展性”指材料能拉长，用在做事前的思考上语义不通。", "可读性": "语义：“可读性”说文字易读，与做事前的考虑无关。", "放射性": "搭配：“放射性”多指物质辐射，不能说“想想它的放射性”。"}, "sentence_index": 6, "correct_answer": "合法性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个计划的合法性很长。", "explanation": "这里应该用〈时间〉。合法性说事情合规矩，计划持续多久要说时间。"}, {"text": "这件衣服的合法性很贵。", "explanation": "这里应该用〈价格〉。合法性说事情合规矩，东西值多少钱要说价格。"}, {"text": "这个软件的合法性很多。", "explanation": "这里应该用〈功能〉。合法性指符合规矩的性质，软件的作用要说功能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc805f03-bcda-4e40-af28-b836c66e21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份合同的一个合法性很难判断。", "corrected_sentence": "这份合同的合法性很难判断。", "error_description": "量词错误：“合法性”是抽象名词，不能用“个”计量；应去掉“一个”，说“这份合同的合法性很难判断”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc805f03-bcda-4e40-af28-b836c66e21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要确认每一笔账合法性。", "corrected_sentence": "我们要确认每一笔账的合法性。", "error_description": "应为“每一笔账的合法性”。漏掉“的”，“合法性”前的定语要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc805f03-bcda-4e40-af28-b836c66e21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
