INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25328, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "天上掉下来的水，比如雨或雪。", "primary_collocate": null, "pronunciation": "jiàng shuǐ", "ipa": "tɕjɑŋ⁵¹ ʂweɪ²¹⁴", "syllable_count": 2, "sentences": [{"text": "今天的降水是雨还是雪？", "target_word": "降水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里夏天降水很多。", "target_word": "降水", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天气预报说明天有降水。", "target_word": "降水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "降水多的时候，河水会变大。", "target_word": "降水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北方冬天的降水常常是雪。", "target_word": "降水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个地方一年四季都有降水。", "target_word": "降水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月降水太少了，树都干了。", "target_word": "降水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的降水持续了整个下午。", "target_word": "降水", "complexity_tier": "T3", "furigana": "zuótiān de jiàngshuǐ chíxù le zhěnggè xiàwǔ", "sentence_source": "generated"}, {"text": "山里的降水比城里多。", "target_word": "降水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为降水，比赛改到明天了。", "target_word": "降水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "降水量", "label": "复合"}], "register": "中性", "sense_fingerprint": "天上落下的雨或雪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5ba59dc-380a-4728-a304-98f8c579d0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25328, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "降水", "is_correct": true, "explanation": "正确：“降水”指天上落下的雨或雪，与“是雨还是雪”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是雨或雪，与“是雨还是雪”的语义矛盾。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”与天气无关，“是雨还是雪”的问法不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”与“雨还是雪”不搭配，不能用来指天上落下的东西。"}], "explanations": {"降水": "正确：“降水”指天上落下的雨或雪，与“是雨还是雪”相符。", "颜色": "语义：“颜色”不是雨或雪，与“是雨还是雪”的语义矛盾。", "价格": "语义：“价格”与天气无关，“是雨还是雪”的问法不通。", "味道": "搭配：“味道”与“雨还是雪”不搭配，不能用来指天上落下的东西。"}, "sentence_index": 0, "correct_answer": "降水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋顶上的降水很厚，我们得去扫。", "explanation": "这里应该用〈雪〉。“降水”是雨雪的总称，形容屋顶积雪的厚薄要说“雪”。"}, {"text": "路上积了很多降水。", "explanation": "这里应该用〈雨水〉。落在地面积起来的水要说“雨水”；“降水”指天上落下的雨或雪，不说“积了很多降水”。"}, {"text": "今天的降水很新鲜，我们去公园吧。", "explanation": "这里应该用〈空气〉。“降水”指雨雪，不能用来形容“新鲜”，要说“空气很新鲜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25328, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降水", "is_correct": true, "explanation": "正确：“这个月降水太少了，树都干了”，“降水”作主语，与“树都干了”的因果相符。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度太少”不合常理，与“树都干了”的语义不相符。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资太少”与“树都干了”没有关联，句子不通。"}, {"text": "字数", "is_correct": false, "explanation": "搭配：“字数”不能用来描述“树都干了”的原因，搭配不当。"}], "explanations": {"降水": "正确：“这个月降水太少了，树都干了”，“降水”作主语，与“树都干了”的因果相符。", "温度": "语义：“温度太少”不合常理，与“树都干了”的语义不相符。", "工资": "语义：“工资太少”与“树都干了”没有关联，句子不通。", "字数": "搭配：“字数”不能用来描述“树都干了”的原因，搭配不当。"}, "sentence_index": 6, "correct_answer": "降水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们昨天看了一场降水的比赛。", "explanation": "“降水”不能修饰“比赛”；去掉“降水”，说“看了一场比赛”即可。"}, {"text": "这场降水在厨房里做了午饭。", "explanation": "这里的主语应是人，如〈妈妈〉；“降水”是天上落下的雨雪，不能在厨房做饭。"}, {"text": "降水出来了，天气晴朗。", "explanation": "这里应该用〈太阳〉。“降水”指落下的雨雪，不会“出来”，要说“太阳出来了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个降水是雨还是雪？", "corrected_sentence": "这场降水是雨还是雪？", "error_description": "错误形式：“这个降水”。“降水”作为一次降落的事件，量词应为“场”，不能用“个”。正确形式为“这场降水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月几乎没有一个降水，树都干了。", "corrected_sentence": "这个月几乎没有降水，树都干了。", "error_description": "错误形式：“没有一个降水”。“降水”的量词应为“场”或“次”，不能用“个”；“几乎没有降水”不需要量词。正确形式为“几乎没有降水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25332, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25332, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25332, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情变得很危险，可能会出问题。", "primary_collocate": null, "pronunciation": "wēi jī", "ipa": "weɪ˥ tɕi˥", "syllable_count": 2, "sentences": [{"text": "公司现在遇到了大危机。", "target_word": "危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次危机来得很突然。", "target_word": "危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起努力，才过了这个危机。", "target_word": "危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会在危机中冷静想办法。", "target_word": "危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城里出现了严重的危机，水越来越少。", "target_word": "危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，公司有危机，大家要小心。", "target_word": "危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂正面临危机，很多人要离开。", "target_word": "危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友帮他度过了生活中的危机。", "target_word": "危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发现危机以后，我们马上开会。", "target_word": "危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那场危机让很多人没了工作。", "target_word": "危机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场危机", "label": "量词（场）"}, {"form": "经济危机", "label": "复合词"}, {"form": "危机感", "label": "复合词"}], "register": "中性", "sense_fingerprint": "危机：名词，严重困难或危险的时刻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be7eb40f-7d8a-4232-9c49-ff679e0a5a7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25332, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "危机", "is_correct": true, "explanation": "wēi jī 对应“危机”，指严重困难或危险的时刻。"}, {"text": "飞机", "is_correct": false, "explanation": "fēi 与 wēi 声母不同（f 与 w），意思是飞机。"}, {"text": "违纪", "is_correct": false, "explanation": "wéi jì 与 wēi jī 声调不同，意思是违反纪律。"}, {"text": "维基", "is_correct": false, "explanation": "wéi 与 wēi 声调不同，意思是维基（网络百科）。"}], "explanations": {"危机": "wēi jī 对应“危机”，指严重困难或危险的时刻。", "飞机": "fēi 与 wēi 声母不同（f 与 w），意思是飞机。", "违纪": "wéi jì 与 wēi jī 声调不同，意思是违反纪律。", "维基": "wéi 与 wēi 声调不同，意思是维基（网络百科）。"}, "sentence_index": null, "correct_answer": "危机"}, "level_3": {"options": [{"text": "危机", "is_correct": true, "explanation": "“危机”指严重困难或危险的时刻，与“遇到了大”相合，是正确答案。"}, {"text": "利润", "is_correct": false, "explanation": "语义：利润是盈利，与“遇到”所表示的困境相矛盾。"}, {"text": "奖金", "is_correct": false, "explanation": "搭配：“遇到”后接的是困难类名词，奖金应说“拿到”或“得到”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是需要应对的困境，“遇到了大天气”说不通。"}], "explanations": {"危机": "“危机”指严重困难或危险的时刻，与“遇到了大”相合，是正确答案。", "利润": "语义：利润是盈利，与“遇到”所表示的困境相矛盾。", "奖金": "搭配：“遇到”后接的是困难类名词，奖金应说“拿到”或“得到”。", "天气": "语义：天气是自然现象，不是需要应对的困境，“遇到了大天气”说不通。"}, "sentence_index": 0, "correct_answer": "危机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我父亲是危机。", "explanation": "这里应该用〈工程师〉。危机指危险的局面，不能用来指人，也不能用来说父亲的职业。"}, {"text": "机器出了危机，只能停下来修。", "explanation": "这里应该用〈故障〉。危机多指社会、经济或人生中的危急局面，机器出问题应说“故障”。"}, {"text": "他下周要参加一场危机。", "explanation": "这里应该用〈考试〉。危机指危险的局面，不能用“参加”来说，参加的是考试、比赛等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25332, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "危机", "is_correct": true, "explanation": "“危机”指危险的局面，与“正面临”和“很多人要离开”相合，是正确答案。"}, {"text": "订单", "is_correct": false, "explanation": "搭配：“面临”接的是困境、挑战等抽象事件，“订单”是具体的商业凭证，不说面临。"}, {"text": "机器", "is_correct": false, "explanation": "语义：机器是设备，不是可以面对的局面，“正面临机器”说不通。"}, {"text": "车祸", "is_correct": false, "explanation": "语义：车祸是突发事故，不是工厂面对的局面，句意不通。"}], "explanations": {"危机": "“危机”指危险的局面，与“正面临”和“很多人要离开”相合，是正确答案。", "订单": "搭配：“面临”接的是困境、挑战等抽象事件，“订单”是具体的商业凭证，不说面临。", "机器": "语义：机器是设备，不是可以面对的局面，“正面临机器”说不通。", "车祸": "语义：车祸是突发事故，不是工厂面对的局面，句意不通。"}, "sentence_index": 6, "correct_answer": "危机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他选择了最好的危机开始行动。", "explanation": "这里应该用〈时机〉。危机指危险的局面，不能用来说做事的合适时间。"}, {"text": "他的危机写得很详细。", "explanation": "这里应该用〈报告〉。危机指危险的局面，不能用来指书面材料，也不能说“写得很详细”。"}, {"text": "我今天的危机很好。", "explanation": "这里应该用〈心情〉。危机指危险的局面，不能用来指人的情绪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司终于度过着危机。", "corrected_sentence": "这家公司终于度过了危机。", "error_description": "体标错误：“度过”表示已完成的动作，应用“了”，不能用“着”，应说“度过了危机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司经历了三个次危机。", "corrected_sentence": "公司经历了三次危机。", "error_description": "量词错误：“次”本身是动量词，前面不能再加“个”，应说“三次危机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25336, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
