INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25336, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "潜力就是还没有用出来的、藏在身体里的特别本领。", "primary_collocate": null, "pronunciation": "qián lì", "ipa": "tɕʰjɛn˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "这个孩子很有潜力，将来会成功。", "target_word": "潜力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说每个学生都有很大的潜力。", "target_word": "潜力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要努力把自己的潜力发挥出来。", "target_word": "潜力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发现他有音乐方面的潜力。", "target_word": "潜力", "complexity_tier": "T3", "furigana": "lǎo shī fā xiàn tā yǒu yīn yuè fāng miàn de qián lì。", "sentence_source": "generated"}, {"text": "运动可以让人发现自己的潜力。", "target_word": "潜力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位年轻的足球运动员很有潜力。", "target_word": "潜力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没有想过自己有这样的潜力。", "target_word": "潜力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的潜力还没有人发现。", "target_word": "潜力", "complexity_tier": "T3", "furigana": "tā de qián lì hái méi yǒu rén fā xiàn。", "sentence_source": "generated"}, {"text": "好的教练能发现孩子的潜力。", "target_word": "潜力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别放弃，你的潜力还没有用完。", "target_word": "潜力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "潛力", "label": "繁体"}, {"form": "发展潜力", "label": "复合"}], "register": "中性", "sense_fingerprint": "尚未发挥出来的内在能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4246d07b-ae3c-4f25-9405-93e74c5a5c69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25336, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "潜力", "is_correct": true, "explanation": "正确答案。潜力（qián lì）指还没有发挥出来的内在能力。"}, {"text": "千里", "is_correct": false, "explanation": "千里（qiān lǐ）第一音节 qiān（第一声）与 qián（第二声）声调不同，第二音节 lǐ（第三声）与 lì（第四声）声调也不同，意思是一千里。"}, {"text": "强力", "is_correct": false, "explanation": "强力（qiáng lì）第一音节 qiáng 与 qián 韵母不同（ang 与 an），意思是力量很大。"}, {"text": "尖利", "is_correct": false, "explanation": "尖利（jiān lì）第一音节 jiān 与 qián 声母不同（j 与 q），意思是锋利。"}, {"text": "签立", "is_correct": false, "explanation": "签立（qiān lì）第一音节 qiān（第一声）与 qián（第二声）声调不同，意思是签订（合同等文件）。"}], "explanations": {"潜力": "正确答案。潜力（qián lì）指还没有发挥出来的内在能力。", "千里": "千里（qiān lǐ）第一音节 qiān（第一声）与 qián（第二声）声调不同，第二音节 lǐ（第三声）与 lì（第四声）声调也不同，意思是一千里。", "强力": "强力（qiáng lì）第一音节 qiáng 与 qián 韵母不同（ang 与 an），意思是力量很大。", "尖利": "尖利（jiān lì）第一音节 jiān 与 qián 声母不同（j 与 q），意思是锋利。", "签立": "签立（qiān lì）第一音节 qiān（第一声）与 qián（第二声）声调不同，意思是签订（合同等文件）。"}, "sentence_index": null, "correct_answer": "潜力"}, "level_3": {"options": [{"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指体型，多用来形容成年人，用在这个孩子身上不自然。"}, {"text": "潜力", "is_correct": true, "explanation": "正确。“潜力”指还没用出来的能力，与“将来会成功”的预期相符。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：“年纪”指年龄大，与“这个孩子”的身份矛盾。"}, {"text": "历史", "is_correct": false, "explanation": "语义：“历史”指过去的事情，与“将来会成功”的预期不符。"}], "explanations": {"身材": "体貌：“身材”指体型，多用来形容成年人，用在这个孩子身上不自然。", "潜力": "正确。“潜力”指还没用出来的能力，与“将来会成功”的预期相符。", "年纪": "语义：“年纪”指年龄大，与“这个孩子”的身份矛盾。", "历史": "语义：“历史”指过去的事情，与“将来会成功”的预期不符。"}, "sentence_index": 0, "correct_answer": "潜力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司去年的潜力是一千万元。", "explanation": "这里应该用〈营业额〉。“潜力”指还没用出来的能力，已经发生的金额是实际数字，要用“营业额”。"}, {"text": "这支球队的潜力一共是二十五人。", "explanation": "这里应该用〈人数〉。“潜力”指还没用出来的能力，队伍的成员数量是现成的数目，要用“人数”。"}, {"text": "他跑了三个小时，潜力是二十公里。", "explanation": "这里应该用〈路程〉。“潜力”指还没用出来的能力，已经跑过的距离是实际数字，要用“路程”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25336, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指外表的色彩，与“想过自己有这样的……”所说的内在能力不相符。"}, {"text": "潜力", "is_correct": true, "explanation": "正确。“潜力”指尚未发挥出来的能力，与“从来没有想过自己有这样的”语境相符。"}, {"text": "芳名", "is_correct": false, "explanation": "语域：“芳名”是敬辞，用于称呼别人的名字，不用于叙述自己的能力，语域不合。"}, {"text": "体积", "is_correct": false, "explanation": "语义：“体积”指物体所占的空间，不用来说一个人的能力。"}], "explanations": {"颜色": "语义：“颜色”指外表的色彩，与“想过自己有这样的……”所说的内在能力不相符。", "潜力": "正确。“潜力”指尚未发挥出来的能力，与“从来没有想过自己有这样的”语境相符。", "芳名": "语域：“芳名”是敬辞，用于称呼别人的名字，不用于叙述自己的能力，语域不合。", "体积": "语义：“体积”指物体所占的空间，不用来说一个人的能力。"}, "sentence_index": 6, "correct_answer": "潜力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他身上还有一把潜力，只是没人发现。", "explanation": "这里应该用〈一种〉或〈一股〉。量词“把”用于有柄、能握住的东西，“潜力”不用“把”。"}, {"text": "这块石头里藏着一颗潜力，需要慢慢挖掘。", "explanation": "这里应该用〈一种〉。量词“颗”用于粒状或圆形的东西，“潜力”不用“颗”。"}, {"text": "他的身体里有一条潜力，还没有用出来。", "explanation": "这里应该用〈一种〉或〈一股〉。量词“条”用于细长的东西，“潜力”不用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25336, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他身上有一个潜力，还没有发挥出来。", "corrected_sentence": "他身上有一种潜力，还没有发挥出来。", "error_description": "量词错误：“潜力”前应用“种”或“股”，不用“个”。写成“一个潜力”不地道，正确说法是“一种潜力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25336, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很潜力，还没有发挥出来。", "corrected_sentence": "他很有潜力，还没有发挥出来。", "error_description": "语法错误：“潜力”是名词，前面不能直接加“很”，要说“很有潜力”，漏掉了“有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25338, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放纵", "is_correct": true, "explanation": "放纵与“节制”构成反义：一个是管住自己，一个是任由自己过度。"}, {"text": "检验", "is_correct": false, "explanation": "检验指检查是否合格，与“节制”没有反义关系。"}, {"text": "出发", "is_correct": false, "explanation": "出发指动身前往，与约束自己不构成反义。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运指把东西从一处移到另一处，与“节制”无对立关系。"}], "correct_answer": "放纵", "explanations": {"放纵": "放纵与“节制”构成反义：一个是管住自己，一个是任由自己过度。", "检验": "检验指检查是否合格，与“节制”没有反义关系。", "出发": "出发指动身前往，与约束自己不构成反义。", "搬运": "搬运指把东西从一处移到另一处，与“节制”无对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25338, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放纵", "is_correct": true, "explanation": "放纵与“节制”构成反义：一个是管住自己，一个是毫无节制地任由自己。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论指共同商议问题，与“节制”没有反义关系。"}, {"text": "整理", "is_correct": false, "explanation": "整理指把东西理顺、归类，与约束自己不构成反义。"}, {"text": "分析", "is_correct": false, "explanation": "分析指研究事物的构成与道理，与“节制”无对立关系。"}], "correct_answer": "放纵", "explanations": {"放纵": "放纵与“节制”构成反义：一个是管住自己，一个是毫无节制地任由自己。", "讨论": "讨论指共同商议问题，与“节制”没有反义关系。", "整理": "整理指把东西理顺、归类，与约束自己不构成反义。", "分析": "分析指研究事物的构成与道理，与“节制”无对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25338, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "控制自己，不多吃或不多做不好的事。", "primary_collocate": null, "pronunciation": "jié zhì", "ipa": "tɕje˧˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "糖吃多了不好，你要节制一点。", "target_word": "节制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爱喝酒，可是每次都节制，从不喝醉。", "target_word": "节制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说我要节制吃肉。", "target_word": "节制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子玩游戏要节制，不能玩一整天。", "target_word": "节制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，很多人不知道节制，吃得太多。", "target_word": "节制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了身体健康，他开始节制喝咖啡。", "target_word": "节制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你已经吃了三块蛋糕，该节制了。", "target_word": "节制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看电视不知道节制，每天很晚才睡。", "target_word": "节制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她努力节制自己，不再吃夜宵。", "target_word": "节制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友提醒我节制一点，别再抽烟了。", "target_word": "节制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "节制了", "label": "体标"}, {"form": "节制过", "label": "体标"}, {"form": "節制", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：管住自己，不多吃、不多做对身体不好的事（节制吃肉、节制抽烟）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a3d56dd-11e0-4e6c-9189-3f9142d08cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25338, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "节制", "is_correct": true, "explanation": "正确答案。节制 jié zhì，意思是管住自己，不多吃或不多做不好的事。"}, {"text": "戒指", "is_correct": false, "explanation": "jiè zhǐ 与 jié zhì 两个音节声调都不同，意思是戒指（首饰）。"}, {"text": "解职", "is_correct": false, "explanation": "jiě zhí 与 jié zhì 两个音节声调都不同，意思是免去职务（书面用语）。"}, {"text": "接治", "is_correct": false, "explanation": "jiē zhì 与 jié zhì 第一个音节声调不同，意思是与对方联系商议（用例较少）。"}], "explanations": {"节制": "正确答案。节制 jié zhì，意思是管住自己，不多吃或不多做不好的事。", "戒指": "jiè zhǐ 与 jié zhì 两个音节声调都不同，意思是戒指（首饰）。", "解职": "jiě zhí 与 jié zhì 两个音节声调都不同，意思是免去职务（书面用语）。", "接治": "jiē zhì 与 jié zhì 第一个音节声调不同，意思是与对方联系商议（用例较少）。"}, "sentence_index": null, "correct_answer": "节制"}, "level_3": {"options": [{"text": "节制", "is_correct": true, "explanation": "节制：控制自己，与“糖吃多了不好，你要……一点”的劝告相合。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加一点”与“糖吃多了不好”的劝告方向相反。"}, {"text": "保存", "is_correct": false, "explanation": "语义：“保存”指留存、收藏，与劝人控制饮食的句意不符。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记一点”不符合句中劝人控制饮食的意思。"}], "explanations": {"节制": "节制：控制自己，与“糖吃多了不好，你要……一点”的劝告相合。", "增加": "语义：“增加一点”与“糖吃多了不好”的劝告方向相反。", "保存": "语义：“保存”指留存、收藏，与劝人控制饮食的句意不符。", "忘记": "语义：“忘记一点”不符合句中劝人控制饮食的意思。"}, "sentence_index": 0, "correct_answer": "节制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师节制了每个努力的学生。", "explanation": "这里应该用〈表扬〉。节制指约束自己的行为，不用于对他人的赞扬。"}, {"text": "大家节制那个受伤的小孩。", "explanation": "这里应该用〈同情〉。节制指约束自己的行为，不用于表示对他人遭遇的怜悯。"}, {"text": "他节制了眼前的困难。", "explanation": "这里应该用〈克服〉。节制指约束欲望或行为，困难要说“克服”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25338, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "节制", "is_correct": true, "explanation": "节制：管住自己不再多吃，与“已经吃了三块蛋糕”的语境相合。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“该结婚了”与吃蛋糕的语境毫不相干，句意不通。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”搭配书籍、报刊，不能用于“该……了”的吃东西语境。"}, {"text": "建造", "is_correct": false, "explanation": "搭配：“建造”的对象是建筑或设施，不能与吃蛋糕搭配。"}], "explanations": {"节制": "节制：管住自己不再多吃，与“已经吃了三块蛋糕”的语境相合。", "结婚": "语义：“该结婚了”与吃蛋糕的语境毫不相干，句意不通。", "出版": "搭配：“出版”搭配书籍、报刊，不能用于“该……了”的吃东西语境。", "建造": "搭配：“建造”的对象是建筑或设施，不能与吃蛋糕搭配。"}, "sentence_index": 6, "correct_answer": "节制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他节制了每一分钱。", "explanation": "这里应该用〈节省〉。节制用于约束欲望或行为，钱要省应说“节省”。"}, {"text": "我节制你的选择。", "explanation": "这里应该用〈尊重〉。节制是约束自己的行为，对他人的选择应说“尊重”。"}, {"text": "她节制了那台坏掉的机器。", "explanation": "这里应该用〈修复〉。节制指约束行为或欲望，坏了的机器要说“修复”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想节制了喝咖啡的次数。", "corrected_sentence": "我想节制喝咖啡的次数。", "error_description": "错误在“节制”后多加了“了”：“想”之后的动词不带“了”，应为“我想节制喝咖啡的次数”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很节制的吃饭，每顿只吃八分饱。", "corrected_sentence": "他很节制地吃饭，每顿只吃八分饱。", "error_description": "“节制”作状语修饰动词“吃饭”，应用“地”，误用了“的”；正确形式为“很节制地吃饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25340, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "近", "is_correct": true, "explanation": "正确答案。“远”与“近”是反义词，都指距离的大小。"}, {"text": "高", "is_correct": false, "explanation": "“高”与“远”不构成反义，“高”说高度，不说距离。"}, {"text": "重", "is_correct": false, "explanation": "“重”的反义词是“轻”，与“远”没有反义关系。"}, {"text": "长", "is_correct": false, "explanation": "“长”的反义词是“短”，不是“远”。"}], "correct_answer": "近", "explanations": {"近": "正确答案。“远”与“近”是反义词，都指距离的大小。", "高": "“高”与“远”不构成反义，“高”说高度，不说距离。", "重": "“重”的反义词是“轻”，与“远”没有反义关系。", "长": "“长”的反义词是“短”，不是“远”。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25340, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "近", "is_correct": true, "explanation": "正确答案。“远”与“近”是反义词，都指距离的大小。"}, {"text": "深", "is_correct": false, "explanation": "“深”的反义词是“浅”，与“远”没有反义关系。"}, {"text": "厚", "is_correct": false, "explanation": "“厚”的反义词是“薄”，与“远”没有反义关系。"}, {"text": "胖", "is_correct": false, "explanation": "“胖”的反义词是“瘦”，与“远”没有反义关系。"}], "correct_answer": "近", "explanations": {"近": "正确答案。“远”与“近”是反义词，都指距离的大小。", "深": "“深”的反义词是“浅”，与“远”没有反义关系。", "厚": "“厚”的反义词是“薄”，与“远”没有反义关系。", "胖": "“胖”的反义词是“瘦”，与“远”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25340, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示距离大，比如从这到那要走很久。", "primary_collocate": null, "pronunciation": "yuǎn", "ipa": "ɥɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "从这儿到那儿很远，要走很久。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家太远，走路要走一个多小时。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车站很远，我们得坐公交车去。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去山顶的路很远，我们走了一上午。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司离我家远，所以我早上六点就起床。", "target_word": "远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷住在很远的农村，一年只见一次。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路那么远，你别走着去了，坐车吧。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个湖不太远，骑车二十分钟就到了。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她跑了很远的路，累得不想说话。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友在很远的城市工作，我们很少见面。", "target_word": "远", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更远", "label": "比较"}, {"form": "最远", "label": "最高级"}, {"form": "远远", "label": "重叠"}, {"form": "遠", "label": "繁体"}], "register": "中性", "sense_fingerprint": "距离大，路上要花很久", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a3d56dd-11e0-4e6c-9189-3f9142d08cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25340, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "远", "is_correct": true, "explanation": "正确答案。远读 yuǎn（第三声），表示距离大。"}, {"text": "院", "is_correct": false, "explanation": "院读 yuàn（第四声），与 yuǎn 只差声调，意思是院子。"}, {"text": "元", "is_correct": false, "explanation": "元读 yuán（第二声），与 yuǎn 只差声调，意思是货币单位。"}, {"text": "冤", "is_correct": false, "explanation": "冤读 yuān（第一声），与 yuǎn 只差声调，意思是冤枉。"}], "explanations": {"远": "正确答案。远读 yuǎn（第三声），表示距离大。", "院": "院读 yuàn（第四声），与 yuǎn 只差声调，意思是院子。", "元": "元读 yuán（第二声），与 yuǎn 只差声调，意思是货币单位。", "冤": "冤读 yuān（第一声），与 yuǎn 只差声调，意思是冤枉。"}, "sentence_index": null, "correct_answer": "远"}, "level_3": {"options": [{"text": "远", "is_correct": true, "explanation": "“很远”说距离大，与后句“要走很久”相符。"}, {"text": "近", "is_correct": false, "explanation": "语义：“近”说距离小，与“要走很久”矛盾。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高”说高度，不能用来形容两地之间的距离。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”形容速度，与“要走很久”矛盾。"}], "explanations": {"远": "“很远”说距离大，与后句“要走很久”相符。", "近": "语义：“近”说距离小，与“要走很久”矛盾。", "高": "语义：“高”说高度，不能用来形容两地之间的距离。", "快": "语义：“快”形容速度，与“要走很久”矛盾。"}, "sentence_index": 0, "correct_answer": "远"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们等得很远，公交车才来。", "explanation": "这里应该用〈久〉。“远”说空间距离，等待的时间长短要用“久”，不能说“等得很远”。"}, {"text": "这根绳子绑得很远，一拉就断。", "explanation": "这里应该用〈紧〉。绳子的松紧要用“紧”，“远”只说距离远近，不能用来说绑得紧不紧。"}, {"text": "这段日子很远，过得很慢。", "explanation": "这里应该用〈长〉。“远”不用来说时间的长短，形容日子长要用“长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25340, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "远", "is_correct": true, "explanation": "正确答案。远读 yuǎn（第三声），表示距离大。"}, {"text": "愿", "is_correct": false, "explanation": "愿读 yuàn（第四声），与 yuǎn 只差声调，意思是愿意。"}, {"text": "圆", "is_correct": false, "explanation": "圆读 yuán（第二声），与 yuǎn 只差声调，意思是圆形。"}, {"text": "眼", "is_correct": false, "explanation": "眼读 yǎn（第三声），与 yuǎn 只差介音 u，意思是眼睛。"}], "explanations": {"远": "正确答案。远读 yuǎn（第三声），表示距离大。", "愿": "愿读 yuàn（第四声），与 yuǎn 只差声调，意思是愿意。", "圆": "圆读 yuán（第二声），与 yuǎn 只差声调，意思是圆形。", "眼": "眼读 yǎn（第三声），与 yuǎn 只差介音 u，意思是眼睛。"}, "sentence_index": null, "correct_answer": "远"}, "level_3": {"options": [{"text": "远", "is_correct": true, "explanation": "“那么远”说明路程长，所以要坐车，与句意相符。"}, {"text": "慢", "is_correct": false, "explanation": "搭配：“慢”说速度，不说路的长短，且与“坐车吧”不协调。"}, {"text": "贵", "is_correct": false, "explanation": "语义：“贵”说价格，与路的长短无关。"}, {"text": "轻", "is_correct": false, "explanation": "搭配：路不说“轻”或“重”，“路那么轻”不成立。"}], "explanations": {"远": "“那么远”说明路程长，所以要坐车，与句意相符。", "慢": "搭配：“慢”说速度，不说路的长短，且与“坐车吧”不协调。", "贵": "语义：“贵”说价格，与路的长短无关。", "轻": "搭配：路不说“轻”或“重”，“路那么轻”不成立。"}, "sentence_index": 6, "correct_answer": "远"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这口井很远，挖到地下十米才有水。", "explanation": "这里应该用〈深〉。井的深浅要用“深”，“远”只说距离。"}, {"text": "这座楼很远，我们住在第十八层。", "explanation": "这里应该用〈高〉。楼的高矮要用“高”，“远”不用来形容楼层。"}, {"text": "这本书很远，我看了三个星期。", "explanation": "这里应该用〈厚〉。书的厚薄要用“厚”，“远”不用来说书的厚度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每天要走很远路去学校。", "corrected_sentence": "我们每天要走很远的路去学校。", "error_description": "“远”修饰名词“路”时中间要加“的”，应说“很远的路”，不能说“很远路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个湖远很，要坐车两个小时才能到。", "corrected_sentence": "这个湖很远，要坐车两个小时才能到。", "error_description": "程度副词“很”要放在“远”前面，应说“很远”，不能说“远很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
