INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25342, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "节律就是有规律地动或变化。", "primary_collocate": null, "pronunciation": "jié lǜ", "ipa": "tɕje³⁵ ly⁵¹", "syllable_count": 2, "sentences": [{"text": "睡觉和起床都有节律。", "target_word": "节律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "心跳有自己的节律。", "target_word": "节律", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "四季的变化有节律。", "target_word": "节律", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的生活很有节律，每天都一样。", "target_word": "节律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熬夜会破坏身体的节律。", "target_word": "节律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "潮水来去有一定的节律。", "target_word": "节律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作要有节律，不能太累。", "target_word": "节律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟叫的节律很好听。", "target_word": "节律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的吃饭和睡觉要有节律。", "target_word": "节律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国旅行后，我的节律乱了。", "target_word": "节律", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生物节律", "label": "复合"}, {"form": "节律性", "label": "复合"}], "register": "中性", "sense_fingerprint": "有规律地动或变化的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5ba59dc-380a-4728-a304-98f8c579d0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25342, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "节律", "is_correct": true, "explanation": "正确：「节律」指有规律地动或变化的样子。"}, {"text": "纪律", "is_correct": false, "explanation": "jì（第四声）与 jié（第二声）韵母和声调都不同（i 与 ie），意思是纪律。"}, {"text": "戒律", "is_correct": false, "explanation": "jiè（第四声）与 jié（第二声）声调不同，意思是戒律。"}, {"text": "节录", "is_correct": false, "explanation": "lù（第四声）与 lǜ（第四声）韵母不同（u 与 ü），意思是摘录。"}], "explanations": {"节律": "正确：「节律」指有规律地动或变化的样子。", "纪律": "jì（第四声）与 jié（第二声）韵母和声调都不同（i 与 ie），意思是纪律。", "戒律": "jiè（第四声）与 jié（第二声）声调不同，意思是戒律。", "节录": "lù（第四声）与 lǜ（第四声）韵母不同（u 与 ü），意思是摘录。"}, "sentence_index": null, "correct_answer": "节律"}, "level_3": {"options": [{"text": "节律", "is_correct": true, "explanation": "正确：「睡觉和起床都有节律」指两者都有规律的节奏，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：睡觉和起床没有颜色，「都有颜色」意思不通。"}, {"text": "重量", "is_correct": false, "explanation": "语义：「睡觉和起床」不说有重量，填入后与句意不合。"}, {"text": "形状", "is_correct": false, "explanation": "搭配：「有形状」不搭配「睡觉和起床」这类动作。"}], "explanations": {"节律": "正确：「睡觉和起床都有节律」指两者都有规律的节奏，与句意相符。", "颜色": "语义：睡觉和起床没有颜色，「都有颜色」意思不通。", "重量": "语义：「睡觉和起床」不说有重量，填入后与句意不合。", "形状": "搭配：「有形状」不搭配「睡觉和起床」这类动作。"}, "sentence_index": 0, "correct_answer": "节律"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校的节律很严，学生都要遵守。", "explanation": "这里应该用〈规则〉。规则是人为制定的要求；「节律」指有规律的节奏，不指需要遵守的规定。"}, {"text": "这位作家写了一根节律，很长。", "explanation": "这里不能用量词「根」。「根」用于细长的东西，「节律」是抽象的规律，不能用「根」计量，应说「一种节律」。"}, {"text": "他在学校里很守节律。", "explanation": "这里应该用〈纪律〉。「守纪律」指遵守规矩；「节律」不能说「守节律」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25342, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "节律", "is_correct": true, "explanation": "正确：「工作要有节律」指工作要有规律、有节奏，与「不能太累」相符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：工作没有体重，「工作要有体重」说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：工作没有年龄，「工作要有年龄」与句意不合。"}, {"text": "电压", "is_correct": false, "explanation": "搭配：「有电压」多指电路，不能与「工作」搭配。"}], "explanations": {"节律": "正确：「工作要有节律」指工作要有规律、有节奏，与「不能太累」相符。", "体重": "语义：工作没有体重，「工作要有体重」说不通。", "年龄": "语义：工作没有年龄，「工作要有年龄」与句意不合。", "电压": "搭配：「有电压」多指电路，不能与「工作」搭配。"}, "sentence_index": 6, "correct_answer": "节律"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的节律很热闹，大家都来看。", "explanation": "这里应该用〈节日〉。节日指节庆的日子；「节律」指有规律地重复出现的节奏，不指节庆。"}, {"text": "他的节律很高，比我高一头。", "explanation": "这里应该用〈个子〉或〈身高〉。「节律」不能用来描述人的身高。"}, {"text": "他的性格很有节律，朋友都喜欢他。", "explanation": "这里应该用〈稳定〉或〈开朗〉之类描写性格的词；「节律」指有规律的重复，不用来形容性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25342, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的说话有一只节律，很好听。", "corrected_sentence": "他的说话有一种节律，很好听。", "error_description": "量词错误：「节律」是抽象事物，「只」用于动物等个体，不能用来计量「节律」，应说「一种节律」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25342, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的作息很节律，每天准时吃饭。", "corrected_sentence": "她的作息很有节律，每天准时吃饭。", "error_description": "漏了动词：「有节律」中的「有」不能省略，「很节律」是名词前加程度副词，不通；应说「很有节律」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
