INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25344, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指某事物只在某个地方才有的性质。", "primary_collocate": null, "pronunciation": "dì fāng xìng", "ipa": "ti⁵¹ fɑŋ⁵⁵ ɕiŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "这些地方性的东西，外地买不到。", "target_word": "地方性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖很多地方性的小吃。", "target_word": "地方性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地方性的东西常常最有意思。", "target_word": "地方性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行时，我喜欢买地方性的礼物。", "target_word": "地方性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶是地方性的，别处没有。", "target_word": "地方性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种酱料是地方性的，外地的超市里找不到。", "target_word": "地方性", "complexity_tier": "T3", "furigana": "zhè zhǒng jiàng liào shì dì fāng xìng de wài dì de chāo shì lǐ zhǎo bu dào", "sentence_source": "generated"}, {"text": "他给我介绍了几种地方性的水果。", "target_word": "地方性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地方性的食物让旅行更有意思。", "target_word": "地方性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鸟是地方性的，只在这个岛上有。", "target_word": "地方性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子有几种地方性的植物，外面很少见。", "target_word": "地方性", "complexity_tier": "T3", "furigana": "zhè ge cūn zi yǒu jǐ zhǒng dì fāng xìng de zhí wù wài miàn hěn shǎo jiàn", "sentence_source": "generated"}], "morphological_forms": [{"form": "地方性知识", "label": "复合"}], "register": "中性", "sense_fingerprint": "只在某个地方才有的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5ba59dc-380a-4728-a304-98f8c579d0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25344, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地方性", "is_correct": true, "explanation": "正确：「地方性」指只在某地才有，与「外地买不到」的语境相符。"}, {"text": "外地", "is_correct": false, "explanation": "语义：「外地」指别的地方，「这些外地的东西，外地买不到」前后自相矛盾。"}, {"text": "普遍性", "is_correct": false, "explanation": "语义：「普遍性」指到处都有，与「外地买不到」矛盾。"}, {"text": "世界性", "is_correct": false, "explanation": "语域：「世界性」偏书面和宏观，不用于描述日常小东西，与口语化的购物语境不合。"}], "explanations": {"地方性": "正确：「地方性」指只在某地才有，与「外地买不到」的语境相符。", "外地": "语义：「外地」指别的地方，「这些外地的东西，外地买不到」前后自相矛盾。", "普遍性": "语义：「普遍性」指到处都有，与「外地买不到」矛盾。", "世界性": "语域：「世界性」偏书面和宏观，不用于描述日常小东西，与口语化的购物语境不合。"}, "sentence_index": 0, "correct_answer": "地方性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个村子的地方性是蜂蜜。", "explanation": "这里应该用〈特产〉。特产指某地出产的东西本身；「地方性」说的是只在某地才有的性质，不能当作东西来说「是蜂蜜」。"}, {"text": "这座塔是这个城市的地方性，外地人都专程来看。", "explanation": "这里应该用〈地标〉。地标指能代表某地的建筑或景物；「地方性」说的是只在某地才有的性质，不能用来指一座建筑。"}, {"text": "这里的地方性很有名，很多游客来买。", "explanation": "这里应该用〈名产〉。「有名」说的是具体的物品，「地方性」是性质，不能说「地方性很有名」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地方性", "is_correct": true, "explanation": "正确：「几种地方性的水果」指只在某些地方才有的水果，与「介绍」的语境相符。"}, {"text": "金属性", "is_correct": false, "explanation": "语义：「金属性」指金属的性质，水果不是金属，与「水果」矛盾。"}, {"text": "文学性", "is_correct": false, "explanation": "语义：「文学性」指作品的艺术特点，不能用来修饰水果。"}, {"text": "科技性", "is_correct": false, "explanation": "搭配：「科技性」是抽象性质，不能用来修饰可以「介绍」给人的具体水果。"}], "explanations": {"地方性": "正确：「几种地方性的水果」指只在某些地方才有的水果，与「介绍」的语境相符。", "金属性": "语义：「金属性」指金属的性质，水果不是金属，与「水果」矛盾。", "文学性": "语义：「文学性」指作品的艺术特点，不能用来修饰水果。", "科技性": "搭配：「科技性」是抽象性质，不能用来修饰可以「介绍」给人的具体水果。"}, "sentence_index": 6, "correct_answer": "地方性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种水果是地方性的，全世界都有。", "explanation": "这里应该用〈普遍〉之类的词。“地方性”指只在某地才有，与“全世界都有”矛盾。"}, {"text": "我的地方性在南方，那里四季都很暖和。", "explanation": "这里应该用〈老家〉。「老家」指出生或长大的地方；「地方性」说的是只在某地才有的性质，不能用来指地方本身。"}, {"text": "他是一个地方性的人，只在这个村子里有。", "explanation": "「地方性」说的是东西只在某地才有，用来形容人不合适；这里应该用〈独特〉或〈特别〉来描写人的特点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种小吃是地方性，外地吃不到。", "corrected_sentence": "这种小吃是地方性的，外地吃不到。", "error_description": "「的」漏掉了：「地方性」作谓语时，后面要带「的」，应说「是地方性的」，不能只说「是地方性」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些美食是地方性地，外地吃不到。", "corrected_sentence": "这些美食是地方性的，外地吃不到。", "error_description": "「地」用错：「地方性」后面的修饰成分应用「的」，「地」只用于修饰动词，不能说「是地方性地」，应说「是地方性的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a4bba19-8ed8-4753-b9db-cb816aed44b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
