INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25348, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自己对做什么、怎么做的想法和主意。", "primary_collocate": null, "pronunciation": "zhǔ zhāng", "ipa": "ʈʂu˨˩˦ ʈʂɑŋ˥˥", "syllable_count": 2, "sentences": [{"text": "你有什么主张，可以直接说出来。", "target_word": "主张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事你自己有主张吗？", "target_word": "主张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个很有主张的人，不太听别人的。", "target_word": "主张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说了自己的主张，会议开了两个小时。", "target_word": "主张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有主张，你们决定吧。", "target_word": "主张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对孩子的学习有自己的主张。", "target_word": "主张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大了，做事有了自己的主张。", "target_word": "主张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的主张很清楚：先存钱，再买房。", "target_word": "主张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板听了每个人的主张，然后做了决定。", "target_word": "主张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的主张是什么？说给我们听听。", "target_word": "主张", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}, {"form": "主張", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：自己对做什么、怎么做的想法和主意（有主张、自己的主张）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a3d56dd-11e0-4e6c-9189-3f9142d08cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25348, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主张", "is_correct": true, "explanation": "正确答案。主张 zhǔzhāng，名词，指自己对做什么、怎么做的想法。"}, {"text": "主涨", "is_correct": false, "explanation": "zhǔzhǎng 与 zhǔzhāng 第二个音节声调不同，“主涨”不是常用词，不能用于此义。"}, {"text": "主掌", "is_correct": false, "explanation": "zhǔzhǎng 与 zhǔzhāng 第二个音节声调不同，意思是掌管。"}, {"text": "助长", "is_correct": false, "explanation": "zhùzhǎng 与 zhǔzhāng 两个音节声调都不同，意思是促进（多指不好的倾向）。"}], "explanations": {"主张": "正确答案。主张 zhǔzhāng，名词，指自己对做什么、怎么做的想法。", "主涨": "zhǔzhǎng 与 zhǔzhāng 第二个音节声调不同，“主涨”不是常用词，不能用于此义。", "主掌": "zhǔzhǎng 与 zhǔzhāng 第二个音节声调不同，意思是掌管。", "助长": "zhùzhǎng 与 zhǔzhāng 两个音节声调都不同，意思是促进（多指不好的倾向）。"}, "sentence_index": null, "correct_answer": "主张"}, "level_3": {"options": [{"text": "主张", "is_correct": true, "explanation": "主张：自己的想法或打算，与“你有什么……可以直接说出来”搭配，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是事物属性，不能指可以直接说出来的想法。"}, {"text": "账单", "is_correct": false, "explanation": "语义：“账单”指付款清单，不是可以说出来的意见。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”不能与“可以直接说出来”搭配，说出来的应是意见或想法。"}], "explanations": {"主张": "主张：自己的想法或打算，与“你有什么……可以直接说出来”搭配，符合句意。", "颜色": "语义：“颜色”是事物属性，不能指可以直接说出来的想法。", "账单": "语义：“账单”指付款清单，不是可以说出来的意见。", "体重": "搭配：“体重”不能与“可以直接说出来”搭配，说出来的应是意见或想法。"}, "sentence_index": 0, "correct_answer": "主张"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每个月都主张一千元。", "explanation": "这里应该用〈存〉。主张表示提出看法，不能用于表示存钱。"}, {"text": "我主张了一本书。", "explanation": "这里应该用〈买〉。主张表示提出看法，不能用于购买东西。"}, {"text": "他订了一个新主张，准备下周实行。", "explanation": "这里应该用〈计划〉。“订”搭配计划，“主张”是看法，不能被订。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25348, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "主张", "is_correct": true, "explanation": "正确答案。主张 zhǔzhāng，名词，指个人对做事的想法或主意。"}, {"text": "主帐", "is_correct": false, "explanation": "zhǔzhàng 与 zhǔzhāng 第二个音节声调不同，指主将的营帐。"}, {"text": "逐张", "is_correct": false, "explanation": "zhúzhāng 与 zhǔzhāng 第一个音节声调不同，意思是一张一张地。"}, {"text": "助涨", "is_correct": false, "explanation": "zhùzhǎng 与 zhǔzhāng 两个音节声调都不同，意思是推动（物价、股价等）上涨。"}], "explanations": {"主张": "正确答案。主张 zhǔzhāng，名词，指个人对做事的想法或主意。", "主帐": "zhǔzhàng 与 zhǔzhāng 第二个音节声调不同，指主将的营帐。", "逐张": "zhúzhāng 与 zhǔzhāng 第一个音节声调不同，意思是一张一张地。", "助涨": "zhùzhǎng 与 zhǔzhāng 两个音节声调都不同，意思是推动（物价、股价等）上涨。"}, "sentence_index": null, "correct_answer": "主张"}, "level_3": {"options": [{"text": "主张", "is_correct": true, "explanation": "主张：个人的想法和主意，与“做事有了自己的”搭配，符合句意。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：“饮料”是饮品，不能指做事的想法，句子意思不通。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“做事有了自己的”后不能接身体数值“体温”。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“眼镜”是物品，不能与“做事有了自己的”搭配。"}], "explanations": {"主张": "主张：个人的想法和主意，与“做事有了自己的”搭配，符合句意。", "饮料": "语义：“饮料”是饮品，不能指做事的想法，句子意思不通。", "体温": "搭配：“做事有了自己的”后不能接身体数值“体温”。", "眼镜": "搭配：“眼镜”是物品，不能与“做事有了自己的”搭配。"}, "sentence_index": 6, "correct_answer": "主张"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他下定了一个新主张，决定戒烟。", "explanation": "这里应该用〈决心〉。“下定”搭配决心，“主张”指想法，不能说“下定主张”。"}, {"text": "他养成了一个主张，就是每天早起。", "explanation": "这里应该用〈习惯〉。“养成”搭配习惯，“主张”指看法，不能被养成。"}, {"text": "她主张了朋友，让他别难过。", "explanation": "这里应该用〈安慰〉。主张是提出并支持看法，不能直接带人作宾语表示安慰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25348, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是个很有主张地人。", "corrected_sentence": "他是个很有主张的人。", "error_description": "“有主张”修饰“人”，名词前应用“的”，写成“地”是误用了修饰动词的标记；正确形式为“很有主张的人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25348, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她提出了一好主张。", "corrected_sentence": "她提出了一个好主张。", "error_description": "漏掉了量词“个”：数词“一”后应接量词，应为“一个好主张”；“一好主张”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
