INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25350, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来做实验或测量东西的工具。", "primary_collocate": null, "pronunciation": "yí qì", "ipa": "i˧˥ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "老师给我们看了一台新仪器。", "target_word": "仪器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做化学实验时要用很多仪器。", "target_word": "仪器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个仪器是用来量温度的。", "target_word": "仪器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用仪器量出了桌子的长度。", "target_word": "仪器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要乱动桌上的仪器。", "target_word": "仪器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小仪器能测出你跑得多快。", "target_word": "仪器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验结束后，要把仪器洗干净。", "target_word": "仪器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仪器上有一个红色的按钮。", "target_word": "仪器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学课上，每组同学都有一套仪器。", "target_word": "仪器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些仪器很贵，用的时候要小心。", "target_word": "仪器", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "套", "label": "量词"}, {"form": "精密仪器", "label": "复合"}, {"form": "测量仪器", "label": "复合"}], "register": "中性", "sense_fingerprint": "做实验或测量东西时用的工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '635621f3-b4f7-4383-9d79-4d5e9f0eff6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25350, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "仪器", "is_correct": true, "explanation": "仪器（yí qì）：用来做实验或测量东西的工具，是正确答案。"}, {"text": "一齐", "is_correct": false, "explanation": "yì qí 两个音节的声调都与 yí qì 不同，意思是“一同、同时”。"}, {"text": "义气", "is_correct": false, "explanation": "yì qì 第一音节声调不同（第四声），意思是讲义气、重情义。"}, {"text": "习气", "is_correct": false, "explanation": "xí qì 与 yí qì 声母不同（x 与 y），意思是积习、坏习惯。"}, {"text": "瓷器", "is_correct": false, "explanation": "cí qì 与 yí qì 声母不同（c 与 y），意思是瓷做的器物。"}], "explanations": {"仪器": "仪器（yí qì）：用来做实验或测量东西的工具，是正确答案。", "一齐": "yì qí 两个音节的声调都与 yí qì 不同，意思是“一同、同时”。", "义气": "yì qì 第一音节声调不同（第四声），意思是讲义气、重情义。", "习气": "xí qì 与 yí qì 声母不同（x 与 y），意思是积习、坏习惯。", "瓷器": "cí qì 与 yí qì 声母不同（c 与 y），意思是瓷做的器物。"}, "sentence_index": null, "correct_answer": "仪器"}, "level_3": {"options": [{"text": "仪器", "is_correct": true, "explanation": "仪器：可以拿给学生看的实验用器具，“一台新”搭配自然。"}, {"text": "汽油", "is_correct": false, "explanation": "搭配：“台”不能修饰液体，“一台新汽油”说不通。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“台”不用于面包，面包没有这样的量词搭配。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“看”的对象是有形的物体，歌曲只能听，不能“看了”。"}], "explanations": {"仪器": "仪器：可以拿给学生看的实验用器具，“一台新”搭配自然。", "汽油": "搭配：“台”不能修饰液体，“一台新汽油”说不通。", "面包": "搭配：“台”不用于面包，面包没有这样的量词搭配。", "歌曲": "语义：“看”的对象是有形的物体，歌曲只能听，不能“看了”。"}, "sentence_index": 0, "correct_answer": "仪器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小提琴是很好的仪器。", "explanation": "这里应该用〈乐器〉。仪器限于做实验和测量用的工具，小提琴这类乐器要说“乐器”。"}, {"text": "客厅的沙发是新买的仪器。", "explanation": "这里应该用〈家具〉。仪器限于做实验和测量的工具，沙发、桌椅等要说“家具”。"}, {"text": "弟弟最喜欢的仪器是遥控飞机。", "explanation": "这里应该用〈玩具〉。仪器用于做实验或测量，遥控飞机这类供玩耍的东西要说“玩具”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25350, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "仪器", "is_correct": true, "explanation": "仪器（yí qì）：用来做实验或测量东西的工具，是正确答案。"}, {"text": "一起", "is_correct": false, "explanation": "yì qǐ 两个音节的声调都与 yí qì 不同，意思是“在一起”。"}, {"text": "一气", "is_correct": false, "explanation": "yī qì 第一音节声调不同（第一声），意思是一股劲儿、一口气。"}, {"text": "石器", "is_correct": false, "explanation": "shí qì 与 yí qì 声母不同（sh 与 y），意思是石头做的工具。"}, {"text": "遗迹", "is_correct": false, "explanation": "yí jì 与 yí qì 第二音节声母不同（j 与 q），意思是遗留下来的古迹。"}], "explanations": {"仪器": "仪器（yí qì）：用来做实验或测量东西的工具，是正确答案。", "一起": "yì qǐ 两个音节的声调都与 yí qì 不同，意思是“在一起”。", "一气": "yī qì 第一音节声调不同（第一声），意思是一股劲儿、一口气。", "石器": "shí qì 与 yí qì 声母不同（sh 与 y），意思是石头做的工具。", "遗迹": "yí jì 与 yí qì 第二音节声母不同（j 与 q），意思是遗留下来的古迹。"}, "sentence_index": null, "correct_answer": "仪器"}, "level_3": {"options": [{"text": "仪器", "is_correct": true, "explanation": "仪器：是实验用的器具，可以清洗，与“实验结束后”相符。"}, {"text": "试卷", "is_correct": false, "explanation": "语义：试卷是纸质品，不能用“洗”来清理。"}, {"text": "讲义", "is_correct": false, "explanation": "语义：讲义是印刷品，不能“洗干净”。"}, {"text": "灰尘", "is_correct": false, "explanation": "搭配：灰尘是被擦掉的，不说“洗干净”。"}], "explanations": {"仪器": "仪器：是实验用的器具，可以清洗，与“实验结束后”相符。", "试卷": "语义：试卷是纸质品，不能用“洗”来清理。", "讲义": "语义：讲义是印刷品，不能“洗干净”。", "灰尘": "搭配：灰尘是被擦掉的，不说“洗干净”。"}, "sentence_index": 6, "correct_answer": "仪器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校的电脑仪器昨天坏了。", "explanation": "这里应该用〈设备〉。仪器限于做实验、测量用的工具，电脑、打印机等要说“设备”。"}, {"text": "城市的公共仪器需要定期维护。", "explanation": "这里应该用〈设施〉。仪器限于做实验和测量，道路、公园等公共设施要说“设施”。"}, {"text": "士兵们的仪器很齐全。", "explanation": "这里应该用〈装备〉。仪器限于做实验和测量用的工具，枪支、头盔等要说“装备”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师借给了我们一张新仪器。", "corrected_sentence": "老师借给了我们一台新仪器。", "error_description": "量词错误：“仪器”应搭配量词“台”，不能用“张”，应说“一台新仪器”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25350, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "实验室里的仪器们都很新。", "corrected_sentence": "实验室里的仪器都很新。", "error_description": "用词错误：“们”一般只用于指人，仪器不能加“们”，应说“仪器都很新”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
