INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25352, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容很小、不容易被察觉的（事情、差别或变化）。", "primary_collocate": null, "pronunciation": "xì wēi", "ipa": "ɕi˥˩ wei˥", "syllable_count": 2, "sentences": [{"text": "他们的想法有细微的不同。", "target_word": "细微", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风很小，树叶只有细微的响声。", "target_word": "细微", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个差别太细微，我没看出来。", "target_word": "细微", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师注意到我细微的进步。", "target_word": "细微", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从细微的小事中看出他的心意。", "target_word": "细微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两张照片的区别非常细微。", "target_word": "细微", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他连最细微的错误也不放过。", "target_word": "细微", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些细微的变化很难发现。", "target_word": "细微", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "声音很细微，要仔细听才行。", "target_word": "细微", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的笑容里有一点细微的变化。", "target_word": "细微", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "細微", "label": "繁体"}], "register": "书面", "sense_fingerprint": "细微|很小很小的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d4eb607-98ba-4d51-a6d8-4ce7b095368b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25352, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "碧绿", "is_correct": false, "explanation": "体貌：碧绿形容颜色，不能修饰想法之间的不同。"}, {"text": "漆黑", "is_correct": false, "explanation": "搭配：漆黑多修饰夜晚、房间，不能说想法的不同很漆黑。"}, {"text": "细微", "is_correct": true, "explanation": "细微：非常微小、不易察觉，修饰“不同”，符合句意。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：清脆形容声音清亮，与想法之间的差别无关。"}], "explanations": {"碧绿": "体貌：碧绿形容颜色，不能修饰想法之间的不同。", "漆黑": "搭配：漆黑多修饰夜晚、房间，不能说想法的不同很漆黑。", "细微": "细微：非常微小、不易察觉，修饰“不同”，符合句意。", "清脆": "语义：清脆形容声音清亮，与想法之间的差别无关。"}, "sentence_index": 0, "correct_answer": "细微"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是个细微的小伙子，力气很大。", "explanation": "这里应该用〈高大〉。细微形容微小到不易察觉的事物，不能用来形容人的身材；说身材大要用高大。"}, {"text": "这台机器很细微，占满了整个车间。", "explanation": "这里应该用〈庞大〉。细微不能形容机器的体积；说体积大要用庞大。"}, {"text": "草原细微无边，一眼望不到头。", "explanation": "这里应该用〈广阔〉。细微不能形容草原的范围；说范围大要用广阔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09c1a456-368b-41a2-b07c-9cbaedc141f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25352, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "甜美", "is_correct": false, "explanation": "搭配：甜美多形容声音、笑容，不能用来修饰错误。"}, {"text": "冰凉", "is_correct": false, "explanation": "语义：冰凉形容温度低，与错误的大小或轻重无关。"}, {"text": "细微", "is_correct": true, "explanation": "细微：非常小、不易察觉，修饰“错误”，符合句意。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：高大形容体形，不能用来修饰错误。"}], "explanations": {"甜美": "搭配：甜美多形容声音、笑容，不能用来修饰错误。", "冰凉": "语义：冰凉形容温度低，与错误的大小或轻重无关。", "细微": "细微：非常小、不易察觉，修饰“错误”，符合句意。", "高大": "体貌：高大形容体形，不能用来修饰错误。"}, "sentence_index": 6, "correct_answer": "细微"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市很细微，夜里很热闹。", "explanation": "这里应该用〈繁华〉。细微形容微小、不易察觉，不能形容城市的繁华程度；说繁华要用繁华。"}, {"text": "这套房子很细微，有三个卧室。", "explanation": "这里应该用〈宽敞〉。细微不能形容房屋的空间大小；说空间大要用宽敞。"}, {"text": "饭桌上的饭菜很细微，非常香。", "explanation": "这里应该用〈丰盛〉。细微不能形容饭菜的数量；说饭菜多要用丰盛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09c1a456-368b-41a2-b07c-9cbaedc141f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块玻璃上有一道细微地划痕。", "corrected_sentence": "这块玻璃上有一道细微的划痕。", "error_description": "错误：“细微地划痕”，“地”误用。修饰名词要用“的”，应为“细微的划痕”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09c1a456-368b-41a2-b07c-9cbaedc141f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个问题很细微的，大家都没注意。", "corrected_sentence": "这个问题很细微，大家都没注意。", "error_description": "错误：“很细微的”，句末多加“的”。作谓语的形容词后面不加“的”，应为“很细微”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09c1a456-368b-41a2-b07c-9cbaedc141f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
