INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25354, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "法律条文就是写下来的规则。", "primary_collocate": null, "pronunciation": "fǎ lǜ tiáo wén", "ipa": "fa˨˩˦ ly˥˩ tʰjɑʊ˧˥ wən˧˥", "syllable_count": 4, "sentences": [{"text": "法律条文写在一本厚书里。", "target_word": "法律条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都应该遵守法律条文。", "target_word": "法律条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了几条法律条文。", "target_word": "法律条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些法律条文是去年写好的。", "target_word": "法律条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察要先了解法律条文，才能工作。", "target_word": "法律条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律条文告诉我们什么可以做，什么不可以做。", "target_word": "法律条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在网上查到了这条法律条文。", "target_word": "法律条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律条文里写着，小孩不能一个人开车。", "target_word": "法律条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道规则，就去读法律条文。", "target_word": "法律条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份法律条文只有两页。", "target_word": "法律条文", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "法律條文", "label": "繁体"}], "register": "正式", "sense_fingerprint": "写下来的法律规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2add0e14-7aad-4c53-8a62-eca53035b254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25354, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是能写在书里的规则文字，与“写在一本厚书里”冲突。"}, {"text": "法律条文", "is_correct": true, "explanation": "“法律条文”是写下来的规则，可以写在书里，与句意相符。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮品，不能写在书里，句子无法成立。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：“写”的对象通常是文字或内容，“阳光”不能被写在书里。"}], "explanations": {"天气": "语义：“天气”不是能写在书里的规则文字，与“写在一本厚书里”冲突。", "法律条文": "“法律条文”是写下来的规则，可以写在书里，与句意相符。", "咖啡": "语义：咖啡是饮品，不能写在书里，句子无法成立。", "阳光": "搭配：“写”的对象通常是文字或内容，“阳光”不能被写在书里。"}, "sentence_index": 0, "correct_answer": "法律条文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国签订了法律条文。", "explanation": "这里应该用〈协议〉。签订的是协议、合同，法律条文是写下来的规定，不能签订。"}, {"text": "法院作出了法律条文。", "explanation": "这里应该用〈判决〉。法院作出的是判决，法律条文是被引用、遵守的规定，不能“作出”。"}, {"text": "他学的是法律条文专业。", "explanation": "这里应该用〈法学〉。学科名称是“法学”或“法律专业”，“法律条文”只是规则的条款，不能作为专业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6aa91466-dc51-4c64-a00f-5d786ecfea41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25354, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尾巴", "is_correct": false, "explanation": "语义：“尾巴”是身体部位，不是可以在网上查到的内容，与“查到”冲突。"}, {"text": "法律条文", "is_correct": true, "explanation": "“法律条文”是可以在网上查到的内容，与句意相符。"}, {"text": "胳膊", "is_correct": false, "explanation": "搭配：“查到”一般接信息、资料，身体部位不能被“查到”。"}, {"text": "腿", "is_correct": false, "explanation": "语义：“腿”是身体部位，不是查询的对象，与“在网上查到了这条”的语义冲突。"}], "explanations": {"尾巴": "语义：“尾巴”是身体部位，不是可以在网上查到的内容，与“查到”冲突。", "法律条文": "“法律条文”是可以在网上查到的内容，与句意相符。", "胳膊": "搭配：“查到”一般接信息、资料，身体部位不能被“查到”。", "腿": "语义：“腿”是身体部位，不是查询的对象，与“在网上查到了这条”的语义冲突。"}, "sentence_index": 6, "correct_answer": "法律条文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只法律条文我读了三遍。", "explanation": "这里应该用〈条〉。“只”多用于动物或成对的东西，法律条文应用“条”。"}, {"text": "这朵法律条文很薄，我一下就读完了。", "explanation": "这里应该用〈条〉。“朵”多用于花、云等，法律条文应用“条”。"}, {"text": "这颗法律条文我抄在了笔记本上。", "explanation": "这里应该用〈条〉。“颗”用于小而圆的东西，法律条文应用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6aa91466-dc51-4c64-a00f-5d786ecfea41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25354, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们读了这些法律条文们。", "corrected_sentence": "我们读了这些法律条文。", "error_description": "后缀错误：“们”只用于指人，“法律条文”是事物，后面不能加“们”，应说“这些法律条文”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6aa91466-dc51-4c64-a00f-5d786ecfea41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25354, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师给我们讲解了一首法律条文。", "corrected_sentence": "老师给我们讲解了一条法律条文。", "error_description": "量词错误：“首”用于诗词、歌曲，“法律条文”应用量词“条”，应说“一条法律条文”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6aa91466-dc51-4c64-a00f-5d786ecfea41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
