INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25358, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "农民在田里做让庄稼长大的事情。", "primary_collocate": null, "pronunciation": "gēng zuò", "ipa": "kɤŋ˥ tsuo˥˩", "syllable_count": 2, "sentences": [{"text": "传统耕作很辛苦。", "target_word": "耕作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机器让现代耕作轻松多了。", "target_word": "耕作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的耕作方式很特别。", "target_word": "耕作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天是耕作最忙的时候。", "target_word": "耕作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就熟悉田里的耕作。", "target_word": "耕作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "耕作需要好天气和足够的水。", "target_word": "耕作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水少会影响今年的耕作。", "target_word": "耕作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人给孩子们讲过去的耕作故事。", "target_word": "耕作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区的耕作条件不太好。", "target_word": "耕作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的耕作能让庄稼长得更好。", "target_word": "耕作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "耕作制度", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "农民在田里种庄稼的农事活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba9e274-b8ab-4e4c-bbe4-4a904cae9285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25358, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耕作", "is_correct": true, "explanation": "正确：“传统耕作”指传统的农事活动，说它很辛苦，合理。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑是言语行为，不能说“很辛苦”，句子说不通。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”的对象是客人、人员，不说“传统欢迎”，也不说“很辛苦”。"}, {"text": "祝福", "is_correct": false, "explanation": "搭配：“祝福”的对象是人，不能用“传统祝福”来修饰，更不说很辛苦。"}], "explanations": {"耕作": "正确：“传统耕作”指传统的农事活动，说它很辛苦，合理。", "嘲笑": "语义：嘲笑是言语行为，不能说“很辛苦”，句子说不通。", "欢迎": "搭配：“欢迎”的对象是客人、人员，不说“传统欢迎”，也不说“很辛苦”。", "祝福": "搭配：“祝福”的对象是人，不能用“传统祝福”来修饰，更不说很辛苦。"}, "sentence_index": 0, "correct_answer": "耕作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂的耕作很高效。", "explanation": "这里应该用〈生产〉。耕作指在田里种庄稼，工厂的产出要说生产。"}, {"text": "他把耕作装进了书包。", "explanation": "这里应该用〈东西〉。耕作指种田的活动，是动作而不是可以装进书包的物品。"}, {"text": "孩子们在教室里耕作。", "explanation": "耕作是在田地里进行的农事，教室不是田地，应说上课或学习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25358, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耕作", "is_correct": true, "explanation": "正确：“影响今年的耕作”指影响农事，与雨水少的因果相连。"}, {"text": "词典", "is_correct": false, "explanation": "语义：“词典”是工具书，雨水少不会影响词典。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：雨水少与鞋子之间没有因果关系，句子不合理。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“影响”的对象多为收成、生活等，不能说影响今年的音乐。"}], "explanations": {"耕作": "正确：“影响今年的耕作”指影响农事，与雨水少的因果相连。", "词典": "语义：“词典”是工具书，雨水少不会影响词典。", "鞋子": "语义：雨水少与鞋子之间没有因果关系，句子不合理。", "音乐": "搭配：“影响”的对象多为收成、生活等，不能说影响今年的音乐。"}, "sentence_index": 6, "correct_answer": "耕作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天耕作，做了一桌子饭菜。", "explanation": "这里应该用〈烹饪〉或〈做〉。耕作指在田里种庄稼，做饭要用烹饪。"}, {"text": "修路耕作很耗时间。", "explanation": "这里应该用〈施工〉。耕作指农事，修路属于工程，不能说修路耕作。"}, {"text": "这台电脑的耕作效率很高，每天能处理上万条数据。", "explanation": "这里应该用〈运作〉。耕作只指农田里的农事活动，电脑处理数据的效率不能说耕作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25358, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只耕作很辛苦。", "corrected_sentence": "这次耕作很辛苦。", "error_description": "“耕作”指一次农事活动，量词应用“次”，“只”多用于动物或单个物件，应说“这次耕作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25358, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民正在耕作过。", "corrected_sentence": "农民正在耕作。", "error_description": "“正在”表示动作进行中，不能与表示经历的“过”同用，应说“农民正在耕作”，去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
