INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25368, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "过去留下的东西。", "primary_collocate": null, "pronunciation": "yí cún", "ipa": "i˧˥ tsʰuən˧˥", "syllable_count": 2, "sentences": [{"text": "这口老井是村里最古老的遗存。", "target_word": "遗存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老街上还能看到几处旧时代的遗存。", "target_word": "遗存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块石碑是祖先留给我们的遗存。", "target_word": "遗存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山洞里的遗存说明，几千年前这里有人住过。", "target_word": "遗存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下的遗存不能随便挖，要先请专家来看。", "target_word": "遗存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这批遗存是战争时期留下的，很有纪念意义。", "target_word": "遗存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些遗存大多已经破旧，需要小心修复。", "target_word": "遗存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的老戏台是几百年前的遗存。", "target_word": "遗存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在海边看到了古代渔村的遗存。", "target_word": "遗存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些遗存虽然很旧，但是对研究历史很有用。", "target_word": "遗存", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "处", "label": "量词"}, {"form": "批", "label": "量词"}, {"form": "古代遗存", "label": "复合"}, {"form": "遺存", "label": "繁体"}], "register": "书面", "sense_fingerprint": "过去留下来的具体东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d4eb607-98ba-4d51-a6d8-4ce7b095368b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25368, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歌曲", "is_correct": false, "explanation": "语义：井是古迹，不是歌曲，“最古老的歌曲”与句意不合。"}, {"text": "遗存", "is_correct": true, "explanation": "遗存：指过去留下来的具体物件，与“老井”所指相合，符合句意。"}, {"text": "课本", "is_correct": false, "explanation": "语义：老井是村里的古老遗留物，不能说成课本，句意不通。"}, {"text": "脸庞", "is_correct": false, "explanation": "体貌：“脸庞”指人的面容，不能用来形容一口老井。"}], "explanations": {"歌曲": "语义：井是古迹，不是歌曲，“最古老的歌曲”与句意不合。", "遗存": "遗存：指过去留下来的具体物件，与“老井”所指相合，符合句意。", "课本": "语义：老井是村里的古老遗留物，不能说成课本，句意不通。", "脸庞": "体貌：“脸庞”指人的面容，不能用来形容一口老井。"}, "sentence_index": 0, "correct_answer": "遗存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是烈士的遗存，从小由叔叔抚养。", "explanation": "这里应该用〈遗孤〉。遗孤指死者留下的子女，遗存只指物件或痕迹，不指人。"}, {"text": "他在老街上买了一本遗存。", "explanation": "这里应该用〈件〉。遗存是具体的遗留物，“本”用于书册，不用于遗存。"}, {"text": "老人临终前说出了自己的遗存。", "explanation": "这里应该用〈遗愿〉。遗愿指临终前的心愿，遗存指过去留下的物件和痕迹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09c1a456-368b-41a2-b07c-9cbaedc141f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25368, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晚霞", "is_correct": false, "explanation": "语义：晚霞是天空中的光彩，不会破旧，也不需要修复。"}, {"text": "遗存", "is_correct": true, "explanation": "遗存：指过去留下的物件，会破旧，需要小心修复，符合句意。"}, {"text": "气温", "is_correct": false, "explanation": "搭配：“破旧”只用于器物或建筑，不能用来形容气温。"}, {"text": "闪电", "is_correct": false, "explanation": "语义：闪电转瞬即逝，不会破旧，也不需要修复。"}], "explanations": {"晚霞": "语义：晚霞是天空中的光彩，不会破旧，也不需要修复。", "遗存": "遗存：指过去留下的物件，会破旧，需要小心修复，符合句意。", "气温": "搭配：“破旧”只用于器物或建筑，不能用来形容气温。", "闪电": "语义：闪电转瞬即逝，不会破旧，也不需要修复。"}, "sentence_index": 6, "correct_answer": "遗存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷留下的遗存叮嘱我们要善待他人。", "explanation": "这里应该用〈遗训〉。遗训指前人留下的教导，遗存指过去留下的物件和痕迹，不指教导。"}, {"text": "他在博物馆里看到了一首古代遗存。", "explanation": "这里应该用〈件〉。“首”用于诗歌，遗存是遗留下来的古物，不能用“首”计量。"}, {"text": "这笔遗存是他从父亲那里继承来的。", "explanation": "这里应该用〈遗产〉。遗产指可以继承的财产，遗存指古代或过去留下的物件和痕迹，不指财产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09c1a456-368b-41a2-b07c-9cbaedc141f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25368, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人在地下发现了一首古代遗存，并立即通知了文物部门。", "corrected_sentence": "工人在地下发现了一批古代遗存，并立即通知了文物部门。", "error_description": "量词错误：“首”用于诗歌歌曲，遗存应说“一批”或“一处”，不能用“首”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09c1a456-368b-41a2-b07c-9cbaedc141f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25368, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些遗存们在地下埋了几百年，现在都已经破旧了。", "corrected_sentence": "这些遗存在地下埋了几百年，现在都已经破旧了。", "error_description": "“们”只用于指人的名词，遗存是无生命的事物，应说“这些遗存”，不能说“这些遗存们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09c1a456-368b-41a2-b07c-9cbaedc141f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
