INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25370, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人类学是研究人类怎么生活、怎么变化的学问。", "primary_collocate": null, "pronunciation": "rén lèi xué", "ipa": "ʐən˧˥ lei˥˩ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "人类学是研究人类生活和变化的学问。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐在大学学人类学，常常去农村住。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学人类学的人，喜欢和不同的人聊天。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类学让我明白，每个民族的生活都不一样。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用人类学的方法，看看这里的人怎么过节。", "target_word": "人类学", "complexity_tier": "T3", "furigana": "tā xiǎng yòng rén lèi xué de fāng fǎ, kàn kan zhè lǐ de rén zěn me guò jié.", "sentence_source": "generated"}, {"text": "这个周末我要去听一个人类学的讲座。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上大学以后，她第一次听说人类学。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类学研究人怎么生活，历史学研究过去的事。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王学了三年人类学，去过很多地方。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想知道人怎么生活和变化，可以读人类学。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人类学家", "label": "复合"}, {"form": "文化人类学", "label": "复合"}, {"form": "人類學", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：研究人怎么生活、怎么变化的学问（学人类学）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a3d56dd-11e0-4e6c-9189-3f9142d08cf1') 