INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25370, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人类学", "is_correct": true, "explanation": "人类学：研究人类生活与变化的学问，作主语，句意通顺。"}, {"text": "气候", "is_correct": false, "explanation": "语义：“气候”是天气的长期状况，不是研究人类生活的学问。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“厨房”是场所，不能作“学问”的主语。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，不能被说成研究人类生活的学问。"}], "explanations": {"人类学": "人类学：研究人类生活与变化的学问，作主语，句意通顺。", "气候": "语义：“气候”是天气的长期状况，不是研究人类生活的学问。", "厨房": "搭配：“厨房”是场所，不能作“学问”的主语。", "体温": "语义：“体温”指身体的温度，不能被说成研究人类生活的学问。"}, "sentence_index": 0, "correct_answer": "人类学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人类学研究山川河流的分布。", "explanation": "这里应该用〈地理学〉。人类学研究人的生活与变化，山川河流的分布属于地理学。"}, {"text": "人类学研究数量和图形的规律。", "explanation": "这里应该用〈数学〉。人类学研究人类社会与文化，数量和图形的规律属于数学。"}, {"text": "人类学研究天气的变化规律。", "explanation": "这里应该用〈气象学〉。人类学研究人的生活与变化，天气的变化规律属于气象学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25370, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人类学", "is_correct": true, "explanation": "人类学：可以听说的一门学问，与“听说”搭配，句意通顺。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“听说”的对象应是消息或事情，“冰箱”不构成可以听说的内容。"}, {"text": "手套", "is_correct": false, "explanation": "语义：“手套”不是可以听说的消息或学问，句意不通。"}, {"text": "闹钟", "is_correct": false, "explanation": "搭配：“听说”后接的是消息或事情，不能与“闹钟”搭配。"}], "explanations": {"人类学": "人类学：可以听说的一门学问，与“听说”搭配，句意通顺。", "冰箱": "语义：“听说”的对象应是消息或事情，“冰箱”不构成可以听说的内容。", "手套": "语义：“手套”不是可以听说的消息或学问，句意不通。", "闹钟": "搭配：“听说”后接的是消息或事情，不能与“闹钟”搭配。"}, "sentence_index": 6, "correct_answer": "人类学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人类学研究物体的运动和力的关系。", "explanation": "这里应该用〈物理学〉。人类学研究人的生活与变化，物体的运动和力的关系属于物理学。"}, {"text": "人类学研究岩石是怎样形成的。", "explanation": "这里应该用〈地质学〉。人类学研究人的生活与变化，岩石的形成属于地质学。"}, {"text": "人类学研究庄稼怎么种。", "explanation": "这里应该用〈农学〉。人类学研究人类社会与文化，庄稼的种植属于农学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他毕业后在博物馆工作，学的是人类学的。", "corrected_sentence": "他毕业后在博物馆工作，学的是人类学。", "error_description": "“的”多余：“学的是……”结构中，宾语“人类学”后不能再加“的”，应说“学的是人类学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前学了过人类学。", "corrected_sentence": "他以前学过人类学。", "error_description": "体貌错误：表示经历用“过”，不能与“了”叠用，应说“学过人类学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
