INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25374, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大坝是挡住水的墙。", "primary_collocate": null, "pronunciation": "dà bà", "ipa": "tɑ˥˩ pɑ˥˩", "syllable_count": 2, "sentences": [{"text": "大坝是挡住河水的一堵墙。", "target_word": "大坝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水太大，大坝挡住了水。", "target_word": "大坝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们站在大坝上看河水。", "target_word": "大坝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座大坝又高又长，水过不去。", "target_word": "大坝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大坝坏了，水就流进了村子。", "target_word": "大坝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨以后，大坝前面的水很多。", "target_word": "大坝", "complexity_tier": "T3", "furigana": "xià dà yǔ yǐ hòu, dàbà qiánmiàn de shuǐ hěn duō", "sentence_source": "generated"}, {"text": "工人在大坝上检查墙有没有裂缝。", "target_word": "大坝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了大坝，村子里的人不怕洪水。", "target_word": "大坝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着大坝走到了河边。", "target_word": "大坝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大坝挡着水，下游的河很浅。", "target_word": "大坝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座大坝", "label": "量词"}, {"form": "大壩", "label": "繁体"}], "register": "中性", "sense_fingerprint": "像墙一样挡住河水的高大建筑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312fe292-15c3-4f5b-baf9-ae90a590e823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25374, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大坝", "is_correct": true, "explanation": "正确答案：读 dà bà，指挡住河水的高大建筑。"}, {"text": "大伯", "is_correct": false, "explanation": "第二个音节声调不同：bó（第二声）与 bà（第四声）不同，意思是父亲的哥哥。"}, {"text": "大骂", "is_correct": false, "explanation": "第二个音节声母不同：mà 与 bà 的声母 m、b 不同，意思是严厉地责骂。"}, {"text": "大棒", "is_correct": false, "explanation": "第二个音节韵母不同：bàng 比 bà 多了 ng，意思是粗棍子。"}, {"text": "大巴", "is_correct": false, "explanation": "第二个音节声调不同：bā（第一声）与 bà（第四声）不同，意思是大型客车。"}], "explanations": {"大坝": "正确答案：读 dà bà，指挡住河水的高大建筑。", "大伯": "第二个音节声调不同：bó（第二声）与 bà（第四声）不同，意思是父亲的哥哥。", "大骂": "第二个音节声母不同：mà 与 bà 的声母 m、b 不同，意思是严厉地责骂。", "大棒": "第二个音节韵母不同：bàng 比 bà 多了 ng，意思是粗棍子。", "大巴": "第二个音节声调不同：bā（第一声）与 bà（第四声）不同，意思是大型客车。"}, "sentence_index": null, "correct_answer": "大坝"}, "level_3": {"options": [{"text": "大坝", "is_correct": true, "explanation": "大坝：挡住河水的高大建筑，正是句子要说的事物。"}, {"text": "小船", "is_correct": false, "explanation": "语义：小船能载人，不能挡住河水，与“挡住河水的一堵墙”相矛盾。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是种花草的地方，不具备挡住河水的功能。"}, {"text": "家伙", "is_correct": false, "explanation": "语域：“家伙”是口语词，指代东西时随意，与这样的定义式语体不合，也无法挡水。"}], "explanations": {"大坝": "大坝：挡住河水的高大建筑，正是句子要说的事物。", "小船": "语义：小船能载人，不能挡住河水，与“挡住河水的一堵墙”相矛盾。", "花园": "语义：花园是种花草的地方，不具备挡住河水的功能。", "家伙": "语域：“家伙”是口语词，指代东西时随意，与这样的定义式语体不合，也无法挡水。"}, "sentence_index": 0, "correct_answer": "大坝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座大坝很厚，讲了很多历史故事。", "explanation": "这里应该用〈书〉。书可以讲故事，大坝是挡水的墙或建筑，不能讲故事。"}, {"text": "下大雨前，工人会把大坝关上。", "explanation": "这里应该用〈水闸〉。关闭的是闸门，大坝是整座拦水的建筑，不能说“关上大坝”。"}, {"text": "这个暑假，我们在大坝里游泳。", "explanation": "这里应该用〈水库〉。游泳要在水库或河里，大坝是拦水的建筑，人不能在里面游泳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25374, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大坝", "is_correct": true, "explanation": "正确答案：读 dà bà，指挡住河水的高大建筑。"}, {"text": "大把", "is_correct": false, "explanation": "第二个音节声调不同：bǎ（第三声）与 bà（第四声）不同，意思是很多。"}, {"text": "打靶", "is_correct": false, "explanation": "两个音节声调都不同：dǎ（第三声）、bǎ（第三声），意思是朝靶子射击。"}, {"text": "大半", "is_correct": false, "explanation": "第二个音节韵母不同：bàn 比 bà 多了 n，意思是大部分。"}, {"text": "大败", "is_correct": false, "explanation": "第二个音节韵母不同：bài 比 bà 多了 i，意思是惨败。"}], "explanations": {"大坝": "正确答案：读 dà bà，指挡住河水的高大建筑。", "大把": "第二个音节声调不同：bǎ（第三声）与 bà（第四声）不同，意思是很多。", "打靶": "两个音节声调都不同：dǎ（第三声）、bǎ（第三声），意思是朝靶子射击。", "大半": "第二个音节韵母不同：bàn 比 bà 多了 n，意思是大部分。", "大败": "第二个音节韵母不同：bài 比 bà 多了 i，意思是惨败。"}, "sentence_index": null, "correct_answer": "大坝"}, "level_3": {"options": [{"text": "大坝", "is_correct": true, "explanation": "大坝：工人可以站在上面检查的建筑，句意合理。"}, {"text": "天空", "is_correct": false, "explanation": "语义：工人不能站在天空上检查墙，“天空”不是可以站人的地方。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴不能让人站上去检查墙面，句子说的是可以走上去的建筑。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这段叙述的语体不合，也不能让人站上去检查墙。"}], "explanations": {"大坝": "大坝：工人可以站在上面检查的建筑，句意合理。", "天空": "语义：工人不能站在天空上检查墙，“天空”不是可以站人的地方。", "钢琴": "语义：钢琴不能让人站上去检查墙面，句子说的是可以走上去的建筑。", "玩意儿": "语域：“玩意儿”是口语说法，与这段叙述的语体不合，也不能让人站上去检查墙。"}, "sentence_index": 6, "correct_answer": "大坝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座大坝很快，能开到一百公里。", "explanation": "这里应该用〈汽车〉。汽车用来开，能开多快；大坝是挡水的建筑，不能开，也谈不上速度。"}, {"text": "这座大坝很好听，大家都喜欢唱。", "explanation": "这里应该用〈歌〉。歌可以好听、可以唱；大坝是挡水的建筑，不能唱，也不能说好听。"}, {"text": "这座大坝很香，开得很漂亮。", "explanation": "这里应该用〈花〉。花有香味，会开；大坝没有香味，也不会开花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村子旁边有一只大坝，又高又长。", "corrected_sentence": "村子旁边有一座大坝，又高又长。", "error_description": "量词错：大坝应说“座”；“只”用于动物或成对的东西，不能用来数大坝。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "游客们站大坝上拍照。", "corrected_sentence": "游客们站在大坝上拍照。", "error_description": "介词错：处所词「大坝」前面缺少介词「在」，「站大坝上」不成句。应为「站在大坝上」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25376, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浓缩", "is_correct": true, "explanation": "浓缩指使液体浓度增加，与淡化（使浓度变低）互为反义。"}, {"text": "过滤", "is_correct": false, "explanation": "语义：“过滤”是用滤网分离杂质，与浓度的增减无关。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：“冷冻”是降温使物体变硬，与浓度的增减无关。"}, {"text": "搅拌", "is_correct": false, "explanation": "语义：“搅拌”是使物体混合均匀，与浓度的变化方向无关。"}], "correct_answer": "浓缩", "explanations": {"浓缩": "浓缩指使液体浓度增加，与淡化（使浓度变低）互为反义。", "过滤": "语义：“过滤”是用滤网分离杂质，与浓度的增减无关。", "冷冻": "语义：“冷冻”是降温使物体变硬，与浓度的增减无关。", "搅拌": "语义：“搅拌”是使物体混合均匀，与浓度的变化方向无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25376, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浓缩", "is_correct": true, "explanation": "浓缩指使液体浓度增加，与淡化（使浓度变低）互为反义。"}, {"text": "煮沸", "is_correct": false, "explanation": "语义：“煮沸”是加热到沸腾，不表示浓度的增减关系。"}, {"text": "蒸发", "is_correct": false, "explanation": "语义：“蒸发”是液体变成气体，不与淡化构成反义关系。"}, {"text": "冷藏", "is_correct": false, "explanation": "语义：“冷藏”是低温保存，与浓度的增减无关。"}], "correct_answer": "浓缩", "explanations": {"浓缩": "浓缩指使液体浓度增加，与淡化（使浓度变低）互为反义。", "煮沸": "语义：“煮沸”是加热到沸腾，不表示浓度的增减关系。", "蒸发": "语义：“蒸发”是液体变成气体，不与淡化构成反义关系。", "冷藏": "语义：“冷藏”是低温保存，与浓度的增减无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25376, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得不那么浓，比如让盐水变淡。", "primary_collocate": null, "pronunciation": "dàn huà", "ipa": "tan˥˩ xua˥˩", "syllable_count": 2, "sentences": [{"text": "工人用清水淡化盐水。", "target_word": "淡化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器可以淡化海水，变成饮用水。", "target_word": "淡化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加一点水就能淡化太浓的果汁。", "target_word": "淡化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把深色的颜料加水淡化了。", "target_word": "淡化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太咸的汤，加点开水就可以淡化。", "target_word": "淡化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用雨水淡化土地里的盐。", "target_word": "淡化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗了几次以后，衣服上的红色淡化了。", "target_word": "淡化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把药水淡化一下，孩子才能喝。", "target_word": "淡化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里的盐水需要用蒸馏水淡化。", "target_word": "淡化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她往太浓的咖啡里加了一点水，把咖啡淡化了。", "target_word": "淡化", "complexity_tier": "T3", "furigana": "tā wǎng tài nóng de kā fēi lǐ jiā le yì diǎn shuǐ, bǎ kā fēi dàn huà le.", "sentence_source": "generated"}], "morphological_forms": [{"form": "淡化了", "label": "体标"}, {"form": "淡化过", "label": "体标"}, {"form": "海水淡化", "label": "复合"}], "register": "中性", "sense_fingerprint": "使液体或颜色的浓度变低", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '635621f3-b4f7-4383-9d79-4d5e9f0eff6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25376, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "淡化", "is_correct": true, "explanation": "dàn huà，意思是使液体或颜色的浓度变低。"}, {"text": "汉化", "is_correct": false, "explanation": "hàn 与 dàn 声母不同（h 与 d），意思是本地化，如把游戏汉化。"}, {"text": "碳化", "is_correct": false, "explanation": "tàn 与 dàn 声母不同（t 与 d），意思是变成碳的化学过程。"}, {"text": "泛化", "is_correct": false, "explanation": "fàn 与 dàn 声母不同（f 与 d），声调相同，意思是范围变宽、概括化。"}, {"text": "蛋花", "is_correct": false, "explanation": "huā 与 huà 声调不同（第一声与第四声），意思是蛋花，如蛋花汤。"}], "explanations": {"淡化": "dàn huà，意思是使液体或颜色的浓度变低。", "汉化": "hàn 与 dàn 声母不同（h 与 d），意思是本地化，如把游戏汉化。", "碳化": "tàn 与 dàn 声母不同（t 与 d），意思是变成碳的化学过程。", "泛化": "fàn 与 dàn 声母不同（f 与 d），声调相同，意思是范围变宽、概括化。", "蛋花": "huā 与 huà 声调不同（第一声与第四声），意思是蛋花，如蛋花汤。"}, "sentence_index": null, "correct_answer": "淡化"}, "level_3": {"options": [{"text": "淡化", "is_correct": true, "explanation": "淡化：加清水使盐水变淡，与用清水的语境相合。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：“冷冻”是降温使液体凝固，与用清水加水稀释的意思不符。"}, {"text": "煮沸", "is_correct": false, "explanation": "语义：“煮沸”是加热到沸腾，并不是加清水。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”用于物品的美化，不能用于盐水。"}], "explanations": {"淡化": "淡化：加清水使盐水变淡，与用清水的语境相合。", "冷冻": "语义：“冷冻”是降温使液体凝固，与用清水加水稀释的意思不符。", "煮沸": "语义：“煮沸”是加热到沸腾，并不是加清水。", "装饰": "搭配：“装饰”用于物品的美化，不能用于盐水。"}, "sentence_index": 0, "correct_answer": "淡化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天到了，冰块慢慢淡化了。", "explanation": "这里应该用〈融化〉。淡化指液体或颜色的浓度变低，冰块由固体变成液体要用融化。"}, {"text": "铁块放在桌上，慢慢淡化了。", "explanation": "这里应该用〈冷却〉。淡化指浓度变低，温度下降要用冷却，铁块这类实物不能被淡化。"}, {"text": "她用砂纸把木头淡化了一下。", "explanation": "这里应该用〈打磨〉。淡化指溶液或颜色的浓度变低，用砂纸处理木头要说打磨，木头不能被淡化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25376, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "淡化", "is_correct": true, "explanation": "dàn huà，意思是使液体或颜色的浓度变低。"}, {"text": "炭画", "is_correct": false, "explanation": "tàn 与 dàn 声母不同（t 与 d），意思是用炭笔画的画。"}, {"text": "弹花", "is_correct": false, "explanation": "tán 与 dàn 声调不同（第二声与第四声），huā 与 huà 声调也不同，意思是弹松棉花。"}, {"text": "大化", "is_correct": false, "explanation": "dà 与 dàn 仅韵尾不同（有无 n），意思是日本大化改新的年号。"}, {"text": "谈话", "is_correct": false, "explanation": "tán 与 dàn 声母不同（t 与 d）且声调不同，意思是交谈。"}], "explanations": {"淡化": "dàn huà，意思是使液体或颜色的浓度变低。", "炭画": "tàn 与 dàn 声母不同（t 与 d），意思是用炭笔画的画。", "弹花": "tán 与 dàn 声调不同（第二声与第四声），huā 与 huà 声调也不同，意思是弹松棉花。", "大化": "dà 与 dàn 仅韵尾不同（有无 n），意思是日本大化改新的年号。", "谈话": "tán 与 dàn 声母不同（t 与 d）且声调不同，意思是交谈。"}, "sentence_index": null, "correct_answer": "淡化"}, "level_3": {"options": [{"text": "淡化", "is_correct": true, "explanation": "淡化：洗涤后颜色变浅，与语境相合。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”是固体遇热变成液体，颜色不会因此变浅。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：“凝固”是液体变成固体，与颜色变浅无关。"}, {"text": "上涨", "is_correct": false, "explanation": "搭配：“上涨”搭配价格、水位，不能用于颜色。"}], "explanations": {"淡化": "淡化：洗涤后颜色变浅，与语境相合。", "融化": "语义：“融化”是固体遇热变成液体，颜色不会因此变浅。", "凝固": "语义：“凝固”是液体变成固体，与颜色变浅无关。", "上涨": "搭配：“上涨”搭配价格、水位，不能用于颜色。"}, "sentence_index": 6, "correct_answer": "淡化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他淡化了百米纪录，大家很兴奋。", "explanation": "这里应该用〈刷新〉。纪录要被刷新，不能说淡化纪录，淡化指浓度或程度变低。"}, {"text": "工厂的规模淡化了，生产减少。", "explanation": "这里应该用〈缩小〉。规模的变小要用缩小，淡化说的是浓度或程度变低。"}, {"text": "这次台风淡化了受灾区域。", "explanation": "这里应该用〈扩大〉。区域的范围变大要用扩大，淡化不用于表示范围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把浓咖啡淡化。", "corrected_sentence": "她把浓咖啡淡化了一点。", "error_description": "“把”字句中“淡化”后缺少补语，不完整。应说“把浓咖啡淡化了一点”，不能只说“把浓咖啡淡化”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "加点水，颜色就淡化很快。", "corrected_sentence": "加点水，颜色就淡化得很快。", "error_description": "补语前漏掉“得”。“淡化”带补语时要说“淡化得很快”，不能说“淡化很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
