INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25378, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25378, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "根扎得很深。", "primary_collocate": null, "pronunciation": "shēn zhí", "ipa": "ʂən˥ ʈʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "这棵老树的根深植在土里。", "target_word": "深植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大树深植于山坡上，不怕大风。", "target_word": "深植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "竹子的根深植地下，风吹不倒。", "target_word": "深植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里的草，根深植沙中，才能找到水。", "target_word": "深植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些松树的根深植在石头缝里。", "target_word": "深植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为根深植泥土，大树没有倒。", "target_word": "深植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花的根深植在湿地里，很难拔。", "target_word": "深植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的柳树根深植水边的泥里。", "target_word": "深植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了不被风吹倒，农民让树苗的根深植土中。", "target_word": "深植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老榕树的根深植在村口，已经几百年了。", "target_word": "深植", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "深植着", "label": "体标"}], "register": "书面", "sense_fingerprint": "植物的根扎得很深", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '635621f3-b4f7-4383-9d79-4d5e9f0eff6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25378, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "深植", "is_correct": true, "explanation": "深植 shēn zhí 是本词条，指根扎得很深，即本句的意思。"}, {"text": "深知", "is_correct": false, "explanation": "语音对比：深知 shēnzhī 与 深植 shēn zhí 只有第二音节声调不同（zhī 第一声，zhí 第二声），意思是深深地了解。"}, {"text": "神职", "is_correct": false, "explanation": "语音对比：神职 shénzhí 只有第一音节声调不同（shén 第二声，shēn 第一声），意思是神职人员的职务。"}, {"text": "生殖", "is_correct": false, "explanation": "语音对比：生殖 shēngzhí 只把第一音节的韵尾从 n 换成 ng（shēng 与 shēn），意思是生育繁殖。"}], "explanations": {"深植": "深植 shēn zhí 是本词条，指根扎得很深，即本句的意思。", "深知": "语音对比：深知 shēnzhī 与 深植 shēn zhí 只有第二音节声调不同（zhī 第一声，zhí 第二声），意思是深深地了解。", "神职": "语音对比：神职 shénzhí 只有第一音节声调不同（shén 第二声，shēn 第一声），意思是神职人员的职务。", "生殖": "语音对比：生殖 shēngzhí 只把第一音节的韵尾从 n 换成 ng（shēng 与 shēn），意思是生育繁殖。"}, "sentence_index": null, "correct_answer": "深植"}, "level_3": {"options": [{"text": "深植", "is_correct": true, "explanation": "正确：深植 指根牢牢扎入土中，与“这棵老树的根……在土里”相合。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”是人或动物迈步快走，根不能跑，与“根在土里”不合。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”接歌曲、戏曲，不能说“根唱在土里”。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”是腾空而起，与根扎入土中的意思相反。"}], "explanations": {"深植": "正确：深植 指根牢牢扎入土中，与“这棵老树的根……在土里”相合。", "跑": "语义：“跑”是人或动物迈步快走，根不能跑，与“根在土里”不合。", "唱": "搭配：“唱”接歌曲、戏曲，不能说“根唱在土里”。", "跳": "语义：“跳”是腾空而起，与根扎入土中的意思相反。"}, "sentence_index": 0, "correct_answer": "深植"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一伸手，把铁钉深植进了墙里。", "explanation": "这里应该用〈钉〉。深植 指植物的根扎得很深，不用于把铁钉敲进墙里，应说钉进。"}, {"text": "蚯蚓深植进了泥土里。", "explanation": "这里应该用〈钻〉。深植 讲植物的根扎得很深，不用于动物钻进土里。"}, {"text": "他把一箱金币深植在了地下。", "explanation": "这里应该用〈埋〉。深植 讲根扎得很深，不指人把东西埋进地下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25378, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "深植", "is_correct": true, "explanation": "深植 shēn zhí 是本词条，指根扎得很深，即本句的意思。"}, {"text": "神志", "is_correct": false, "explanation": "语音对比：神志 shénzhì 的两个音节声调都与 深植 不同（shén 第二声，zhì 第四声），意思是神智、意识。"}, {"text": "升职", "is_correct": false, "explanation": "语音对比：升职 shēngzhí 只把第一音节的韵尾从 n 换成 ng（shēng 与 shēn），意思是职位提升。"}, {"text": "深挚", "is_correct": false, "explanation": "语音对比：深挚 shēnzhì 只有第二音节声调不同（zhì 第四声，zhí 第二声），意思是感情深厚真挚。"}], "explanations": {"深植": "深植 shēn zhí 是本词条，指根扎得很深，即本句的意思。", "神志": "语音对比：神志 shénzhì 的两个音节声调都与 深植 不同（shén 第二声，zhì 第四声），意思是神智、意识。", "升职": "语音对比：升职 shēngzhí 只把第一音节的韵尾从 n 换成 ng（shēng 与 shēn），意思是职位提升。", "深挚": "语音对比：深挚 shēnzhì 只有第二音节声调不同（zhì 第四声，zhí 第二声），意思是感情深厚真挚。"}, "sentence_index": null, "correct_answer": "深植"}, "level_3": {"options": [{"text": "深植", "is_correct": true, "explanation": "正确：深植 指根牢牢扎入湿地，与“这种花的根……在湿地里”相合。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“笑”是人的表情和动作，根不会笑，与“根在湿地里”不合。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”是人或动物发出的声音和情绪，与根的状态不合。"}, {"text": "挥", "is_correct": false, "explanation": "搭配：“挥”一般接手臂、拳头、旗子，不接“根”。"}], "explanations": {"深植": "正确：深植 指根牢牢扎入湿地，与“这种花的根……在湿地里”相合。", "笑": "语义：“笑”是人的表情和动作，根不会笑，与“根在湿地里”不合。", "哭": "语义：“哭”是人或动物发出的声音和情绪，与根的状态不合。", "挥": "搭配：“挥”一般接手臂、拳头、旗子，不接“根”。"}, "sentence_index": 6, "correct_answer": "深植"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水库把清水深植进了农田里。", "explanation": "这里应该用〈注入〉。深植 只指植物的根扎得很深，不指液体流入田地。"}, {"text": "他在石碑上深植了一行名字。", "explanation": "这里应该用〈刻〉。深植 不指在石面上刻字。"}, {"text": "医生用针深植进了他的血管。", "explanation": "这里应该用〈扎〉。深植 不用于针刺入身体，应说扎进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这丛芦苇的根很深植在湿泥里。", "corrected_sentence": "这丛芦苇的根深植在湿泥里。", "error_description": "错误在于“深植”前加了“很”。“深植”是动词，不能受程度副词修饰；应说“根深植在湿泥里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这棵柳树的根已经深植了在河岸边。", "corrected_sentence": "这棵柳树的根已经深植在河岸边。", "error_description": "错误在于“深植”和“在”之间多加了“了”。“了”不能插在动词与处所之间，应说“根已经深植在河岸边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
