INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25380, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力打败或控制住对方。", "primary_collocate": null, "pronunciation": "zhēng fú", "ipa": "ʈʂɤŋ˥ fu˧˥", "syllable_count": 2, "sentences": [{"text": "他用力气征服了那匹野马。", "target_word": "征服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一番激烈的搏斗，他终于征服了那只老虎。", "target_word": "征服", "complexity_tier": "T3", "furigana": "jīng guò yì fān jī liè de bó dòu, tā zhōng yú zhēng fú le nà zhī lǎo hǔ.", "sentence_source": "generated"}, {"text": "摔跤时，他很快征服了对手。", "target_word": "征服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "驯兽员想征服这头发怒的狮子。", "target_word": "征服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个人一起才征服了那条大狗。", "target_word": "征服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把对手压在地上，征服了他。", "target_word": "征服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻的牛仔征服了烈性的公牛。", "target_word": "征服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猎人用了一整天，终于征服了那只凶猛的狼。", "target_word": "征服", "complexity_tier": "T3", "furigana": "liè rén yòng le yì zhěng tiān, zhōng yú zhēng fú le nà zhī xiōng měng de láng.", "sentence_source": "generated"}, {"text": "比赛里，小李用力量征服了高大的对手。", "target_word": "征服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那头熊发疯了，大家好久才征服它。", "target_word": "征服", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "征服了", "label": "体标"}, {"form": "征服过", "label": "体标"}, {"form": "征服者", "label": "复合"}], "register": "中性", "sense_fingerprint": "用力气打败或制住对手、动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '635621f3-b4f7-4383-9d79-4d5e9f0eff6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25380, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "征服", "is_correct": true, "explanation": "zhēng fú，意思是用力气打败或控制住对方、动物。"}, {"text": "政府", "is_correct": false, "explanation": "zhèng fǔ 两个音节都变了调，与 zhēng fú 声调不同，意思是政府。"}, {"text": "增幅", "is_correct": false, "explanation": "zēng 与 zhēng 声母不同（z 与 zh），意思是增加的幅度。"}, {"text": "正负", "is_correct": false, "explanation": "zhèng fù 两个音节都变了调，与 zhēng fú 声调不同，意思是正数与负数。"}], "explanations": {"征服": "zhēng fú，意思是用力气打败或控制住对方、动物。", "政府": "zhèng fǔ 两个音节都变了调，与 zhēng fú 声调不同，意思是政府。", "增幅": "zēng 与 zhēng 声母不同（z 与 zh），意思是增加的幅度。", "正负": "zhèng fù 两个音节都变了调，与 zhēng fú 声调不同，意思是正数与负数。"}, "sentence_index": null, "correct_answer": "征服"}, "level_3": {"options": [{"text": "征服", "is_correct": true, "explanation": "征服：用力气使野马屈服，与“用力气”相合。"}, {"text": "观赏", "is_correct": false, "explanation": "语义：“观赏”是看与欣赏，不需要用力气。"}, {"text": "画", "is_correct": false, "explanation": "语义：“画”是描绘，与“用力气”的动作不合。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的动作与“用力气”不相搭配。"}], "explanations": {"征服": "征服：用力气使野马屈服，与“用力气”相合。", "观赏": "语义：“观赏”是看与欣赏，不需要用力气。", "画": "语义：“画”是描绘，与“用力气”的动作不合。", "喂": "搭配：“喂”的动作与“用力气”不相搭配。"}, "sentence_index": 0, "correct_answer": "征服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们终于征服了那个新玩具。", "explanation": "这里应该用〈玩〉。征服针对要压服的对手或动物，玩具是用来玩的，不能说征服。"}, {"text": "他终于征服了绳子。", "explanation": "这里应该用〈解开〉。征服的对象是对手或动物，绳子是物体，要说解开。"}, {"text": "工人征服了一批货物。", "explanation": "这里应该用〈运送〉。征服针对有力量抗衡的对手，货物要用运送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25380, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "征服", "is_correct": true, "explanation": "zhēng fú，意思是用力气打败或控制住对方、动物。"}, {"text": "升幅", "is_correct": false, "explanation": "shēng 与 zhēng 声母不同（sh 与 zh），意思是上升的幅度。"}, {"text": "增幅", "is_correct": false, "explanation": "zēng 与 zhēng 声母不同（z 与 zh），声调相同，意思是增加的幅度。"}, {"text": "整幅", "is_correct": false, "explanation": "zhěng 与 zhēng 声调不同（第三声与第一声），意思是整块的布或画面。"}], "explanations": {"征服": "zhēng fú，意思是用力气打败或控制住对方、动物。", "升幅": "shēng 与 zhēng 声母不同（sh 与 zh），意思是上升的幅度。", "增幅": "zēng 与 zhēng 声母不同（z 与 zh），声调相同，意思是增加的幅度。", "整幅": "zhěng 与 zhēng 声调不同（第三声与第一声），意思是整块的布或画面。"}, "sentence_index": null, "correct_answer": "征服"}, "level_3": {"options": [{"text": "征服", "is_correct": true, "explanation": "征服：用力量制服烈性的公牛，与语境相合。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“祝贺”的对象是人，不能说祝贺公牛。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”多用于客人，不能用于公牛。"}, {"text": "谒见", "is_correct": false, "explanation": "语域：“谒见”是书面语，专用于拜见尊长，与口语语境不合。"}], "explanations": {"征服": "征服：用力量制服烈性的公牛，与语境相合。", "祝贺": "搭配：“祝贺”的对象是人，不能说祝贺公牛。", "欢迎": "搭配：“欢迎”多用于客人，不能用于公牛。", "谒见": "语域：“谒见”是书面语，专用于拜见尊长，与口语语境不合。"}, "sentence_index": 6, "correct_answer": "征服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他征服了那位客人的行李。", "explanation": "这里应该用〈搬运〉。征服针对要压服的对手或动物，行李要说搬运，不能说征服。"}, {"text": "大家征服了那扇铁门。", "explanation": "这里应该用〈打开〉。征服的对象须是对手或动物，铁门是物体，要说打开。"}, {"text": "他征服了那个网页。", "explanation": "这里应该用〈浏览〉。网页只能被浏览，不能用力气征服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25380, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把那只狼征服，大家都很佩服。", "corrected_sentence": "他把那只狼征服了，大家都很佩服。", "error_description": "“把”字句中“征服”后缺少“了”等补充成分，应说“把那只狼征服了”，不能只说“把那只狼征服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25380, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这头熊发疯了，大家终于征服着它。", "corrected_sentence": "这头熊发疯了，大家终于征服了它。", "error_description": "“终于”表示动作已经完成，应用完成标记“了”，不能用表示持续的“着”。应说“大家终于征服了它”，不能说“征服着它”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
