INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25382, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25382, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "“关乎”的意思是“和……有关系”。", "primary_collocate": null, "pronunciation": "guān hū", "ipa": "kuan˥ xu˥", "syllable_count": 2, "sentences": [{"text": "这件事关乎每个人的健康。", "target_word": "关乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃什么关乎身体好不好。", "target_word": "关乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试关乎你的未来。", "target_word": "关乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水的问题关乎整个城市的生活。", "target_word": "关乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的决定关乎几百个工人的工作。", "target_word": "关乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这不关乎钱，关乎我们的信任。", "target_word": "关乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气好坏关乎大家的生活。", "target_word": "关乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个比赛关乎学校的名誉。", "target_word": "关乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说这件事关乎国家的安全。", "target_word": "关乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡得好不好关乎孩子的成长。", "target_word": "关乎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "關乎", "label": "繁体"}], "register": "书面", "sense_fingerprint": "和某事有关系，多指重要的事（关乎健康、关乎未来）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e787e97-1e72-4215-97db-ad41e99b5a31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25382, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关心", "is_correct": false, "explanation": "搭配：“关心”的主语要是人，“这件事关心每个人的健康”说不通。"}, {"text": "关乎", "is_correct": true, "explanation": "关乎：指和某件事有重要的关系，“这件事关乎每个人的健康”与句意相符。"}, {"text": "属于", "is_correct": false, "explanation": "配价：“属于”后面要接所属的一方，“健康”不能被“这件事”属于，句子说不通。"}, {"text": "认识", "is_correct": false, "explanation": "语义：“认识”表示了解，事情不能去认识健康，句意不通。"}], "explanations": {"关心": "搭配：“关心”的主语要是人，“这件事关心每个人的健康”说不通。", "关乎": "关乎：指和某件事有重要的关系，“这件事关乎每个人的健康”与句意相符。", "属于": "配价：“属于”后面要接所属的一方，“健康”不能被“这件事”属于，句子说不通。", "认识": "语义：“认识”表示了解，事情不能去认识健康，句意不通。"}, "sentence_index": 0, "correct_answer": "关乎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书关乎中国历史。", "explanation": "这里应该用〈关于〉。“关乎”表示跟重要的事有关系，不能用来介绍内容范围。"}, {"text": "我很关乎你的健康。", "explanation": "这里应该用〈关心〉。“关乎”的主语是事情，不能用人作主语去关怀别人。"}, {"text": "他很关乎这个问题。", "explanation": "这里应该用〈关注〉。“关乎”指事情对人有重大影响，不用于人对问题的注意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "照顾", "is_correct": false, "explanation": "搭配：“照顾”的主语要是人，“空气好坏照顾大家的生活”说不通。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“结束”表示终止，空气好坏不能结束大家的生活，句意不通。"}, {"text": "相信", "is_correct": false, "explanation": "配价：“相信”要带能被相信的对象，“空气好坏相信大家的生活”说不通。"}, {"text": "关乎", "is_correct": true, "explanation": "关乎：指空气好坏与大家的生活有重大关系，与句意相符。"}], "explanations": {"照顾": "搭配：“照顾”的主语要是人，“空气好坏照顾大家的生活”说不通。", "结束": "语义：“结束”表示终止，空气好坏不能结束大家的生活，句意不通。", "相信": "配价：“相信”要带能被相信的对象，“空气好坏相信大家的生活”说不通。", "关乎": "关乎：指空气好坏与大家的生活有重大关系，与句意相符。"}, "sentence_index": 6, "correct_answer": "关乎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书关乎很多历史人物。", "explanation": "这里应该用〈讲述〉。“关乎”不用来引出人物，介绍内容要用“讲述”。"}, {"text": "妈妈每天关乎我的生活。", "explanation": "这里应该用〈照顾〉。“关乎”的主语要是事情，不能用人去照顾别人的生活。"}, {"text": "老师很关乎这次考试。", "explanation": "这里应该用〈重视〉。“关乎”表示事情与某事有重大关系，不用来表示人对事情的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事关乎于我们每个人的利益。", "corrected_sentence": "这件事关乎我们每个人的利益。", "error_description": "多加了“于”。“关乎”后直接接宾语，不说“关乎于”，应改为“关乎我们每个人的利益”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事被关乎我们的未来。", "corrected_sentence": "这件事关乎我们的未来。", "error_description": "错误：「被关乎」。「关乎」是表示事情与某事有关系的动词，不能构成「被」字被动句，应改为「这件事关乎我们的未来」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97ab7-65ac-4d87-805e-4dd3bbeb1e47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
