INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25384, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家最注意、最关心的人或事。", "primary_collocate": null, "pronunciation": "jiāo diǎn", "ipa": "tɕjɑʊ˥ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "他是今天晚会的焦点。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事成了大家谈话的焦点。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的焦点都在新玩具上。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新闻是今天报纸的焦点。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的新帽子成了朋友们的焦点。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的焦点是谁能得第一名。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的讨论焦点是旅行的时间。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一唱歌，就成为大家的焦点。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，今天的焦点是第三课。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢成为人群的焦点。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个焦点", "label": "量词"}, {"form": "焦點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大家最注意、最关心的人或事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312fe292-15c3-4f5b-baf9-ae90a590e823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25384, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "焦点", "is_correct": true, "explanation": "焦点：晚会上大家最注意的人，与句意相符。"}, {"text": "账单", "is_correct": false, "explanation": "语义：“账单”是付款凭证，不是人，“他是晚会的账单”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人，不能说“他是晚会的天气”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是电子设备，不是人，“他是晚会的手机”说不通。"}], "explanations": {"焦点": "焦点：晚会上大家最注意的人，与句意相符。", "账单": "语义：“账单”是付款凭证，不是人，“他是晚会的账单”说不通。", "天气": "语义：天气不是人，不能说“他是晚会的天气”。", "手机": "语义：手机是电子设备，不是人，“他是晚会的手机”说不通。"}, "sentence_index": 0, "correct_answer": "焦点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "外面下着焦点，地上白茫茫的一片。", "explanation": "这里应该用〈雪〉。雪会从天上下来，让地上白茫茫；「焦点」指大家最注意的地方，不会下。"}, {"text": "院子里有一个焦点，夏天很凉快。", "explanation": "这里应该用〈大树〉。大树能遮阴，所以夏天凉快；「焦点」不能遮阴。"}, {"text": "桌上有三个焦点，孩子们抢着吃。", "explanation": "这里应该用〈糖〉。糖可以吃，孩子们会抢；「焦点」是大家最注意的地方，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25384, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "焦点", "is_correct": true, "explanation": "焦点：大家最关注的部分，讨论的重点是旅行的时间。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不能作为讨论的对象，与“旅行的时间”无关。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”是人，不是讨论的内容，句子说的是讨论的话题。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“讨论”通常接话题、问题，不说“讨论座位”。"}], "explanations": {"焦点": "焦点：大家最关注的部分，讨论的重点是旅行的时间。", "冰箱": "语义：冰箱是家电，不能作为讨论的对象，与“旅行的时间”无关。", "老师": "语义：“老师”是人，不是讨论的内容，句子说的是讨论的话题。", "座位": "搭配：“讨论”通常接话题、问题，不说“讨论座位”。"}, "sentence_index": 6, "correct_answer": "焦点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的焦点很好，适合出去玩。", "explanation": "这里应该用〈天气〉。天气有好坏，适合出门；「焦点」指大家最注意的地方，没有好坏之分，不能说适合出去玩。"}, {"text": "这个焦点很大，住着一家人。", "explanation": "这里应该用〈房子〉。房子可以住人；「焦点」不能住人。"}, {"text": "屋里跑进来一个焦点，很可爱。", "explanation": "这里应该用〈小猫〉。小猫会跑进屋，还很可爱；「焦点」不会跑，也不能说可爱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位歌手的新专辑成了大家议论的一股焦点。", "corrected_sentence": "这位歌手的新专辑成了大家议论的一个焦点。", "error_description": "量词错：“焦点”应说“个”；“股”用于气体、液体等成股的东西，不能用来数“焦点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这幅画是今天展览会的一名焦点。", "corrected_sentence": "这幅画是今天展览会的一个焦点。", "error_description": "量词错：“焦点”应说“个”；“名”用于人，不能用来数“焦点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
