INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25386, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "看东西时用来比较的另一个东西。", "primary_collocate": null, "pronunciation": "cān zhào xì", "ipa": "tsʰan˥ ʈʂɑʊ˥˩ ɕi˥˩", "syllable_count": 3, "sentences": [{"text": "照片里放一支笔当参照系，就知道盒子多大。", "target_word": "参照系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有参照系，我们很难看出这棵树有多高。", "target_word": "参照系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手放在石头旁边，当作大小的参照系。", "target_word": "参照系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家在山脚画了一个人，作为山高的参照系。", "target_word": "参照系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看远处的灯时，近处的树是很好的参照系。", "target_word": "参照系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拍小猫的照片时，我放了一个硬币当参照系。", "target_word": "参照系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比较两种颜色时，先要有一个参照系。", "target_word": "参照系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子站在门口，门就成了他身高的参照系。", "target_word": "参照系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要找一个参照系，才能比较两个东西。", "target_word": "参照系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要看出兔子有多大，旁边要有一个参照系。", "target_word": "参照系", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "参考系", "label": "异形词"}], "register": "中性", "sense_fingerprint": "看东西时放在旁边、用来比较大小或高矮的另一个东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '635621f3-b4f7-4383-9d79-4d5e9f0eff6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25386, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参照系", "is_correct": true, "explanation": "正确：参照系 指看东西时用来比较的另一个东西，与“放一支笔当……，就知道盒子多大”相合。"}, {"text": "背景", "is_correct": false, "explanation": "语义：背景只起衬托作用，不能用来比较物体的大小。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是供玩耍的东西，不能用来判断盒子有多大。"}, {"text": "标题", "is_correct": false, "explanation": "搭配：“当”后接“标题”不合，一支笔不能当标题来比较大小。"}], "explanations": {"参照系": "正确：参照系 指看东西时用来比较的另一个东西，与“放一支笔当……，就知道盒子多大”相合。", "背景": "语义：背景只起衬托作用，不能用来比较物体的大小。", "玩具": "语义：玩具是供玩耍的东西，不能用来判断盒子有多大。", "标题": "搭配：“当”后接“标题”不合，一支笔不能当标题来比较大小。"}, "sentence_index": 0, "correct_answer": "参照系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用一首歌作参照系，比较两块石头的大小。", "explanation": "这里的“参照系”被用来指歌曲。本词条指看东西时用来比较的另一个东西，歌曲不是可以对照大小的实物，应选一个实物作比较。"}, {"text": "我用一只参照系来比较两块石头的大小。", "explanation": "这里应该用〈个〉。参照系 的量词是个，“只”多用于动物。"}, {"text": "我想看清这棵树有多高，就把它当作参照系。", "explanation": "这里的“参照系”被用成了被比较的对象本身。本词条指看东西时用来比较的另一个东西，树不能作自己的参照，应选另一个物体来对照。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参照系", "is_correct": true, "explanation": "正确：参照系 指用来比较的东西，与“比较两种颜色时，先要有一个……”相合。"}, {"text": "夜晚", "is_correct": false, "explanation": "语义：夜晚是时间，与比较两种颜色无关，不能作为比较的依据。"}, {"text": "谜语", "is_correct": false, "explanation": "语义：谜语是供人猜的题目，与比较颜色无关。"}, {"text": "诗句", "is_correct": false, "explanation": "语义：诗句是文学表达，不能用来比较颜色。"}], "explanations": {"参照系": "正确：参照系 指用来比较的东西，与“比较两种颜色时，先要有一个……”相合。", "夜晚": "语义：夜晚是时间，与比较两种颜色无关，不能作为比较的依据。", "谜语": "语义：谜语是供人猜的题目，与比较颜色无关。", "诗句": "语义：诗句是文学表达，不能用来比较颜色。"}, "sentence_index": 6, "correct_answer": "参照系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在桌上放了一把参照系，用来比较盒子的大小。", "explanation": "这里应该用〈个〉。“把”用于有柄或可握的器物，参照系 不用“把”计量。"}, {"text": "路口的参照系指示了去城里的方向。", "explanation": "这里应该用〈路标〉。参照系 是用来比较的东西，不是指示方向的标志。"}, {"text": "参照系显示屋里是二十度。", "explanation": "这里应该用〈温度计〉。参照系 是用来比较的东西，不是测量仪器，不能显示温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桌上放一块橡皮参照系，就知道笔有多长。", "corrected_sentence": "桌上放一块橡皮当参照系，就知道笔有多长。", "error_description": "错误在于缺少“当”。“放……当……”表示把某物当作另一物，应说“放一块橡皮当参照系”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "要看出树有多高，身边要有一只参照系。", "corrected_sentence": "要看出树有多高，身边要有一个参照系。", "error_description": "错误在于量词“只”。参照系 用“个”计量，“只”多用于动物。应说“一个参照系”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caa22b19-fa22-448e-994e-a1897295807d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
