INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25398, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25398, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "非常小的生物，要用显微镜才能看到，有的会让我们生病。", "primary_collocate": null, "pronunciation": "xì jūn", "ipa": "ɕi˥˩ tɕyn˥", "syllable_count": 2, "sentences": [{"text": "细菌很小，要用显微镜才能看到。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的细菌会让我们生病。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "脏衣服上有很多细菌。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾桶里有很多细菌，别用手碰。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生病的时候，医生会给我药，杀死身体里的细菌。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水不干净，里面可能有细菌。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道吗？空气里也有细菌。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机屏幕上也有很多细菌。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煮开的水里没有细菌，可以放心喝。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，吃东西以前先洗手，不然会带进细菌。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "细菌·很小的生物·让人生病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312fe292-15c3-4f5b-baf9-ae90a590e823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "细菌", "is_correct": true, "explanation": "细菌很小，要用显微镜才能看到，符合句意。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象体形庞大，与「很小」矛盾。"}, {"text": "大楼", "is_correct": false, "explanation": "体貌：「很小」描写的是大小，大楼体积庞大，与句意不符。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳肉眼就能看到，不需要用显微镜。"}], "explanations": {"细菌": "细菌很小，要用显微镜才能看到，符合句意。", "大象": "语义：大象体形庞大，与「很小」矛盾。", "大楼": "体貌：「很小」描写的是大小，大楼体积庞大，与句意不符。", "太阳": "语义：太阳肉眼就能看到，不需要用显微镜。"}, "sentence_index": 0, "correct_answer": "细菌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我看见饭桌上有一只细菌。", "explanation": "这里应该用〈个〉或〈种〉。量词〈只〉多用于动物，细菌不用〈只〉来数。"}, {"text": "手机中了木马，是因为里面有细菌。", "explanation": "这里应该用〈病毒〉。手机中毒是病毒造成的，细菌不用来说电子设备的故障。"}, {"text": "霉斑是细菌长出来的。", "explanation": "这里应该用〈真菌〉。霉斑是霉菌这类真菌长出的，不是细菌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "细菌", "is_correct": true, "explanation": "细菌在空气中也存在，符合句意。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼生活在水中，空气里不会有鱼。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会存在于空气中。"}, {"text": "皮鞋", "is_correct": false, "explanation": "搭配：「空气里也有」指看不见的微粒，皮鞋不能这样说。"}], "explanations": {"细菌": "细菌在空气中也存在，符合句意。", "鱼": "语义：鱼生活在水中，空气里不会有鱼。", "桌子": "语义：桌子是家具，不会存在于空气中。", "皮鞋": "搭配：「空气里也有」指看不见的微粒，皮鞋不能这样说。"}, "sentence_index": 6, "correct_answer": "细菌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑的细菌坏了，要送去修。", "explanation": "这里应该用〈硬盘〉。硬盘是电脑的部件，会坏、要修；细菌不是电脑的部件。"}, {"text": "人的身体是由很多细菌组成的。", "explanation": "这里应该用〈细胞〉。人体由细胞组成，细菌不是构成人体的单位。"}, {"text": "蛔虫是一种细菌。", "explanation": "这里应该用〈寄生虫〉。蛔虫属于动物，是寄生虫，不是细菌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块布上有一只细菌，它很小。", "corrected_sentence": "这块布上有一种细菌，它很小。", "error_description": "「细菌」的量词应用「种」或「个」，「只」多用于动物。「一只细菌」错误，应为「一种细菌」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "洗手可以把细菌洗。", "corrected_sentence": "洗手可以把细菌洗掉。", "error_description": "「把」字句中，动词后要有结果补语等成分，「把细菌洗」意思不完整，应为「把细菌洗掉」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25402, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合并", "is_correct": true, "explanation": "合并：把分开的部分合在一起，与「分成」的分开方向相反。"}, {"text": "建造", "is_correct": false, "explanation": "无关：「建造」指修建房屋等，与「分成」没有反义关系。"}, {"text": "阅读", "is_correct": false, "explanation": "无关：「阅读」指看书报，与「分成」没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：「唱歌」指发出歌声，与「分成」没有反义关系。"}], "correct_answer": "合并", "explanations": {"合并": "合并：把分开的部分合在一起，与「分成」的分开方向相反。", "建造": "无关：「建造」指修建房屋等，与「分成」没有反义关系。", "阅读": "无关：「阅读」指看书报，与「分成」没有反义关系。", "唱歌": "无关：「唱歌」指发出歌声，与「分成」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25402, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合并", "is_correct": true, "explanation": "合并：把分开的部分合在一起，与「分成」的分开方向相反。"}, {"text": "种植", "is_correct": false, "explanation": "无关：「种植」指把植物种在土里，与「分成」没有反义关系。"}, {"text": "检查", "is_correct": false, "explanation": "无关：「检查」指仔细查看，与「分成」没有反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：「打扫」指清除脏物，与「分成」没有反义关系。"}], "correct_answer": "合并", "explanations": {"合并": "合并：把分开的部分合在一起，与「分成」的分开方向相反。", "种植": "无关：「种植」指把植物种在土里，与「分成」没有反义关系。", "检查": "无关：「检查」指仔细查看，与「分成」没有反义关系。", "打扫": "无关：「打扫」指清除脏物，与「分成」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25402, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把整体切开或分开成几部分，让人看到里面不一样的部分。", "primary_collocate": null, "pronunciation": "fēn chéng", "ipa": "fən˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "把西瓜分成两半，就能看到红红的瓜肉。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把蛋糕分成两半，里面有三层不同的颜色。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把洋葱分成两半，让我们看里面的样子。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把梨分成两半，我们看到里面很白。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把苹果分成两半，你会看到里面的小星星。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把煮熟的鸡蛋分成两半，能看到白的和黄的。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这个面包分成两半，里面有不一样的馅。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把橘子分成两半，给我看里面的小块。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把花分成几部分，让我们看清花瓣和花心。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这块巧克力分成两半，里面有红色的果酱。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分成了", "label": "体标"}, {"form": "分成过", "label": "体标"}], "register": "中性", "sense_fingerprint": "分成·分开后露出里面不同的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312fe292-15c3-4f5b-baf9-ae90a590e823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25402, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分成", "is_correct": true, "explanation": "分成：把西瓜打开成两半，让瓜肉露出来，符合句意。"}, {"text": "包", "is_correct": false, "explanation": "语义：包是裹住，不会让瓜肉露出来，与句意矛盾。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：「擦」不能带「两半」这样的结果宾语。"}, {"text": "保存", "is_correct": false, "explanation": "语义：保存是留住完整，不会把西瓜切开让瓜肉露出来。"}], "explanations": {"分成": "分成：把西瓜打开成两半，让瓜肉露出来，符合句意。", "包": "语义：包是裹住，不会让瓜肉露出来，与句意矛盾。", "擦": "搭配：「擦」不能带「两半」这样的结果宾语。", "保存": "语义：保存是留住完整，不会把西瓜切开让瓜肉露出来。"}, "sentence_index": 0, "correct_answer": "分成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "把这封信分成了三只小猫，大家都很高兴。", "explanation": "这里不能用〈分成〉。〈分成〉的结果必须是原物的部分，“三只小猫”不是信的部分，搭配不通。"}, {"text": "我把弟弟分成两半，给妈妈看。", "explanation": "这里不能用〈分成〉。〈分成〉的对象只能是可以切开的物品，「弟弟」是人，人不能被切成两半给别人看，这是搭配错误。"}, {"text": "妈妈把蛋糕分成了我们。", "explanation": "这里应该用〈分给〉。「分成」的结果是部分，不能指向人，把东西给人要用〈分给〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分成", "is_correct": true, "explanation": "分成：把面包切成两半，露出里面的馅，符合句意。"}, {"text": "装", "is_correct": false, "explanation": "搭配：「装」的宾语是放进容器里的东西，不能说把面包装成两半。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：「挂」指悬挂，面包不能这样被分成两半。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：吃掉会把面包吃光，就看不到里面的馅了，与句意矛盾。"}], "explanations": {"分成": "分成：把面包切成两半，露出里面的馅，符合句意。", "装": "搭配：「装」的宾语是放进容器里的东西，不能说把面包装成两半。", "挂": "搭配：「挂」指悬挂，面包不能这样被分成两半。", "吃掉": "语义：吃掉会把面包吃光，就看不到里面的馅了，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "分成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两条小路分成了一条路。", "explanation": "这里应该用〈合并〉。合并是合成一条，分成是分开，二者意思相反。"}, {"text": "这些颜料分成了一种新颜色。", "explanation": "这里应该用〈合成〉。颜料混合后才得到新颜色，「分成」是把整体分开。"}, {"text": "他分成了我们的小组。", "explanation": "这里应该用〈加入〉。人是加入小组，而不是被分成小组。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "把橘子分成在两半，就能看到一瓣一瓣的果肉。", "corrected_sentence": "把橘子分成两半，就能看到一瓣一瓣的果肉。", "error_description": "搭配错：「分成」后直接接结果宾语「两半」，中间不能插入「在」，应为「把橘子分成两半」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个面包可以分成了两半，里面有馅。", "corrected_sentence": "这个面包可以分成两半，里面有馅。", "error_description": "「可以」表示可能，后面的动词不能再加「了」。「可以分成了两半」错误，应为「可以分成两半」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25404, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "很大", "is_correct": true, "explanation": "正确：“大”与“小”在体积上互为反义，“很小”的反义是“很大”。"}, {"text": "高兴", "is_correct": false, "explanation": "无反义关系：“高兴”形容心情，与东西的大小无关。"}, {"text": "整洁", "is_correct": false, "explanation": "无反义关系：“整洁”形容干净有序，与大小无关。"}, {"text": "轻松", "is_correct": false, "explanation": "无反义关系：“轻松”形容感受或状态，与大小无关。"}], "correct_answer": "很大", "explanations": {"很大": "正确：“大”与“小”在体积上互为反义，“很小”的反义是“很大”。", "高兴": "无反义关系：“高兴”形容心情，与东西的大小无关。", "整洁": "无反义关系：“整洁”形容干净有序，与大小无关。", "轻松": "无反义关系：“轻松”形容感受或状态，与大小无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25404, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大", "is_correct": true, "explanation": "正确：“大”与“小”在体积上互为反义，“裤子很小”的反义是“裤子很大”，这里取“大”。"}, {"text": "明亮", "is_correct": false, "explanation": "无反义关系：“明亮”形容光线或颜色，与大小无关。"}, {"text": "清楚", "is_correct": false, "explanation": "无反义关系：“清楚”形容明白或可见的程度，与大小无关。"}, {"text": "安全", "is_correct": false, "explanation": "无反义关系：“安全”形容状态，与大小无关。"}], "correct_answer": "大", "explanations": {"大": "正确：“大”与“小”在体积上互为反义，“裤子很小”的反义是“裤子很大”，这里取“大”。", "明亮": "无反义关系：“明亮”形容光线或颜色，与大小无关。", "清楚": "无反义关系：“清楚”形容明白或可见的程度，与大小无关。", "安全": "无反义关系：“安全”形容状态，与大小无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25404, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示东西的大小比平时少一点。", "primary_collocate": null, "pronunciation": "hěn xiǎo", "ipa": "xən˨˩ ɕjɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这件衣服很小，我穿不上。", "target_word": "很小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋很小，我的脚放不进去。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天买的苹果很小，只有拳头一半大。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子很小，装不下一瓶水。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子很小，放不下三个盘子。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的帽子很小，戴在头上很紧。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的西瓜长得很小，不太好卖。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块蛋糕很小，一口就吃完了。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子很小，我的书放不进去。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裤子很小，孩子穿着不舒服。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "东西的大小比平常偏小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '144bdcb8-b634-4814-93d5-bb47c40a03fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25404, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "很小", "is_correct": true, "explanation": "正确答案：很小（hěn xiǎo），表示东西的大小比平时少一点。"}, {"text": "很想", "is_correct": false, "explanation": "xiǎng 与 xiǎo 只差韵母（ang 与 ao），意思是“非常想念”。"}, {"text": "很响", "is_correct": false, "explanation": "xiǎng 与 xiǎo 只差韵母（ang 与 ao），意思是“声音大”。"}, {"text": "很险", "is_correct": false, "explanation": "xiǎn 与 xiǎo 只差韵母（an 与 ao），意思是“情况危险”。"}, {"text": "很好", "is_correct": false, "explanation": "声母不同：h 与 x，只差一个音位（hǎo 与 xiǎo），意思是“非常好”。"}], "explanations": {"很小": "正确答案：很小（hěn xiǎo），表示东西的大小比平时少一点。", "很想": "xiǎng 与 xiǎo 只差韵母（ang 与 ao），意思是“非常想念”。", "很响": "xiǎng 与 xiǎo 只差韵母（ang 与 ao），意思是“声音大”。", "很险": "xiǎn 与 xiǎo 只差韵母（an 与 ao），意思是“情况危险”。", "很好": "声母不同：h 与 x，只差一个音位（hǎo 与 xiǎo），意思是“非常好”。"}, "sentence_index": null, "correct_answer": "很小"}, "level_3": {"options": [{"text": "很小", "is_correct": true, "explanation": "正确：“很小”说衣服的大小比合适的少一点，与“我穿不上”相符。"}, {"text": "很香", "is_correct": false, "explanation": "语义：“香”说气味，衣服不能用来形容气味而与“穿不上”的原因相合。"}, {"text": "很快", "is_correct": false, "explanation": "语义：“快”描写速度，不能修饰衣服。"}, {"text": "很吵", "is_correct": false, "explanation": "搭配：“吵”形容声音，不用来说衣服。"}], "explanations": {"很小": "正确：“很小”说衣服的大小比合适的少一点，与“我穿不上”相符。", "很香": "语义：“香”说气味，衣服不能用来形容气味而与“穿不上”的原因相合。", "很快": "语义：“快”描写速度，不能修饰衣服。", "很吵": "搭配：“吵”形容声音，不用来说衣服。"}, "sentence_index": 0, "correct_answer": "很小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天很小，要多穿一件衣服。", "explanation": "〈很冷〉。说天气寒冷要用“很冷”，“很小”不用于描述天气。"}, {"text": "这次出差的时间很小，我三个月没回家。", "explanation": "〈很长〉。说时间的长短要用“很长”，“很小”不用于形容时间。"}, {"text": "这首歌很小，大家都爱唱。", "explanation": "〈好听〉。说歌曲动听要用“好听”，“很小”不用于形容歌曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25404, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很小", "is_correct": true, "explanation": "正确：“很小”说西瓜的个头比平时小，与“不太好卖”的结果相符。"}, {"text": "很冷", "is_correct": false, "explanation": "语义：“冷”描写温度，不能用来形容西瓜的长相。"}, {"text": "很热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面，不能修饰西瓜的长势。"}, {"text": "很清楚", "is_correct": false, "explanation": "搭配：“清楚”说明是否明白，不用来形容西瓜的长势。"}], "explanations": {"很小": "正确：“很小”说西瓜的个头比平时小，与“不太好卖”的结果相符。", "很冷": "语义：“冷”描写温度，不能用来形容西瓜的长相。", "很热闹": "搭配：“热闹”形容场面，不能修饰西瓜的长势。", "很清楚": "搭配：“清楚”说明是否明白，不用来形容西瓜的长势。"}, "sentence_index": 6, "correct_answer": "很小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的心情很小，我们去逛街吧。", "explanation": "〈很好〉。说心情好坏要用“很好”，“很小”不用于形容心情。"}, {"text": "这部电影很小，看了整整三个小时。", "explanation": "〈很长〉。说时间的长短要用“很长”，“很小”不用于形容电影的时长。"}, {"text": "这场比赛很小，大家都看入迷了。", "explanation": "〈精彩〉。说比赛好看要用“精彩”，“很小”不用于形容比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25404, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这双鞋很很小，我穿不下。", "corrected_sentence": "这双鞋很小，我穿不下。", "error_description": "错误：“很很小”。正确：“很小”。程度副词“很”不能重叠使用，应只用一个“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25404, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块饼干很小小的，一口就能吃完。", "corrected_sentence": "这块饼干很小，一口就能吃完。", "error_description": "错误：“很小小的”。正确：“很小”。“很”与重叠形式“小小的”不能同时用，应去掉“小的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
