INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25410, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "装东西的袋子，用塑料做的。", "primary_collocate": null, "pronunciation": "sù liào dài", "ipa": "su⁵¹ liau̯⁵¹ tai̯⁵¹", "syllable_count": 3, "sentences": [{"text": "我忘了带布袋，只好买一个塑料袋。", "target_word": "塑料袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料袋很轻，但是不太结实。", "target_word": "塑料袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用塑料袋装了一些苹果。", "target_word": "塑料袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把湿雨伞放进塑料袋里。", "target_word": "塑料袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾要先装进塑料袋，再扔掉。", "target_word": "塑料袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多商店不给塑料袋了。", "target_word": "塑料袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子别玩塑料袋，很危险。", "target_word": "塑料袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里漂着几个白色的塑料袋。", "target_word": "塑料袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从包里拿出一个塑料袋，把鞋子装进去。", "target_word": "塑料袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个塑料袋能装五公斤的东西吗？", "target_word": "塑料袋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个塑料袋", "label": "量词"}, {"form": "塑料袋子", "label": "复合"}], "register": "中性", "sense_fingerprint": "用塑料做的装东西的袋子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffaa23c-0615-48bd-8fdc-16ab6fa2cc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25410, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "塑料袋", "is_correct": true, "explanation": "正确。“只好买一个塑料袋”是自然的说法，塑料袋是可以买的物品。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不能被买，与“买一个”的搭配不合。"}, {"text": "石油", "is_correct": false, "explanation": "搭配：石油以“桶”或“吨”计，不说“一个石油”。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”指人，不能被买，句意不合。"}], "explanations": {"塑料袋": "正确。“只好买一个塑料袋”是自然的说法，塑料袋是可以买的物品。", "大海": "语义：大海不能被买，与“买一个”的搭配不合。", "石油": "搭配：石油以“桶”或“吨”计，不说“一个石油”。", "老师": "语义：“老师”指人，不能被买，句意不合。"}, "sentence_index": 0, "correct_answer": "塑料袋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一张塑料袋。", "explanation": "这里应该用〈个〉。“张”用于纸张等平面物，塑料袋要用“个”，应说“一个塑料袋”。"}, {"text": "他骑着塑料袋去上班。", "explanation": "这里应该用〈自行车〉。“他骑着自行车去上班”是自然的说法；骑的是自行车、摩托车等车辆，塑料袋不能骑。"}, {"text": "他用塑料袋在黑板上写字。", "explanation": "这里应该用〈粉笔〉。“他用粉笔在黑板上写字”是自然的说法；写字要用粉笔，塑料袋不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "塑料袋", "is_correct": true, "explanation": "正确。“小孩子别玩塑料袋，很危险”符合句意，塑料袋是可以拿来玩的物品。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：“玩”的对象应是玩具等可玩之物，“饭菜”是食物，句意不合。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“玩”不搭配抽象的“时间”，句意不合。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“玩”不搭配“作业”，应说“做作业”。"}], "explanations": {"塑料袋": "正确。“小孩子别玩塑料袋，很危险”符合句意，塑料袋是可以拿来玩的物品。", "饭菜": "语义：“玩”的对象应是玩具等可玩之物，“饭菜”是食物，句意不合。", "时间": "搭配：“玩”不搭配抽象的“时间”，句意不合。", "作业": "搭配：“玩”不搭配“作业”，应说“做作业”。"}, "sentence_index": 6, "correct_answer": "塑料袋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用塑料袋打电话。", "explanation": "这里应该用〈手机〉。“他用手机打电话”是自然的说法；打电话要用手机等通讯工具，塑料袋不能用来通话。"}, {"text": "他养了一个塑料袋当宠物。", "explanation": "这里应该用〈猫〉。“他养了一只猫当宠物”是自然的说法；宠物是有生命的动物，塑料袋不能当宠物。"}, {"text": "他用塑料袋吃饭。", "explanation": "这里应该用〈筷子〉。“他用筷子吃饭”是自然的说法；吃饭要用筷子或勺子，塑料袋不用来吃饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我用一台塑料袋装了菜。", "corrected_sentence": "我用一个塑料袋装了菜。", "error_description": "错误形式是量词“一台”，正确形式是“一个”。“台”用于机器等物品，塑料袋应用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从包里拿出一个了塑料袋。", "corrected_sentence": "他从包里拿出一个塑料袋。", "error_description": "多余的“了”插在数量短语“一个”与名词“塑料袋”之间，应删去，说“拿出一个塑料袋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
