INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25414, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地底下的一种黑黑的油，可以用来做汽油。", "primary_collocate": null, "pronunciation": "shí yóu", "ipa": "ʂɨ˧˥ joʊ˧˥", "syllable_count": 2, "sentences": [{"text": "地底下有黑黑的石油。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽油是用石油做的。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把石油从地下抽出来。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油很黑，像黑色的水。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有石油，汽车就不能跑。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，石油在很深的地下。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在沙漠里找到了石油。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油不能喝，喝了会生病。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海上的船运来很多石油。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书上看到石油是怎么来的。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一桶石油", "label": "量词"}, {"form": "石油气", "label": "复合"}], "register": "中性", "sense_fingerprint": "地底下黑黑的油，可做汽油", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffaa23c-0615-48bd-8fdc-16ab6fa2cc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25414, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "石油", "is_correct": true, "explanation": "石油是地底下的黑色油，可以用来做汽油，正是这个词。"}, {"text": "事由", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，事由指原因，不是石油。"}, {"text": "实有", "is_correct": false, "explanation": "yǒu（第三声）与 yóu（第二声）声调不同，实有指确实存在，不是石油。"}, {"text": "时有", "is_correct": false, "explanation": "yǒu（第三声）与 yóu（第二声）声调不同，时有指有时候会有，不是石油。"}], "explanations": {"石油": "石油是地底下的黑色油，可以用来做汽油，正是这个词。", "事由": "shì（第四声）与 shí（第二声）声调不同，事由指原因，不是石油。", "实有": "yǒu（第三声）与 yóu（第二声）声调不同，实有指确实存在，不是石油。", "时有": "yǒu（第三声）与 yóu（第二声）声调不同，时有指有时候会有，不是石油。"}, "sentence_index": null, "correct_answer": "石油"}, "level_3": {"options": [{"text": "石油", "is_correct": true, "explanation": "正确：石油是地底下的黑色油，符合句意。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳在天上，地底下不会有黑黑的太阳。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：牛奶通常是白色的，不说黑黑的牛奶。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛长在脸上，不会埋在地底下。"}], "explanations": {"石油": "正确：石油是地底下的黑色油，符合句意。", "太阳": "语义：太阳在天上，地底下不会有黑黑的太阳。", "牛奶": "搭配：牛奶通常是白色的，不说黑黑的牛奶。", "眼睛": "语义：眼睛长在脸上，不会埋在地底下。"}, "sentence_index": 0, "correct_answer": "石油"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只石油。", "explanation": "这里应该用〈桶〉。石油是大量的液体，计量用“桶”或“吨”，“只”用于动物或成对物品中的一个。"}, {"text": "汽车加的是石油。", "explanation": "这里应该用〈汽油〉。石油要先炼成汽油、柴油等才能给汽车加，不能直接加进汽车。"}, {"text": "我们家做饭用石油。", "explanation": "这里应该用〈天然气〉。石油是未经加工的原油，不能直接用来做饭，家里做饭通常用天然气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25414, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "石油", "is_correct": true, "explanation": "石油是地底下的黑色油，正是这个词。"}, {"text": "十余", "is_correct": false, "explanation": "yú与yóu韵母不同（u与ou），十余指十多，不是石油。"}, {"text": "试游", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，试游指试航，不是石油。"}, {"text": "诗友", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，诗友指写诗的朋友，不是石油。"}], "explanations": {"石油": "石油是地底下的黑色油，正是这个词。", "十余": "yú与yóu韵母不同（u与ou），十余指十多，不是石油。", "试游": "shì（第四声）与 shí（第二声）声调不同，试游指试航，不是石油。", "诗友": "shī（第一声）与 shí（第二声）声调不同，诗友指写诗的朋友，不是石油。"}, "sentence_index": null, "correct_answer": "石油"}, "level_3": {"options": [{"text": "石油", "is_correct": true, "explanation": "正确：沙漠里找到的可以是石油，符合句意。"}, {"text": "大海", "is_correct": false, "explanation": "语义：沙漠里不会有大海，与“沙漠”矛盾。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“找到”的对象应是可以被找到的东西，不说找到天空。"}, {"text": "雪山", "is_correct": false, "explanation": "语义：沙漠里不会有雪山，与“沙漠”矛盾。"}], "explanations": {"石油": "正确：沙漠里找到的可以是石油，符合句意。", "大海": "语义：沙漠里不会有大海，与“沙漠”矛盾。", "天空": "搭配：“找到”的对象应是可以被找到的东西，不说找到天空。", "雪山": "语义：沙漠里不会有雪山，与“沙漠”矛盾。"}, "sentence_index": 6, "correct_answer": "石油"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在桌子上放了一台石油。", "explanation": "这里应该用〈桶〉。“台”用于机器、仪器，石油是液体，计量要用“桶”或“吨”。"}, {"text": "医生用石油给伤口消毒。", "explanation": "这里应该用〈酒精〉。消毒要用酒精，石油不能用来消毒。"}, {"text": "我们用石油洗衣服。", "explanation": "这里应该用〈肥皂〉。洗衣服要用肥皂或洗衣粉；石油是黏稠的原油，不能用来洗衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个工厂每天要用两个石油。", "corrected_sentence": "这个工厂每天要用两吨石油。", "error_description": "“石油”是液体，计量要用“吨”或“桶”，不能用“个”。应说“两吨石油”，不说“两个石油”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂昨天运来了三条石油。", "corrected_sentence": "工厂昨天运来了三吨石油。", "error_description": "量词用错：“条”用于细长的东西，石油是液体，计量应说“吨”或“桶”，不说“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
