INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25416, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种气，人呼吸会吐出它。", "primary_collocate": null, "pronunciation": "èr yǎng huà tàn", "ipa": "aɚ˥˩ jɑŋ˨˩˦ xu̯a˥˩ tʰan˥˩", "syllable_count": 4, "sentences": [{"text": "人呼吸的时候会吐出二氧化碳。", "target_word": "二氧化碳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "树叶能吸进二氧化碳，放出氧气。", "target_word": "二氧化碳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽车会排出很多二氧化碳。", "target_word": "二氧化碳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间里人太多，二氧化碳会变多。", "target_word": "二氧化碳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽水里有二氧化碳，所以会冒泡。", "target_word": "二氧化碳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要少开车，少放二氧化碳。", "target_word": "二氧化碳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "二氧化碳没有颜色，我们看不见。", "target_word": "二氧化碳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植物需要二氧化碳才能长大。", "target_word": "二氧化碳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗户关着，屋里的二氧化碳会越来越多。", "target_word": "二氧化碳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，二氧化碳不是毒气。", "target_word": "二氧化碳", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人呼出、植物吸收的一种无色气体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e4ba268-bd9c-4b86-82cf-3221d314a81e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25416, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "二氧化碳", "is_correct": true, "explanation": "正确。人呼出的气体就是二氧化碳，符合句意。"}, {"text": "火焰", "is_correct": false, "explanation": "语义：人呼吸时不会吐出火焰，句意说不通。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：人不会吐出汽油，句子的意思说不通。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“吐出”的对象是气体或物质，汽车不能被吐出。"}], "explanations": {"二氧化碳": "正确。人呼出的气体就是二氧化碳，符合句意。", "火焰": "语义：人呼吸时不会吐出火焰，句意说不通。", "汽油": "语义：人不会吐出汽油，句子的意思说不通。", "汽车": "搭配：“吐出”的对象是气体或物质，汽车不能被吐出。"}, "sentence_index": 0, "correct_answer": "二氧化碳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们需要二氧化碳来呼吸。", "explanation": "这里误用了〈二氧化碳〉。人呼吸时要吸入的是〈氧气〉，呼出的才是二氧化碳，二者不能对调。"}, {"text": "我渴了，想喝一杯二氧化碳。", "explanation": "这里应该用〈汽水〉。二氧化碳是气体，不是饮料，不能用“喝”来说。"}, {"text": "这个屋子里的二氧化碳很新鲜。", "explanation": "这里应该用〈空气〉。“新鲜”形容可以呼吸的空气，二氧化碳不能用“新鲜”来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7ce5719-3d14-4759-bacc-f568fe5d44ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25416, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "二氧化碳", "is_correct": true, "explanation": "正确。二氧化碳是无色的，人看不见，符合句意。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：彩虹有明显的颜色，人能看见，与“没有颜色，我们看不见”矛盾。"}, {"text": "大山", "is_correct": false, "explanation": "语义：大山很大，有颜色，人能看见，句子说不通。"}, {"text": "红旗", "is_correct": false, "explanation": "搭配：“没有颜色”不能修饰红旗这类颜色鲜明的东西。"}], "explanations": {"二氧化碳": "正确。二氧化碳是无色的，人看不见，符合句意。", "彩虹": "语义：彩虹有明显的颜色，人能看见，与“没有颜色，我们看不见”矛盾。", "大山": "语义：大山很大，有颜色，人能看见，句子说不通。", "红旗": "搭配：“没有颜色”不能修饰红旗这类颜色鲜明的东西。"}, "sentence_index": 6, "correct_answer": "二氧化碳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们吃了很多二氧化碳。", "explanation": "这里应该用〈食物〉。二氧化碳是气体，不能吃。"}, {"text": "这幅画用了很多二氧化碳。", "explanation": "这里应该用〈颜料〉。二氧化碳是无色气体，不能用来画画。"}, {"text": "工人正在锯二氧化碳。", "explanation": "这里应该用〈木材〉。“锯”的对象是固体材料，二氧化碳是气体，不能锯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7ce5719-3d14-4759-bacc-f568fe5d44ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25416, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要减少这块二氧化碳的排放。", "corrected_sentence": "我们要减少这种二氧化碳的排放。", "error_description": "量词错误：“二氧化碳”是气体，指代时要用“种”，不能用“块”。“块”多用于有固定形状的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7ce5719-3d14-4759-bacc-f568fe5d44ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25416, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂每天都排出这块二氧化碳。", "corrected_sentence": "工厂每天都排出这种二氧化碳。", "error_description": "量词错误：“二氧化碳”是气体，指代时要用“种”，不能用“块”。“块”多用于有固定形状的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7ce5719-3d14-4759-bacc-f568fe5d44ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
