INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25422, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有很多水，不干", "primary_collocate": null, "pronunciation": "cháo shī", "ipa": "tʂʰau̯³⁵ ʂɻ̩⁵⁵", "syllable_count": 2, "sentences": [{"text": "这条毛巾还是潮湿的，不能用。", "target_word": "潮湿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗完的衣服还有点潮湿。", "target_word": "潮湿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这块地很潮湿，花长得很好。", "target_word": "潮湿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下了三天雨，路上的土都很潮湿。", "target_word": "潮湿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面包放在潮湿的地方会坏。", "target_word": "潮湿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服晾了一天，还是潮湿的。", "target_word": "潮湿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨停了，但是石头还很潮湿。", "target_word": "潮湿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "潮湿的木头很难烧起来。", "target_word": "潮湿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "被子太潮湿了，我们拿到外面晒晒。", "target_word": "潮湿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书放在潮湿的柜子里，会发霉。", "target_word": "潮湿", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "潮濕", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西沾了很多水，还没有干", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b2747cf-51da-4bed-8a3e-6845ab573b37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25422, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "潮湿", "is_correct": true, "explanation": "正确答案，指东西沾了很多水、还没有干。"}, {"text": "超市", "is_correct": false, "explanation": "chāo（第一声）与 cháo（第二声）声调不同；shì（第四声）与 shī（第一声）声调也不同，意思是超市。"}, {"text": "朝市", "is_correct": false, "explanation": "cháo 相同，shì（第四声）与 shī（第一声）声调不同，意思是早市。"}, {"text": "长诗", "is_correct": false, "explanation": "cháng 与 cháo 的韵母不同（ang 与 ao），shī 不变，意思是长诗。"}, {"text": "禅师", "is_correct": false, "explanation": "chán 与 cháo 的韵母不同（an 与 ao），shī 不变，意思是禅师。"}], "explanations": {"潮湿": "正确答案，指东西沾了很多水、还没有干。", "超市": "chāo（第一声）与 cháo（第二声）声调不同；shì（第四声）与 shī（第一声）声调也不同，意思是超市。", "朝市": "cháo 相同，shì（第四声）与 shī（第一声）声调不同，意思是早市。", "长诗": "cháng 与 cháo 的韵母不同（ang 与 ao），shī 不变，意思是长诗。", "禅师": "chán 与 cháo 的韵母不同（an 与 ao），shī 不变，意思是禅师。"}, "sentence_index": null, "correct_answer": "潮湿"}, "level_3": {"options": [{"text": "潮湿", "is_correct": true, "explanation": "正确：“潮湿”指毛巾含水未干，与“不能用”前后呼应。"}, {"text": "俊秀", "is_correct": false, "explanation": "体貌：“俊秀”形容人的容貌，不能用来形容毛巾。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容空间，不能修饰毛巾。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”的主体须是人，毛巾不会高兴。"}], "explanations": {"潮湿": "正确：“潮湿”指毛巾含水未干，与“不能用”前后呼应。", "俊秀": "体貌：“俊秀”形容人的容貌，不能用来形容毛巾。", "宽敞": "搭配：“宽敞”形容空间，不能修饰毛巾。", "高兴": "语义：“高兴”的主体须是人，毛巾不会高兴。"}, "sentence_index": 0, "correct_answer": "潮湿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个人的脾气很潮湿。", "explanation": "这里应该用〈温和〉。“温和”形容性情平和，“潮湿”只指物体含水多、不干，不能用来形容性情。"}, {"text": "这颗西瓜又大又潮湿。", "explanation": "这里应该用〈水灵〉。水灵形容水果饱满多汁，潮湿不用于形容水果。"}, {"text": "这首曲子的旋律很潮湿。", "explanation": "这里应该用〈悠扬〉。悠扬形容声音或旋律美妙悠长，潮湿不能形容旋律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25422, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "潮湿", "is_correct": true, "explanation": "正确答案，指东西沾了很多水、还没有干。"}, {"text": "超时", "is_correct": false, "explanation": "chāo（第一声）与 cháo（第二声）声调不同，shí（第二声）与 shī（第一声）声调也不同，意思是超时。"}, {"text": "朝食", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，意思是早饭。"}, {"text": "潮汐", "is_correct": false, "explanation": "xī 与 shī 的声母不同（x 与 sh），cháo 不变，意思是潮汐。"}, {"text": "朝市", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，意思是早市。"}], "explanations": {"潮湿": "正确答案，指东西沾了很多水、还没有干。", "超时": "chāo（第一声）与 cháo（第二声）声调不同，shí（第二声）与 shī（第一声）声调也不同，意思是超时。", "朝食": "shí（第二声）与 shī（第一声）声调不同，意思是早饭。", "潮汐": "xī 与 shī 的声母不同（x 与 sh），cháo 不变，意思是潮汐。", "朝市": "shì（第四声）与 shī（第一声）声调不同，意思是早市。"}, "sentence_index": null, "correct_answer": "潮湿"}, "level_3": {"options": [{"text": "潮湿", "is_correct": true, "explanation": "正确：“潮湿”描写石头沾水未干，与“雨停了，但是”的转折相符。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：石头一般坚硬，“柔软”与石头的性质矛盾。"}, {"text": "香甜", "is_correct": false, "explanation": "搭配：“香甜”形容味道，不能用来形容石头。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”只用于人或生物，不能描写石头。"}], "explanations": {"潮湿": "正确：“潮湿”描写石头沾水未干，与“雨停了，但是”的转折相符。", "柔软": "语义：石头一般坚硬，“柔软”与石头的性质矛盾。", "香甜": "搭配：“香甜”形容味道，不能用来形容石头。", "年轻": "语义：“年轻”只用于人或生物，不能描写石头。"}, "sentence_index": 6, "correct_answer": "潮湿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的主意很潮湿。", "explanation": "这里应该用〈新颖〉。“新颖”形容想法与众不同，“潮湿”只指物体含水多、不干，不能用来形容主意。"}, {"text": "老师的语气很潮湿。", "explanation": "这里应该用〈温和〉。温和形容语气平和，潮湿不能用来形容语气。"}, {"text": "这幅画的颜色很潮湿。", "explanation": "这里应该用〈鲜艳〉。鲜艳形容颜色明亮，潮湿不能用来形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨停以后，院子里的地还潮湿很。", "corrected_sentence": "雨停以后，院子里的地还潮湿得很。", "error_description": "错误：“潮湿很”。正确应为“潮湿得很”，形容词后作程度补语要用“得”连接，“潮湿很”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块抹布太的潮湿，拧干再用。", "corrected_sentence": "这块抹布太潮湿，拧干再用。", "error_description": "错误：“太的潮湿”。“潮湿”作谓语时不加“的”，应为“太潮湿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9f5352-89b3-42b0-bd8d-a9707f7bfa85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
