INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25426, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看不见了，或者没有见面。", "primary_collocate": null, "pronunciation": "bú jiàn", "ipa": "pu˧˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "好久不见，你最近怎么样？", "target_word": "不见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老朋友多年不见，一见面就聊个不停。", "target_word": "不见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个月不见，小明长高了不少。", "target_word": "不见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雾太大了，前面的车都不见了。", "target_word": "不见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等了半天，还不见他来。", "target_word": "不见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三年不见，你的汉语说得这么好！", "target_word": "不见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她去了国外，我们两年不见了。", "target_word": "不见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，远处的山都不见了。", "target_word": "不见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找了半天，也不见书包的影子。", "target_word": "不见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十年不见，老师还记得我的名字。", "target_word": "不见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不见了", "label": "体标"}], "register": "口语", "sense_fingerprint": "不见·很久没见面·看不到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312fe292-15c3-4f5b-baf9-ae90a590e823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25426, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不见", "is_correct": true, "explanation": "正确。“好久不见”是久别重逢时的问候，与“你最近怎么样”搭配。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：“失踪”指下落不明，与久别后的问候语境不符。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“好久吃饭”不成句，与问候语境不符。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“好久忘记”表示忘了，与问候“你最近怎么样”的语境相反。"}], "explanations": {"不见": "正确。“好久不见”是久别重逢时的问候，与“你最近怎么样”搭配。", "失踪": "语义：“失踪”指下落不明，与久别后的问候语境不符。", "吃饭": "搭配：“好久吃饭”不成句，与问候语境不符。", "忘记": "语义：“好久忘记”表示忘了，与问候“你最近怎么样”的语境相反。"}, "sentence_index": 0, "correct_answer": "不见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她说话很快，我不见她的声音。", "explanation": "这里应该用〈听见〉。“不见”指看不到或消失，不能指听不到；听声音要用〈听见〉。"}, {"text": "老朋友多年不见，一见面就不见了。", "explanation": "这里的“不见”指消失，不能用来说见面后的状态；见到人要说“见到”。"}, {"text": "我的朋友一见我就不见了。", "explanation": "“不见”指消失或没有见面，与“一见我”的意思矛盾，这里要说的是见到了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25426, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不见", "is_correct": true, "explanation": "正确。前句“她去了国外”，后句“两年不见了”表示分开两年没见面。"}, {"text": "陪伴", "is_correct": false, "explanation": "搭配：“陪伴”要求双方在一起，与“去了国外”的分离语境不符。"}, {"text": "来往", "is_correct": false, "explanation": "语义：“来往”指经常交往，与“去了国外”的分开语境相反。"}, {"text": "思念", "is_correct": false, "explanation": "语义：“思念”是心理活动，不能用来说明“两年”之后的见面状况。"}], "explanations": {"不见": "正确。前句“她去了国外”，后句“两年不见了”表示分开两年没见面。", "陪伴": "搭配：“陪伴”要求双方在一起，与“去了国外”的分离语境不符。", "来往": "语义：“来往”指经常交往，与“去了国外”的分开语境相反。", "思念": "语义：“思念”是心理活动，不能用来说明“两年”之后的见面状况。"}, "sentence_index": 6, "correct_answer": "不见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "十年过去，老师不见了我的名字。", "explanation": "这里应该用〈忘记〉。“不见”指看不到或消失，不能用来表示想不起名字。"}, {"text": "十年不见，老师还不见我的名字。", "explanation": "这里应该用〈记得〉。“不见”表示没见面或看不到，不能用来说记不记得名字。"}, {"text": "十年过去，那次聚会不见了。", "explanation": "这里应该用〈结束〉。“不见”指东西消失或看不到，聚会结束不能说“不见”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们三不见了，你还好吗？", "corrected_sentence": "我们三年不见了，你还好吗？", "error_description": "量词错：「三」后缺少时间单位「年」，应说「三年不见了」；「三不见了」不成词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们俩十年不见着，今天终于见面了。", "corrected_sentence": "他们俩十年不见了，今天终于见面了。", "error_description": "“不见”表示没见面的结果，后面不能接“着”。正确形式：十年不见了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
