INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25430, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西吃到肚子里。", "primary_collocate": null, "pronunciation": "chī diào", "ipa": "tʂʰɻ̩˥ tiɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈做的饺子，我全吃掉了。", "target_word": "吃掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快把这个苹果吃掉，不然会坏的。", "target_word": "吃掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把蛋糕都吃掉了，一点也没留。", "target_word": "吃掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把盘子里的菜吃掉，别浪费。", "target_word": "吃掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗吃掉了地上的骨头。", "target_word": "吃掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人吃掉了两碗面条。", "target_word": "吃掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经吃掉了午饭，不饿了。", "target_word": "吃掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们吃掉了桌上所有的水果。", "target_word": "吃掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把冰箱里的面包吃掉了。", "target_word": "吃掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小兔子吃掉了一根胡萝卜。", "target_word": "吃掉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吃掉了", "label": "体标"}, {"form": "吃不掉", "label": "否定可能补语"}, {"form": "吃得掉", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "把食物吃进肚子里，吃完", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1a78db7-dd1f-4ce9-a28b-f3b315ed5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25430, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吃掉", "is_correct": true, "explanation": "正确答案：吃掉（chī diào），指把食物吃到肚子里。"}, {"text": "失掉", "is_correct": false, "explanation": "shī（第一声）与 chī（第一声）声母不同（sh 与 ch），意思是丢失，不是吃进肚子里。"}, {"text": "拆掉", "is_correct": false, "explanation": "chāi 与 chī 同为第一声，仅韵母多一个 a，意思是拆除，不是吃进肚子里。"}, {"text": "吃到", "is_correct": false, "explanation": "dào 与 diào 只差介音 i，意思是吃到某物，不是吃完。"}], "explanations": {"吃掉": "正确答案：吃掉（chī diào），指把食物吃到肚子里。", "失掉": "shī（第一声）与 chī（第一声）声母不同（sh 与 ch），意思是丢失，不是吃进肚子里。", "拆掉": "chāi 与 chī 同为第一声，仅韵母多一个 a，意思是拆除，不是吃进肚子里。", "吃到": "dào 与 diào 只差介音 i，意思是吃到某物，不是吃完。"}, "sentence_index": null, "correct_answer": "吃掉"}, "level_3": {"options": [{"text": "吃掉", "is_correct": true, "explanation": "吃掉指把食物吃进肚子里，句中说饺子全部吃完了。"}, {"text": "写", "is_correct": false, "explanation": "语义：饺子不能被“写”，句子说不通。"}, {"text": "生气", "is_correct": false, "explanation": "配价：“生气”是不及物动词，不能带“饺子”做宾语。"}, {"text": "唱", "is_correct": false, "explanation": "语义：饺子不能被“唱”，句子说不通。"}], "explanations": {"吃掉": "吃掉指把食物吃进肚子里，句中说饺子全部吃完了。", "写": "语义：饺子不能被“写”，句子说不通。", "生气": "配价：“生气”是不及物动词，不能带“饺子”做宾语。", "唱": "语义：饺子不能被“唱”，句子说不通。"}, "sentence_index": 0, "correct_answer": "吃掉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把那杯果汁吃掉了。", "explanation": "这里应该用〈喝掉〉。果汁是用喝的，“吃掉”只用于固体食物。"}, {"text": "他把那辆自行车吃掉了。", "explanation": "这里应该用〈骑走〉。“吃掉”的对象只能是食物，自行车不能被吃掉。"}, {"text": "他把那张照片吃掉了，只好重新洗一张。", "explanation": "这里应该用〈撕掉〉。“吃掉”的对象只能是食物，照片不能被吃掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5c3db9f-034b-4ee2-a951-b031ba786b8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25430, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃掉", "is_correct": true, "explanation": "吃掉指把食物吃进肚子里，句中说午饭已经吃完了。"}, {"text": "相信", "is_correct": false, "explanation": "配价：“相信”要求对象是人或观点，不能以“午饭”为宾语。"}, {"text": "洗", "is_correct": false, "explanation": "语义：午饭不能“洗”，句子说不通。"}, {"text": "骂", "is_correct": false, "explanation": "语义：午饭不能“骂”，句子说不通。"}], "explanations": {"吃掉": "吃掉指把食物吃进肚子里，句中说午饭已经吃完了。", "相信": "配价：“相信”要求对象是人或观点，不能以“午饭”为宾语。", "洗": "语义：午饭不能“洗”，句子说不通。", "骂": "语义：午饭不能“骂”，句子说不通。"}, "sentence_index": 6, "correct_answer": "吃掉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小兔子把那只碗吃掉了。", "explanation": "这里应该用〈摔碎〉。“吃掉”只用于食物，碗不能被吃掉。"}, {"text": "小兔子把那张床吃掉了。", "explanation": "这里应该用〈搬走〉。“吃掉”的对象只能是食物，床不能被吃掉。"}, {"text": "小兔子吃掉了那个好消息。", "explanation": "这里应该用〈听到〉。“吃掉”的对象是食物，消息不能被吃掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5c3db9f-034b-4ee2-a951-b031ba786b8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹吃掉了把那个西瓜。", "corrected_sentence": "妹妹把那个西瓜吃掉了。", "error_description": "把字句语序错误：“把”字结构应位于动词之前，“吃掉了把那个西瓜”应改为“把那个西瓜吃掉了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5c3db9f-034b-4ee2-a951-b031ba786b8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "猫把那条鱼吃掉着。", "corrected_sentence": "猫把那条鱼吃掉了。", "error_description": "“吃掉”表示动作已完成，不能接“着”，应用“了”，“吃掉着”应改为“吃掉了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5c3db9f-034b-4ee2-a951-b031ba786b8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
