INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25436, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指某人或某事与情况相符，令人满意、觉得正好或适合。", "primary_collocate": null, "pronunciation": "hé shì", "ipa": "xɤ˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这双鞋我穿正合适。", "target_word": "合适", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你做老师真合适，学生都喜欢你。", "target_word": "合适", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这杯茶不冷不热，喝起来正合适。", "target_word": "合适", "complexity_tier": "T3", "furigana": "zhè bēi chá bù lěng bù rè, qǐ hē lái zhèng hé shì.", "sentence_source": "generated"}, {"text": "这个价钱我觉得很合适，就买吧。", "target_word": "合适", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们俩年纪差不多，在一起很合适。", "target_word": "合适", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "三点见面对你们两个都合适吗？", "target_word": "合适", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里离学校近，租给学生最合适。", "target_word": "合适", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他觉得这份工作的工资合适，就接受了。", "target_word": "合适", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "衣服太短，你穿不合适，换长的吧。", "target_word": "合适", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说这个年纪学钢琴正合适。", "target_word": "合适", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不合适", "label": "复合"}], "register": "中性", "sense_fingerprint": "与人或事的情况相符，觉得满意、正好或适合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc1124c-aaa0-4917-8d0b-f80cda82f842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25436, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合适", "is_correct": true, "explanation": "正确：“合适”与“正”搭配，表示穿着恰好、令人满意。"}, {"text": "贵", "is_correct": false, "explanation": "语义：“贵”说价钱高，与穿鞋的感受无关。"}, {"text": "热", "is_correct": false, "explanation": "搭配：“热”描述温度，不用来形容鞋穿着的感受。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”说温度低，与对鞋是否满意无关。"}], "explanations": {"合适": "正确：“合适”与“正”搭配，表示穿着恰好、令人满意。", "贵": "语义：“贵”说价钱高，与穿鞋的感受无关。", "热": "搭配：“热”描述温度，不用来形容鞋穿着的感受。", "冷": "语义：“冷”说温度低，与对鞋是否满意无关。"}, "sentence_index": 0, "correct_answer": "合适"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个礼物让我很合适。", "explanation": "这里应该用〈喜欢〉。合适表示正好、满意，不能用来表达对礼物的喜爱。"}, {"text": "他的看法让我很合适，我很同意。", "explanation": "这里应该用〈赞同〉。合适表示正好、满意，表示同意别人的看法要用赞同。"}, {"text": "这种闷热的天气让我很合适。", "explanation": "这里应该用〈讨厌〉。合适表示正好、满意，对事物感到厌恶要用讨厌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25436, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合适", "is_correct": true, "explanation": "正确：“最合适”表示租给学生正好，与“离学校近”的条件相合。"}, {"text": "偏僻", "is_correct": false, "explanation": "语义：“偏僻”指地方远离人群，与“离学校近”相矛盾。"}, {"text": "富有", "is_correct": false, "explanation": "搭配：“富有”形容人的财产或内容丰富，不用来形容房子的位置。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高”说高度，与租给学生是否合适无关。"}], "explanations": {"合适": "正确：“最合适”表示租给学生正好，与“离学校近”的条件相合。", "偏僻": "语义：“偏僻”指地方远离人群，与“离学校近”相矛盾。", "富有": "搭配：“富有”形容人的财产或内容丰富，不用来形容房子的位置。", "高": "语义：“高”说高度，与租给学生是否合适无关。"}, "sentence_index": 6, "correct_answer": "合适"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚到新学校，没几天就合适了。", "explanation": "这里应该用〈适应〉。合适指对某事觉得满意、正好，人对新环境逐渐习惯要用适应。"}, {"text": "这顿饭让我吃得很合适，连汤都喝光了。", "explanation": "这里应该用〈饱〉。合适说的是相称、令人满意，不用来形容吃的分量；“吃得很饱”才是正确说法。"}, {"text": "他面对困难时的勇气真合适。", "explanation": "这里应该用〈佩服〉。合适表示正好、满意，不能用来表示敬佩他人的品质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套衣服我穿很最合适，就买吧。", "corrected_sentence": "这套衣服我穿最合适，就买吧。", "error_description": "错误：“很最合适”，正确：“最合适”。“很”和“最”都是程度副词，不能叠用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套衣服我穿正在合适，就买下吧。", "corrected_sentence": "这套衣服我穿正合适，就买下吧。", "error_description": "错误：“正在合适”，正确：“正合适”。“正在”表示进行，不能修饰形容词“合适”，应去掉“在”，用“正合适”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25438, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "“不足”与“足够”构成反义，指数量或程度达不到需要。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容清晰，与“足够”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线或颜色，与“足够”没有反义关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "“陡峭”形容坡度，与“足够”没有反义关系。"}], "correct_answer": "不足", "explanations": {"不足": "“不足”与“足够”构成反义，指数量或程度达不到需要。", "清楚": "“清楚”形容清晰，与“足够”没有反义关系。", "明亮": "“明亮”形容光线或颜色，与“足够”没有反义关系。", "陡峭": "“陡峭”形容坡度，与“足够”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25438, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "“不足”与“足够”构成反义，指数量或程度达不到需要。"}, {"text": "幽默", "is_correct": false, "explanation": "“幽默”形容说话或性格，与“足够”没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”形容质地，与“足够”没有反义关系。"}, {"text": "繁忙", "is_correct": false, "explanation": "“繁忙”形容工作或生活状态，与“足够”没有反义关系。"}], "correct_answer": "不足", "explanations": {"不足": "“不足”与“足够”构成反义，指数量或程度达不到需要。", "幽默": "“幽默”形容说话或性格，与“足够”没有反义关系。", "柔软": "“柔软”形容质地，与“足够”没有反义关系。", "繁忙": "“繁忙”形容工作或生活状态，与“足够”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25438, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西的数量或程度已经达到让人满意的状态。", "primary_collocate": null, "pronunciation": "zú gòu", "ipa": "tsu˧˥ kou˥˩", "syllable_count": 2, "sentences": [{"text": "这些饭足够我们五个人吃。", "target_word": "足够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你带的钱足够买车票吗？", "target_word": "足够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们有足够的时间，不用着急。", "target_word": "足够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一杯水不够，两杯就足够了。", "target_word": "足够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的力气足够把这张桌子搬走。", "target_word": "足够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的作业不多，一个小时足够了。", "target_word": "足够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户很大，屋里的光线足够看书。", "target_word": "足够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有足够的信心完成比赛。", "target_word": "足够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里的菜足够吃一个星期。", "target_word": "足够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点蛋糕足够分给每个孩子。", "target_word": "足够", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "足夠", "label": "繁体"}, {"form": "足够了", "label": "体标"}], "register": "中性", "sense_fingerprint": "数量或程度已经满足需要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4246d07b-ae3c-4f25-9405-93e74c5a5c69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25438, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "足够", "is_correct": true, "explanation": "“足够”说明这些饭的量能满足五个人吃，句子通顺。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容空间，不用来说饭的量。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”说的是卫生，与饭够不够吃无关。"}, {"text": "安静", "is_correct": false, "explanation": "语义：饭不能“安静”，句子不成立。"}], "explanations": {"足够": "“足够”说明这些饭的量能满足五个人吃，句子通顺。", "宽敞": "搭配：“宽敞”形容空间，不用来说饭的量。", "干净": "语义：“干净”说的是卫生，与饭够不够吃无关。", "安静": "语义：饭不能“安静”，句子不成立。"}, "sentence_index": 0, "correct_answer": "足够"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要足够利用这段时间。", "explanation": "这里应该用〈充分〉。“足够”是形容词，不能修饰动词“利用”，要说“充分利用”。"}, {"text": "她的脾气很足够。", "explanation": "这里应该用〈温和〉。“足够”只表示数量或程度够用，不能形容脾气，要说“温和”。"}, {"text": "她穿的裙子很足够。", "explanation": "这里应该用〈漂亮〉。“足够”不用来评价外观，要说“漂亮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25438, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "足够", "is_correct": true, "explanation": "“足够”说明光线亮到能看书，与“窗户很大”相符。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：光线不能“热闹”，句子不成立。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容事物的体积，不用来形容光线。"}, {"text": "结实", "is_correct": false, "explanation": "语义：光线不能“结实”，句子不通。"}], "explanations": {"足够": "“足够”说明光线亮到能看书，与“窗户很大”相符。", "热闹": "语义：光线不能“热闹”，句子不成立。", "高大": "搭配：“高大”形容事物的体积，不用来形容光线。", "结实": "语义：光线不能“结实”，句子不通。"}, "sentence_index": 6, "correct_answer": "足够"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做事非常足够。", "explanation": "这里应该用〈周到〉。“足够”不用来评价做事态度，要说“周到”。"}, {"text": "这场比赛非常足够。", "explanation": "这里应该用〈精彩〉。“足够”不用来评价比赛质量，要说“精彩”。"}, {"text": "这个问题非常足够。", "explanation": "这里应该用〈严重〉。“足够”不用来形容问题，要说“严重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些钱足够的买一台电脑。", "corrected_sentence": "这些钱足够买一台电脑。", "error_description": "错误：“足够的买”。正确：“足够买”。“足够”后接动词时不加“的”，“足够的”只修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些蛋糕足够了分给全班同学。", "corrected_sentence": "这些蛋糕足够分给全班同学。", "error_description": "错误：“足够了分”。正确：“足够分”。“了”不放在“足够”和动词之间，只用于句末或动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
