INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25440, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "空气里有很多小小的水，摸起来潮潮的。", "primary_collocate": null, "pronunciation": "shī qì", "ipa": "ʂɻ̩˥ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "早上的山里有很多湿气，空气凉凉的。", "target_word": "湿气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗完澡，浴室里全是湿气。", "target_word": "湿气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "阴天的时候，湿气让被子摸起来潮潮的。", "target_word": "湿气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "木头地板怕湿气，容易坏。", "target_word": "湿气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们打开除湿机，把湿气吸走。", "target_word": "湿气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天湿气重，墙边的衣服总是干不了。", "target_word": "湿气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一进山洞，我就感到一股冷冷的湿气。", "target_word": "湿气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下过雨的草地上，湿气扑面而来。", "target_word": "湿气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣柜里湿气太大，衣服都有点潮。", "target_word": "湿气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳出来后，地上的湿气慢慢没有了。", "target_word": "湿气", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股湿气", "label": "量词"}, {"form": "濕氣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "空气里水分多，摸起来潮潮的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc1124c-aaa0-4917-8d0b-f80cda82f842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25440, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "湿气", "is_correct": true, "explanation": "正确答案。湿气指空气里有很多小小的水，摸起来潮潮的。"}, {"text": "失去", "is_correct": false, "explanation": "shī 相同，qì 与 qù 的韵母不同（i 与 ü），声调同为第四声，意思是失去。"}, {"text": "石器", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，意思是石头做的工具。"}, {"text": "时期", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，qī（第一声）与 qì（第四声）声调也不同，意思是一段时期。"}, {"text": "十七", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，qī（第一声）与 qì（第四声）声调也不同，意思是数字十七。"}], "explanations": {"湿气": "正确答案。湿气指空气里有很多小小的水，摸起来潮潮的。", "失去": "shī 相同，qì 与 qù 的韵母不同（i 与 ü），声调同为第四声，意思是失去。", "石器": "shí（第二声）与 shī（第一声）声调不同，意思是石头做的工具。", "时期": "shí（第二声）与 shī（第一声）声调不同，qī（第一声）与 qì（第四声）声调也不同，意思是一段时期。", "十七": "shí（第二声）与 shī（第一声）声调不同，qī（第一声）与 qì（第四声）声调也不同，意思是数字十七。"}, "sentence_index": null, "correct_answer": "湿气"}, "level_3": {"options": [{"text": "湿气", "is_correct": true, "explanation": "正确答案。“很多湿气”是山里早上的自然现象，与“空气凉凉的”相符。"}, {"text": "钱", "is_correct": false, "explanation": "语义：山里不会有很多钱，句子描写的不是自然环境，句意不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是山里的自然景物，句子的描写无法成立。"}, {"text": "皱纹", "is_correct": false, "explanation": "体貌：“皱纹”多用来描写人的脸或皮肤，不用于描写山里的环境。"}], "explanations": {"湿气": "正确答案。“很多湿气”是山里早上的自然现象，与“空气凉凉的”相符。", "钱": "语义：山里不会有很多钱，句子描写的不是自然环境，句意不通。", "冰箱": "语义：冰箱不是山里的自然景物，句子的描写无法成立。", "皱纹": "体貌：“皱纹”多用来描写人的脸或皮肤，不用于描写山里的环境。"}, "sentence_index": 0, "correct_answer": "湿气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "玻璃窗上挂满了湿气，看不清外面。", "explanation": "这里应该用〈水珠〉。水珠是能看见、会挂在玻璃上的小水滴，“湿气”看不见，不能说挂满。"}, {"text": "锅盖一掀开，冒出一阵湿气，烫得我直缩手。", "explanation": "这里应该用〈蒸汽〉。蒸汽是水受热后冒出的热气，会烫手；“湿气”是空气中弥散的水分，不是冒出的热气。"}, {"text": "衣柜里放着一只湿气，摸起来潮潮的。", "explanation": "这里应该用〈股〉。湿气作量词用“股”，“只”多用于动物或成对的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湿气", "is_correct": true, "explanation": "正确答案。走进山洞时感到一股冷冷的湿气，符合句意。"}, {"text": "热风", "is_correct": false, "explanation": "语义：“热风”是热的，与“冷冷的”自相矛盾，句意不通。"}, {"text": "脚步声", "is_correct": false, "explanation": "搭配：“脚步声”不用“一股”计量，“感到一股冷冷的脚步声”搭配不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是实物，不是可以被感到的冷气，句子的描写不成立。"}], "explanations": {"湿气": "正确答案。走进山洞时感到一股冷冷的湿气，符合句意。", "热风": "语义：“热风”是热的，与“冷冷的”自相矛盾，句意不通。", "脚步声": "搭配：“脚步声”不用“一股”计量，“感到一股冷冷的脚步声”搭配不通。", "钥匙": "语义：钥匙是实物，不是可以被感到的冷气，句子的描写不成立。"}, "sentence_index": 6, "correct_answer": "湿气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块面包里湿气很多，吃起来很软。", "explanation": "这里应该用〈水分〉。水分指食物或物体里所含的水，面包里的是水分；“湿气”指空气中的水，不能说面包里有湿气。"}, {"text": "床上铺着一张湿气，睡着很难受。", "explanation": "这里应该用〈股〉。“张”用于平面的东西，湿气应用“股”来计量。"}, {"text": "屋里放着一把湿气，人都闷得慌。", "explanation": "这里应该用〈股〉。“把”用于有柄或可握住的东西，湿气不能用“把”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "衣服上有一个湿气，摸起来潮潮的。", "corrected_sentence": "衣服上有一股湿气，摸起来潮潮的。", "error_description": "“湿气”的量词要用“股”，用“个”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋里的一个湿气已经少了。", "corrected_sentence": "屋里的一股湿气已经少了。", "error_description": "错误：“一个湿气”，正确：“一股湿气”。“湿气”的量词要用“股”，用“个”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25442, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远离", "is_correct": true, "explanation": "正确：“远离”与“靠近”构成反义，指距离变远。"}, {"text": "逗留", "is_correct": false, "explanation": "“逗留”指在某处停下来不走，与距离的远近变化无关，不构成反义。"}, {"text": "行进", "is_correct": false, "explanation": "“行进”指朝某个方向前进，与“靠近”同向，不构成反义。"}, {"text": "转弯", "is_correct": false, "explanation": "“转弯”指改变行进方向，并不直接表示距离变远，不构成反义。"}], "correct_answer": "远离", "explanations": {"远离": "正确：“远离”与“靠近”构成反义，指距离变远。", "逗留": "“逗留”指在某处停下来不走，与距离的远近变化无关，不构成反义。", "行进": "“行进”指朝某个方向前进，与“靠近”同向，不构成反义。", "转弯": "“转弯”指改变行进方向，并不直接表示距离变远，不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25442, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远离", "is_correct": true, "explanation": "正确：“远离”与“靠近”构成反义，指距离变远。"}, {"text": "静立", "is_correct": false, "explanation": "“静立”描述安静地站着，与距离的远近变化无关，不构成反义。"}, {"text": "飞舞", "is_correct": false, "explanation": "“飞舞”描述在空中回旋运动，与向某处挨近无直接对立，不构成反义。"}, {"text": "盘旋", "is_correct": false, "explanation": "“盘旋”指绕圈飞行，并不表示距离变远，不构成反义。"}], "correct_answer": "远离", "explanations": {"远离": "正确：“远离”与“靠近”构成反义，指距离变远。", "静立": "“静立”描述安静地站着，与距离的远近变化无关，不构成反义。", "飞舞": "“飞舞”描述在空中回旋运动，与向某处挨近无直接对立，不构成反义。", "盘旋": "“盘旋”指绕圈飞行，并不表示距离变远，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25442, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向一个地方移动，让距离变小。", "primary_collocate": null, "pronunciation": "kào jìn", "ipa": "kʰau̯˥˩ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "请大家往前走，不要靠近马路边。", "target_word": "靠近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师走进教室，靠近最后一排的学生。", "target_word": "靠近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "猫悄悄地靠近桌上的鱼，想偷吃。", "target_word": "靠近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车慢慢靠近站台，人们开始排队。", "target_word": "靠近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他怕狗，不敢靠近那只大黑狗。", "target_word": "靠近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "月亮慢慢靠近了山头，天快亮了。", "target_word": "靠近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小女孩靠近妈妈，轻轻地拉住她的手。", "target_word": "靠近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛快结束时，他靠近终点，加快了脚步。", "target_word": "靠近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请站远一点，别靠近正在烧水的炉子。", "target_word": "靠近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜜蜂闻到花香，很快就靠近了那朵花。", "target_word": "靠近", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "靠近了", "label": "体标"}, {"form": "靠近过", "label": "体标"}], "register": "中性", "sense_fingerprint": "向某处移动，让彼此的距离变小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc1124c-aaa0-4917-8d0b-f80cda82f842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25442, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "靠近", "is_correct": true, "explanation": "正确：“靠近”指向马路边挨近，符合“请大家往前走，不要……马路边”的语境。"}, {"text": "燃烧", "is_correct": false, "explanation": "搭配：“燃烧”的对象是物体或火，不能用于“马路边”这样的地点。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”指把东西保存起来，不能用于地点，句意不通。"}, {"text": "诞生", "is_correct": false, "explanation": "语义：“诞生”指新事物出现，不能与“马路边”这样的地点搭配。"}], "explanations": {"靠近": "正确：“靠近”指向马路边挨近，符合“请大家往前走，不要……马路边”的语境。", "燃烧": "搭配：“燃烧”的对象是物体或火，不能用于“马路边”这样的地点。", "收藏": "搭配：“收藏”指把东西保存起来，不能用于地点，句意不通。", "诞生": "语义：“诞生”指新事物出现，不能与“马路边”这样的地点搭配。"}, "sentence_index": 0, "correct_answer": "靠近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他和班里的同学很靠近，经常一起复习。", "explanation": "这里应该用〈亲近〉。靠近只表示空间距离缩短，人际关系亲密要用亲近。"}, {"text": "这两种茶的味道很靠近，很难分辨。", "explanation": "这里应该用〈相近〉。靠近指位置挨近，两种事物性质相似要用相近。"}, {"text": "今年的收入靠近去年的水平。", "explanation": "这里应该用〈接近〉。靠近指实际移动使距离变小，说收入、水平的接近要用接近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25442, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "靠近", "is_correct": true, "explanation": "正确：“靠近”表示挨近，与“轻轻地拉住她的手”的亲昵情境相合。"}, {"text": "推开", "is_correct": false, "explanation": "语义：“推开”表示用力使分离，与后文“轻轻地拉住她的手”冲突。"}, {"text": "迫近", "is_correct": false, "explanation": "语义：“迫近”带有逼近、威胁的意味，与“轻轻”的亲昵场景不符。"}, {"text": "躲开", "is_correct": false, "explanation": "语义：“躲开”是避开，与后文“轻轻地拉住她的手”的亲近情境相反。"}], "explanations": {"靠近": "正确：“靠近”表示挨近，与“轻轻地拉住她的手”的亲昵情境相合。", "推开": "语义：“推开”表示用力使分离，与后文“轻轻地拉住她的手”冲突。", "迫近": "语义：“迫近”带有逼近、威胁的意味，与“轻轻”的亲昵场景不符。", "躲开": "语义：“躲开”是避开，与后文“轻轻地拉住她的手”的亲近情境相反。"}, "sentence_index": 6, "correct_answer": "靠近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小孩子困了，靠近妈妈的肩膀睡着了。", "explanation": "这里应该用〈靠在〉。靠近只表示移到附近，身体倚着某处要用靠在。"}, {"text": "这个决定靠近了所有人的期望，大家都很满意。", "explanation": "这里应该用〈符合〉。靠近指实际移动使距离变小，说结果与期望相合要用符合。"}, {"text": "随着温度下降，气体的体积不断靠近零。", "explanation": "这里应该用〈趋近〉。靠近指实际的移动，数值或体积逐步逼近某个极限要用趋近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他慢慢靠近到门口，看清了里面的人。", "corrected_sentence": "他慢慢靠近门口，看清了里面的人。", "error_description": "错误：“靠近到门口”，正确：“靠近门口”。“靠近”后面直接接处所，不需要再加“到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一步步靠近在洞口，心里很紧张。", "corrected_sentence": "他一步步靠近洞口，心里很紧张。", "error_description": "错误：“靠近在洞口”，正确：“靠近洞口”。“靠近”后面直接接处所，不能加“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
