INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25444, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "成分就是一样东西里含有的东西。", "primary_collocate": null, "pronunciation": "chéng fèn", "ipa": "tʂʰɤŋ˧˥ fən˥˩", "syllable_count": 2, "sentences": [{"text": "巧克力里有哪些成分？", "target_word": "成分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道这杯果汁的成分。", "target_word": "成分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药的成分是什么？", "target_word": "成分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看了看饼干的成分，没有买。", "target_word": "成分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面膜里有很多有用的成分。", "target_word": "成分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶里有一种成分，喝多了会睡不着。", "target_word": "成分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个糖的成分比较简单，小孩也能吃。", "target_word": "成分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买东西时，总是先看成分。", "target_word": "成分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽水里的主要成分是水和糖。", "target_word": "成分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜的成分里有没有花生？", "target_word": "成分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "成分-一样东西里含有的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1a78db7-dd1f-4ce9-a28b-f3b315ed5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25444, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成分", "is_correct": true, "explanation": "成分指一样东西里含有的东西，问巧克力里有哪些，正是问它所含之物。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不是可以含在巧克力里的东西。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不指所含之物，“巧克力里有哪些年龄”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是人或动物的身体特征，巧克力里不会有体重。"}], "explanations": {"成分": "成分指一样东西里含有的东西，问巧克力里有哪些，正是问它所含之物。", "心情": "语义：心情不是可以含在巧克力里的东西。", "年龄": "语义：年龄不指所含之物，“巧克力里有哪些年龄”说不通。", "体重": "体貌：体重是人或动物的身体特征，巧克力里不会有体重。"}, "sentence_index": 0, "correct_answer": "成分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都吃成分。", "explanation": "这里应该用〈面包〉。“成分”指所含之物，不是可以吃的食物。"}, {"text": "这件衣服的成分很便宜，我就买了。", "explanation": "这里应该用〈价格〉。“便宜”说的是价钱，成分不能说便宜或贵。"}, {"text": "我们在操场上踢成分。", "explanation": "这里应该用〈足球〉。“成分”指所含之物，不能用来踢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5c3db9f-034b-4ee2-a951-b031ba786b8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25444, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成分", "is_correct": true, "explanation": "成分指所含之物，“这个糖的成分比较简单”符合语境。"}, {"text": "思想", "is_correct": false, "explanation": "语义：思想属于人，糖的思想说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气属于人或动物，糖没有脾气。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人或生物的外形特征，糖没有身高。"}], "explanations": {"成分": "成分指所含之物，“这个糖的成分比较简单”符合语境。", "思想": "语义：思想属于人，糖的思想说不通。", "脾气": "语义：脾气属于人或动物，糖没有脾气。", "身高": "体貌：身高是人或生物的外形特征，糖没有身高。"}, "sentence_index": 6, "correct_answer": "成分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在湖里钓成分。", "explanation": "这里应该用〈鱼〉。“成分”指所含之物，不能用来钓。"}, {"text": "这朵花的成分很鲜艳，很好看。", "explanation": "这里应该用〈颜色〉。成分指所含之物，“鲜艳”说的是颜色，不能用来形容成分。"}, {"text": "这根绳子的成分很长，不好收。", "explanation": "这里应该用〈长度〉。成分指所含之物，不能说长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5c3db9f-034b-4ee2-a951-b031ba786b8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25444, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种饮料有两只成分，你要看清楚。", "corrected_sentence": "这种饮料有两种成分，你要看清楚。", "error_description": "“成分”前的量词应为“种”，“两只成分”应改为“两种成分”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5c3db9f-034b-4ee2-a951-b031ba786b8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25444, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小明仔细看了这瓶酸奶的成分的。", "corrected_sentence": "小明仔细看了这瓶酸奶的成分。", "error_description": "多余成分：“成分”后面不能再加“的”，“成分的”多了一个“的”。把句末多出的“的”去掉，改为“这瓶酸奶的成分”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5c3db9f-034b-4ee2-a951-b031ba786b8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
