INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25448, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "警察晚上去街上工作。", "primary_collocate": null, "pronunciation": "chū gēng", "ipa": "t͡ʂʰu˥ kɤŋ˥", "syllable_count": 2, "sentences": [{"text": "香港警察今晚要出更。", "target_word": "出更", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他爸爸是警察，常常晚上出更。", "target_word": "出更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天夜里，小李出更了。", "target_word": "出更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察出更的时候，街上很安静。", "target_word": "出更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天晚上谁出更？", "target_word": "出更", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们两个警察一起出更，在街上走了很久。", "target_word": "出更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥是警察，每个星期出更三次。", "target_word": "出更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他出更回来，已经是早上六点了。", "target_word": "出更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨下得很大，警察还是要出更。", "target_word": "出更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下个月他换了班，不用晚上出更了。", "target_word": "出更", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出更了", "label": "体标"}], "register": "口语", "sense_fingerprint": "警察夜间外出执勤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc1124c-aaa0-4917-8d0b-f80cda82f842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25448, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出更", "is_correct": true, "explanation": "正确答案。“今晚要出更”指今晚外出执勤，符合警察的工作。"}, {"text": "出笼", "is_correct": false, "explanation": "语义：“出笼”指蒸好的食物从笼屉里端出，与警察的工作无关，句意不通。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指人刚降生，不能用于“今晚要……”这样的安排。"}, {"text": "出版", "is_correct": false, "explanation": "配价：“出版”的对象应是书报等出版物，不能说“警察今晚要出版”。"}], "explanations": {"出更": "正确答案。“今晚要出更”指今晚外出执勤，符合警察的工作。", "出笼": "语义：“出笼”指蒸好的食物从笼屉里端出，与警察的工作无关，句意不通。", "出生": "语义：“出生”指人刚降生，不能用于“今晚要……”这样的安排。", "出版": "配价：“出版”的对象应是书报等出版物，不能说“警察今晚要出版”。"}, "sentence_index": 0, "correct_answer": "出更"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这周在警局出更，负责接电话。", "explanation": "这里应该用〈值班〉。出更指夜里外出值勤，不在室内接电话；在室内值班才说“值班”。"}, {"text": "他下周要出更去北京开会。", "explanation": "这里应该用〈出差〉。出更指夜间外出执勤，不能用于出远门开会。"}, {"text": "警察白天在街上出更，很多人都看到了。", "explanation": "这里应该用〈巡逻〉。巡逻可以在白天进行，出更专指夜间执勤，不能用于白天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25448, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出更", "is_correct": true, "explanation": "正确答案。“每个星期出更三次”说的是有规律的值勤，符合警察的工作。"}, {"text": "降温", "is_correct": false, "explanation": "配价：“降温”的主语应是天气，不能用于“我哥哥”，句意不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”通常只发生一次，不能说每个星期进行。"}, {"text": "降雨", "is_correct": false, "explanation": "配价：“降雨”的主语应是天气，不能用于“我哥哥”。"}], "explanations": {"出更": "正确答案。“每个星期出更三次”说的是有规律的值勤，符合警察的工作。", "降温": "配价：“降温”的主语应是天气，不能用于“我哥哥”，句意不通。", "结婚": "语义：“结婚”通常只发生一次，不能说每个星期进行。", "降雨": "配价：“降雨”的主语应是天气，不能用于“我哥哥”。"}, "sentence_index": 6, "correct_answer": "出更"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上出更，九点才回家。", "explanation": "这里应该用〈上班〉。出更是夜里外出执勤，早上在单位工作应说“上班”，不说出更。"}, {"text": "为了写报告，他出更写到凌晨三点。", "explanation": "这里应该用〈熬夜〉。出更是因执勤而夜间外出，不用于写报告熬夜的情形。"}, {"text": "奶奶在床边出更，怕孩子醒来哭。", "explanation": "这里应该用〈守夜〉。守夜指在床边或家中守候，出更指外出值勤，不能用于床边守候。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25448, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨晚出着一次更，一直走到天亮。", "corrected_sentence": "我昨晚出了一次更，一直走到天亮。", "error_description": "错误：“出着一次更”，正确：“出了一次更”。“着”表示动作持续或状态，不能与表示计次且已完成的“一次”搭配，应使用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25448, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨晚街上出更，一直走到天亮。", "corrected_sentence": "他昨晚在街上出更，一直走到天亮。", "error_description": "错误：“街上出更”，正确：“在街上出更”。表示处所的名词作状语时，前面须加介词“在”，不能直接放在动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
