INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25450, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种黄色的、可以煮着吃的粮食，一粒一粒的。", "primary_collocate": null, "pronunciation": "yù mǐ", "ipa": "y⁵¹ mi²¹⁴", "syllable_count": 2, "sentences": [{"text": "我早饭吃了一根热玉米。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玉米是黄色的，一粒一粒很整齐。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子手里拿着一个煮好的玉米。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边有人在卖烤玉米。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱吃米饭，只爱啃玉米。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玉米煮二十分钟就可以吃了。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶从菜市场买回了两根玉米。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玉米很甜，孩子们都爱吃。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里，小女孩正在吃玉米。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把玉米放进锅里煮。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "玉米面", "label": "复合"}, {"form": "玉米粒", "label": "复合"}], "register": "中性", "sense_fingerprint": "黄色、一粒一粒、可以煮着吃的粮食", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '879a0741-3d13-4cd5-a933-7197b357419d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25450, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "玉米", "is_correct": true, "explanation": "正确：“一根”计量细长的玉米棒，“热”与“吃”都与食用相合。"}, {"text": "米饭", "is_correct": false, "explanation": "搭配：“根”用于细长条状的东西，米饭应该用“碗”或“份”计量。"}, {"text": "汤", "is_correct": false, "explanation": "搭配：汤是液体，不能用“根”计量，应说“一碗汤”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能吃，与句中“吃了”的动作相冲突。"}], "explanations": {"玉米": "正确：“一根”计量细长的玉米棒，“热”与“吃”都与食用相合。", "米饭": "搭配：“根”用于细长条状的东西，米饭应该用“碗”或“份”计量。", "汤": "搭配：汤是液体，不能用“根”计量，应说“一碗汤”。", "石头": "语义：石头不能吃，与句中“吃了”的动作相冲突。"}, "sentence_index": 0, "correct_answer": "玉米"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在玉米里玩捉迷藏。", "explanation": "这里应该用〈玉米地〉。此处的玉米指可以煮着吃的玉米，不是能让人走进去的场所；表示场所要说“玉米地”。"}, {"text": "我们用玉米拧开了瓶盖。", "explanation": "这里应该用〈开瓶器〉。玉米是可以煮着吃的食物，不能当作开瓶的工具。"}, {"text": "妈妈用玉米做了一件外套。", "explanation": "这里应该用〈布料〉。玉米是食物，不能作衣服的材料；做衣服要用布料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b59260c-a60d-44ae-96a6-595f6763726d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25450, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玉米", "is_correct": true, "explanation": "正确：菜市场买的是蔬菜粮食，“根”计量的正是玉米棒。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：菜市场不卖钢笔，与句中的购买场所相冲突。"}, {"text": "猪肉", "is_correct": false, "explanation": "搭配：“根”用于细长条状的东西，猪肉应说“块”或“斤”。"}, {"text": "书", "is_correct": false, "explanation": "语义：菜市场不卖书，与句中的购买场所相冲突。"}], "explanations": {"玉米": "正确：菜市场买的是蔬菜粮食，“根”计量的正是玉米棒。", "钢笔": "语义：菜市场不卖钢笔，与句中的购买场所相冲突。", "猪肉": "搭配：“根”用于细长条状的东西，猪肉应说“块”或“斤”。", "书": "语义：菜市场不卖书，与句中的购买场所相冲突。"}, "sentence_index": 6, "correct_answer": "玉米"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们骑着玉米去郊游。", "explanation": "这里应该用〈自行车〉。玉米不是交通工具，骑车要用自行车。"}, {"text": "他每天看玉米就知道几点了。", "explanation": "这里应该用〈钟表〉。玉米不能用来计时，看时间要用钟表。"}, {"text": "这盘玉米每天都在教室里唱歌。", "explanation": "这里不能把〈玉米〉当作主语。玉米是植物，不会唱歌；唱歌的主语应是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b59260c-a60d-44ae-96a6-595f6763726d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我晚饭吃了一只烤玉米。", "corrected_sentence": "我晚饭吃了一根烤玉米。", "error_description": "量词误用：玉米应用“根”计量；“只”多用于动物或成对之物中的一个，不能计量玉米。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b59260c-a60d-44ae-96a6-595f6763726d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我吃过玉米煮。", "corrected_sentence": "我吃过煮玉米。", "error_description": "语序颠倒：“煮”与“玉米”的动宾结构应为“煮玉米”，正确说法是“吃过煮玉米”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b59260c-a60d-44ae-96a6-595f6763726d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
