INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25452, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "长链就是很长的链子。", "primary_collocate": null, "pronunciation": "cháng liàn", "ipa": "ʈʂʰɑŋ˧˥ ljɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他买了一条长链来锁自行车。", "target_word": "长链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条长链有十米长，可以拉很远。", "target_word": "长链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗被一条长链拴在院子里。", "target_word": "长链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把长链绕在手上，绕了三圈。", "target_word": "长链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长链太重了，孩子拿不起来。", "target_word": "长链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条长链比那条长多了。", "target_word": "长链", "complexity_tier": "T3", "furigana": "cháng liàn", "sentence_source": "generated"}, {"text": "仓库里有好几条长链，都是新的。", "target_word": "长链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条长链不是铁的，是用塑料做的。", "target_word": "长链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把那条长链从墙上拿下来。", "target_word": "长链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在店里选了一条最长的长链。", "target_word": "长链", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条长链", "label": "量词"}, {"form": "長鏈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很长的链子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7d32c5-7ea6-49ff-a5b8-7910f90aa5ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25452, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长链", "is_correct": true, "explanation": "正确：“长链”是可以用来锁车的长链子，与“锁自行车”搭配。"}, {"text": "项链", "is_correct": false, "explanation": "语义：“项链”是饰品，不能用来锁自行车。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：“围巾”是衣物，不能用来锁自行车。"}, {"text": "长裤", "is_correct": false, "explanation": "搭配：“锁自行车”需要链子这类工具，“长裤”不搭配这种用途。"}], "explanations": {"长链": "正确：“长链”是可以用来锁车的长链子，与“锁自行车”搭配。", "项链": "语义：“项链”是饰品，不能用来锁自行车。", "围巾": "语义：“围巾”是衣物，不能用来锁自行车。", "长裤": "搭配：“锁自行车”需要链子这类工具，“长裤”不搭配这种用途。"}, "sentence_index": 0, "correct_answer": "长链"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把长链当手套戴在手上，戴得很暖和。", "explanation": "这里应该用〈手套〉。手套可以戴在手上保暖；长链是链子，不能当作手套。"}, {"text": "我把水装进长链里。", "explanation": "这里应该用〈水桶〉。水桶可以装水；长链是链子，不能用来装东西。"}, {"text": "长链在教室里认真地学习。", "explanation": "这里应该用〈学生〉。学生能在教室里学习；长链是链子，不能做“学习”这样的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28eee4b8-5aea-4484-a73e-9196fa0b69e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25452, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长链", "is_correct": true, "explanation": "正确：“长链”是链子，与“仓库里有好几条……，都是新的”的语境相符。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不会存放在仓库里，与“都是新的”的语境不合。"}, {"text": "小路", "is_correct": false, "explanation": "语义：小路不能存放在仓库里，与语境矛盾。"}, {"text": "公路", "is_correct": false, "explanation": "搭配：“仓库里有”不能搭配“公路”这类大型设施，搭配不合。"}], "explanations": {"长链": "正确：“长链”是链子，与“仓库里有好几条……，都是新的”的语境相符。", "河流": "语义：河流不会存放在仓库里，与“都是新的”的语境不合。", "小路": "语义：小路不能存放在仓库里，与语境矛盾。", "公路": "搭配：“仓库里有”不能搭配“公路”这类大型设施，搭配不合。"}, "sentence_index": 6, "correct_answer": "长链"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的长链很高，站在人群中很显眼。", "explanation": "这里应该用〈身高〉。人的身高可以说“高”；长链是链子，说“很高”不合常理，应说“很长”。"}, {"text": "他的长链很好听。", "explanation": "这里应该用〈声音〉。声音可以“好听”；长链是链子，不能用“好听”形容。"}, {"text": "他用长链擦干了汗。", "explanation": "这里应该用〈毛巾〉。毛巾可以擦汗；长链是链子，不能用来擦东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28eee4b8-5aea-4484-a73e-9196fa0b69e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根很长链可以拉很远。", "corrected_sentence": "这根长链可以拉很远。", "error_description": "“很”是程度副词，不能直接修饰“长链”这样的名词性词语，原句“很长链”不成立；去掉“很”，说“这根长链”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28eee4b8-5aea-4484-a73e-9196fa0b69e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店里摆着几根长链们，都是新的。", "corrected_sentence": "店里摆着几根长链，都是新的。", "error_description": "错误用法：“们”不能用于链子这类无生命的物体，应直接说“几根长链”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28eee4b8-5aea-4484-a73e-9196fa0b69e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
