INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25456, 1, 'prompt1_core', '{"pos": "结果补语", "semantic_class": "function", "definition": "事情做完了。", "primary_collocate": null, "pronunciation": "wán", "ipa": "wan˧˥", "syllable_count": 1, "sentences": [{"text": "作业我已经写完了。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作做完了，你可以回家。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把作业做完了。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我昨天看完了。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭做完了，快来吃吧。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把房间打扫完了。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告写完了吗？", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服洗完了，我去晾。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情做完了，我们休息一下。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的信我读完了。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "完了", "label": "体标"}, {"form": "完成", "label": "复合"}, {"form": "完美", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词后补语，表示事情做完、完成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea494939-a4c9-431c-bc0d-cd219d6a4140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25456, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "完", "is_correct": true, "explanation": "完（wán，第二声）：事情做完了，表示完成。"}, {"text": "万", "is_correct": false, "explanation": "wàn（第四声）与 wán（第二声）声调不同，意思是“一万”。"}, {"text": "晚", "is_correct": false, "explanation": "wǎn（第三声）与 wán（第二声）声调不同，意思是“晚上”。"}, {"text": "王", "is_correct": false, "explanation": "wáng 与 wán 韵母不同（-ng 与 -n），意思是“国王”。"}, {"text": "弯", "is_correct": false, "explanation": "wān（第一声）与 wán（第二声）声调不同，意思是“弯曲”。"}], "explanations": {"完": "完（wán，第二声）：事情做完了，表示完成。", "万": "wàn（第四声）与 wán（第二声）声调不同，意思是“一万”。", "晚": "wǎn（第三声）与 wán（第二声）声调不同，意思是“晚上”。", "王": "wáng 与 wán 韵母不同（-ng 与 -n），意思是“国王”。", "弯": "wān（第一声）与 wán（第二声）声调不同，意思是“弯曲”。"}, "sentence_index": null, "correct_answer": "完"}, "level_3": {"options": [{"text": "完", "is_correct": true, "explanation": "“写完”表示作业写到结束，与“已经”相合。"}, {"text": "成", "is_correct": false, "explanation": "配价：“写成”后要带结果宾语，如“写成文章”，不能只说“作业写成了”。"}, {"text": "光", "is_correct": false, "explanation": "语义：“写光”指把纸或墨用尽，“作业”不是可以用光的东西。"}, {"text": "到", "is_correct": false, "explanation": "配价：“写到”后要说明写到哪里，如“写到第三页”，单独说“写到了”不完整。"}], "explanations": {"完": "“写完”表示作业写到结束，与“已经”相合。", "成": "配价：“写成”后要带结果宾语，如“写成文章”，不能只说“作业写成了”。", "光": "语义：“写光”指把纸或墨用尽，“作业”不是可以用光的东西。", "到": "配价：“写到”后要说明写到哪里，如“写到第三页”，单独说“写到了”不完整。"}, "sentence_index": 0, "correct_answer": "完"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这顿饭还没做，妈妈已经做完了。", "explanation": "这里不能用“完”。“完”表示事情已经做完，“还没做”与“做完了”前后矛盾，应改说“还没做好”。"}, {"text": "这本书我还没开始看，就已经看完了。", "explanation": "这里不能用“完”。“看完”指已经看到最后，“还没开始看”与“看完了”前后矛盾。"}, {"text": "这场会议还没开始，就已经完了。", "explanation": "这里不能用“完”。“完”表示事情已经结束，会议还没开始时只能说“还没开始”，不能说“完了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25456, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "完", "is_correct": true, "explanation": "完（wán，第二声）：事情做完了，表示完成。"}, {"text": "碗", "is_correct": false, "explanation": "wǎn（第三声）与 wán（第二声）声调不同，意思是“碗”。"}, {"text": "文", "is_correct": false, "explanation": "wén 与 wán 韵母不同（-en 与 -an），意思是“文字”。"}, {"text": "腕", "is_correct": false, "explanation": "wàn（第四声）与 wán（第二声）声调不同，意思是“手腕”。"}], "explanations": {"完": "完（wán，第二声）：事情做完了，表示完成。", "碗": "wǎn（第三声）与 wán（第二声）声调不同，意思是“碗”。", "文": "wén 与 wán 韵母不同（-en 与 -an），意思是“文字”。", "腕": "wàn（第四声）与 wán（第二声）声调不同，意思是“手腕”。"}, "sentence_index": null, "correct_answer": "完"}, "level_3": {"options": [{"text": "完", "is_correct": true, "explanation": "“写完”表示报告写到结束，与“吗”的提问相合。"}, {"text": "掉", "is_correct": false, "explanation": "语义：“写掉”指把已写的内容去掉，与“报告写完了”的意思不合。"}, {"text": "上", "is_correct": false, "explanation": "配价：“写上”需要说明写上什么，如“写上名字”，句中没有这样的宾语。"}, {"text": "破", "is_correct": false, "explanation": "语义：“写破”指把纸或笔写坏，“报告”的完成与“写破”的意思不合。"}], "explanations": {"完": "“写完”表示报告写到结束，与“吗”的提问相合。", "掉": "语义：“写掉”指把已写的内容去掉，与“报告写完了”的意思不合。", "上": "配价：“写上”需要说明写上什么，如“写上名字”，句中没有这样的宾语。", "破": "语义：“写破”指把纸或笔写坏，“报告”的完成与“写破”的意思不合。"}, "sentence_index": 6, "correct_answer": "完"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨终于完了。", "explanation": "这里应该用〈停〉。“完”指事情做完，雨、风停止要说“停”。"}, {"text": "这学期的课还没上，他已经上完了。", "explanation": "这里不能用“完”。“上完”指课程已经讲完，“还没上”与“上完了”前后矛盾。"}, {"text": "电影还没开始，我们就看完了。", "explanation": "这里不能用“完”。“看完”指已经看到结尾，电影还没开始时不能说“看完了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25456, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我吃饭完就出门。", "corrected_sentence": "我吃完饭就出门。", "error_description": "“完”作结果补语要紧跟动词，应说“吃完饭”；说“吃饭完”把补语放在了宾语之后，是错误的位置。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25456, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把作业写了完了。", "corrected_sentence": "他把作业写完了。", "error_description": "“完”是结果补语，要紧跟动词组成“写完”，中间不能插入“了”。应说“写完了”，不能说“写了完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
