INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25458, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西很牢固，不容易坏。", "primary_collocate": null, "pronunciation": "jiē shi", "ipa": "t͡ɕjɛ˥ ʂɨ", "syllable_count": 2, "sentences": [{"text": "这张床很结实，两个人坐也不会坏。", "target_word": "结实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件雨衣太薄了，不太结实。", "target_word": "结实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条裤子很结实，穿了很多年。", "target_word": "结实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把木板钉得很结实。", "target_word": "结实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明的新自行车又轻又结实。", "target_word": "结实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个杯子不结实，一掉在地上就碎了。", "target_word": "结实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一个结实的盒子装工具。", "target_word": "结实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路修得很结实，大车也能走。", "target_word": "结实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这扇门很结实，风吹不开。", "target_word": "结实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老房子的柱子很结实，一百年都没坏。", "target_word": "结实", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "结结实实", "label": "重叠"}], "register": "中性", "sense_fingerprint": "东西牢固不容易坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc1124c-aaa0-4917-8d0b-f80cda82f842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25458, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "结实", "is_correct": true, "explanation": "结实 jiēshi：东西很牢固，不容易坏。"}, {"text": "结识", "is_correct": false, "explanation": "结识 jiēshí 与 结实 jiēshi 的第二个音节声调不同，意思是认识、交朋友。"}, {"text": "节食", "is_correct": false, "explanation": "节食 jiéshí 与 结实 jiēshi 两个音节的声调都不同，意思是控制饮食。"}, {"text": "结石", "is_correct": false, "explanation": "结石 jiéshí 与 结实 jiēshi 声调不同，意思是身体里形成的硬块。"}], "explanations": {"结实": "结实 jiēshi：东西很牢固，不容易坏。", "结识": "结识 jiēshí 与 结实 jiēshi 的第二个音节声调不同，意思是认识、交朋友。", "节食": "节食 jiéshí 与 结实 jiēshi 两个音节的声调都不同，意思是控制饮食。", "结石": "结石 jiéshí 与 结实 jiēshi 声调不同，意思是身体里形成的硬块。"}, "sentence_index": null, "correct_answer": "结实"}, "level_3": {"options": [{"text": "结实", "is_correct": true, "explanation": "结实：说东西牢固、不容易坏，与后半句「两个人坐也不会坏」的意思一致。"}, {"text": "脆弱", "is_correct": false, "explanation": "语义：「脆弱」说容易坏、不牢固，与后半句「不会坏」相矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：「高大」多用于人或建筑的身材、体积，不用来形容床。"}, {"text": "柔弱", "is_correct": false, "explanation": "体貌：「柔弱」形容人或植物的体态，不用来形容床的牢固程度。"}], "explanations": {"结实": "结实：说东西牢固、不容易坏，与后半句「两个人坐也不会坏」的意思一致。", "脆弱": "语义：「脆弱」说容易坏、不牢固，与后半句「不会坏」相矛盾。", "高大": "搭配：「高大」多用于人或建筑的身材、体积，不用来形容床。", "柔弱": "体貌：「柔弱」形容人或植物的体态，不用来形容床的牢固程度。"}, "sentence_index": 0, "correct_answer": "结实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这件事的态度很结实。", "explanation": "这里应该用〈坚定〉。结实形容物体牢固，说态度、立场要用坚定。"}, {"text": "他做事很结实，从不马虎。", "explanation": "这里应该用〈踏实〉。结实形容物体或身体坚固，说做事、为人稳当可靠要用踏实。"}, {"text": "这个计划很结实，我们可以马上执行。", "explanation": "这里应该用〈牢靠〉。结实说物体或身体牢固，说计划、办法可靠要用牢靠。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25458, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结实", "is_correct": true, "explanation": "结实：说东西牢固、不容易坏，符合「想买一个……盒子装工具」的要求。"}, {"text": "松软", "is_correct": false, "explanation": "搭配：「松软」多形容土壤、食物，不用来形容盒子。"}, {"text": "易碎", "is_correct": false, "explanation": "语义：「易碎」说容易碎，与「装工具」需要牢固的要求相反。"}, {"text": "娇嫩", "is_correct": false, "explanation": "搭配：「娇嫩」多形容花草、皮肤，不用来形容盒子。"}], "explanations": {"结实": "结实：说东西牢固、不容易坏，符合「想买一个……盒子装工具」的要求。", "松软": "搭配：「松软」多形容土壤、食物，不用来形容盒子。", "易碎": "语义：「易碎」说容易碎，与「装工具」需要牢固的要求相反。", "娇嫩": "搭配：「娇嫩」多形容花草、皮肤，不用来形容盒子。"}, "sentence_index": 6, "correct_answer": "结实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的学习成绩很结实，每次考试都在前十名。", "explanation": "这里应该用〈稳定〉。结实形容物体坚固耐用，说成绩、状态持续不变要用稳定。"}, {"text": "她的眼神很结实，看着孩子微笑。", "explanation": "这里应该用〈温柔〉。结实形容物体或身体坚固，说眼神、神情柔和要用温柔。"}, {"text": "老师的解释很结实，大家都听懂了。", "explanation": "这里应该用〈清楚〉。结实形容物体坚固，说解释、讲述明白易懂要用清楚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把窗户钉很结实。", "corrected_sentence": "他把窗户钉得很结实。", "error_description": "错误：「钉很结实」。正确：「钉得很结实」。「动词＋得＋形容词」作补语时，「得」不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把椅子没结实，坐上去不晃。", "corrected_sentence": "这把椅子很结实，坐上去不晃。", "error_description": "错误：“没结实”，正确：“很结实”。“结实”是形容词，不能用“没”直接否定，应当用程度副词“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482ade50-37ca-40c6-b4d4-1d3e337908b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
