INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25460, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "周围的东西改变了我们或别的东西。", "primary_collocate": null, "pronunciation": "huán jìng yǐng xiǎng", "ipa": "xwan˧˥ tɕiŋ˥˩ iŋ˨˩˦ ɕiaŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "受环境影响，这些花长得很慢。", "target_word": "环境影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受环境影响，海边的铁很快就生锈了。", "target_word": "环境影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的空气好，环境影响让人睡得很香。", "target_word": "环境影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "噪音是一种环境影响，会让人睡不好。", "target_word": "环境影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高温的环境影响会让牛奶很快变坏。", "target_word": "环境影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只鸟受环境影响，羽毛变成了灰色。", "target_word": "环境影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子旁边有工厂，环境影响很明显。", "target_word": "环境影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搬到海边，环境影响让皮肤变黑了。", "target_word": "环境影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同样的种子，受不同环境影响，长得不一样。", "target_word": "环境影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水温的环境影响会改变鱼的生长速度。", "target_word": "环境影响", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "環境影響", "label": "繁体"}], "register": "中性", "sense_fingerprint": "周围的事物让人或东西发生变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7d32c5-7ea6-49ff-a5b8-7910f90aa5ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25460, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "环境影响", "is_correct": true, "explanation": "正确：“环境影响”指周围事物的作用，“受……，这些花长得很慢”指环境使花生长变慢，符合语境。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”是经济概念，不能作为使花生长变慢的原因。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不会使花生长变慢，作为原因与语境不合。"}, {"text": "亲戚关系", "is_correct": false, "explanation": "搭配：“受”后接的是作用或因素，“亲戚关系”与花的生长无关，搭配不合。"}], "explanations": {"环境影响": "正确：“环境影响”指周围事物的作用，“受……，这些花长得很慢”指环境使花生长变慢，符合语境。", "价格": "语义：“价格”是经济概念，不能作为使花生长变慢的原因。", "颜色": "语义：“颜色”不会使花生长变慢，作为原因与语境不合。", "亲戚关系": "搭配：“受”后接的是作用或因素，“亲戚关系”与花的生长无关，搭配不合。"}, "sentence_index": 0, "correct_answer": "环境影响"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会场的环境影响很热闹。", "explanation": "这里应该用〈气氛〉。气氛可以说“热闹”；环境影响指作用，不能用“热闹”形容。"}, {"text": "这间屋子的环境影响很好，空气也很新鲜。", "explanation": "这里用的是“周围状况”的意思，这一义应只说〈环境〉，不能加“影响”。环境指周围的状况，可以说“很好”；环境影响指作用，不能用来评价状况的好坏。"}, {"text": "他把环境影响挂在墙上。", "explanation": "这里应该用〈海报〉。海报可以挂在墙上；环境影响是抽象作用，不是能挂起来的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28eee4b8-5aea-4484-a73e-9196fa0b69e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25460, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "环境影响", "is_correct": true, "explanation": "正确：“环境影响”指周围环境的作用，与“房子旁边有工厂”的语境相符，说明工厂带来的影响很明显。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人的个性特点，与房子旁边工厂带来的情况无关，句子不成立。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用来描述房子旁边工厂的情况。"}, {"text": "学历", "is_correct": false, "explanation": "语义：“学历”指受教育的程度，与工厂的位置无关，“很明显”无法修饰它。"}], "explanations": {"环境影响": "正确：“环境影响”指周围环境的作用，与“房子旁边有工厂”的语境相符，说明工厂带来的影响很明显。", "性格": "语义：“性格”指人的个性特点，与房子旁边工厂带来的情况无关，句子不成立。", "身材": "体貌：“身材”指人的体形，不能用来描述房子旁边工厂的情况。", "学历": "语义：“学历”指受教育的程度，与工厂的位置无关，“很明显”无法修饰它。"}, "sentence_index": 6, "correct_answer": "环境影响"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的环境影响很好听。", "explanation": "这里应该用〈声音〉。声音可以“好听”；环境影响指作用，不能用“好听”形容。"}, {"text": "湖面的环境影响很美。", "explanation": "这里应该用〈景色〉。景色可以“美”；环境影响是作用，不能用“美”来形容。"}, {"text": "他用环境影响做了一顿饭。", "explanation": "这里应该用〈食材〉。食材可以用来做饭；环境影响只表示作用，不能当材料使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28eee4b8-5aea-4484-a73e-9196fa0b69e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "潮湿的空气对铁进行了明显的环境影响。", "corrected_sentence": "潮湿的空气对铁产生了明显的环境影响。", "error_description": "搭配错误：“环境影响”应与“产生”搭配；“进行”用于活动，不能说“进行环境影响”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28eee4b8-5aea-4484-a73e-9196fa0b69e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种植物曾经受过很环境影响。", "corrected_sentence": "这种植物曾经受过环境影响。", "error_description": "“很”是程度副词，不能直接修饰名词性的“环境影响”；去掉“很”，说“曾经受过环境影响”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28eee4b8-5aea-4484-a73e-9196fa0b69e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
