INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25462, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "自然环境就是人们生活的地方，有山、有水、有树和动物。", "primary_collocate": null, "pronunciation": "zì rán huán jìng", "ipa": "tsɨ ʐan xwan tɕiŋ", "syllable_count": 4, "sentences": [{"text": "这里的自然环境真美，有山有水。", "target_word": "自然环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢住在自然环境好的地方。", "target_word": "自然环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们村的自然环境很好，有山有树。", "target_word": "自然环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去郊外，享受自然环境。", "target_word": "自然环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子在自然环境中长大，身体很好。", "target_word": "自然环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个公园里有水有树，自然环境不错。", "target_word": "自然环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢安静的自然环境。", "target_word": "自然环境", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "住在山里，自然环境让人很放松。", "target_word": "自然环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那儿的自然环境很美，我拍了很多照片。", "target_word": "自然环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟和小鹿在自然环境里自由生活。", "target_word": "自然环境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自然環境", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人们生活的地方，有山水树木和动物的自然景象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15493912-f1ff-4f6e-a884-3ffcb8e6a4f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25462, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自然环境", "is_correct": true, "explanation": "正确。“自然环境”指有山有水的地方，符合“真美，有山有水”的描述。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间里不会“有山有水”，与句意不符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不会“有山有水”，句子说的是户外的景象。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“课本”不能用“真美”形容山水景色，“有山有水”也与课本无关。"}], "explanations": {"自然环境": "正确。“自然环境”指有山有水的地方，符合“真美，有山有水”的描述。", "房间": "语义：房间里不会“有山有水”，与句意不符。", "厨房": "语义：厨房不会“有山有水”，句子说的是户外的景象。", "课本": "搭配：“课本”不能用“真美”形容山水景色，“有山有水”也与课本无关。"}, "sentence_index": 0, "correct_answer": "自然环境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们去郊外，欣赏一只自然环境。", "explanation": "这里应该用〈片〉。〈只〉用于动物，“自然环境”不能用“只”计量。"}, {"text": "我在山上看到一本自然环境。", "explanation": "这里应该用〈片〉。〈本〉用于书册，“自然环境”不能用“本”计量。"}, {"text": "我们走进了一条自然环境。", "explanation": "这里应该用〈片〉。〈条〉用于细长的事物，不用于“自然环境”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自然环境", "is_correct": true, "explanation": "正确。“安静的自然环境”指宁静的山水环境，符合“爷爷喜欢”的语境。"}, {"text": "集市", "is_correct": false, "explanation": "语义：集市通常热闹，与“安静的”相矛盾。"}, {"text": "夜市", "is_correct": false, "explanation": "语义：夜市是热闹的场所，与“安静”相矛盾。"}, {"text": "菜市场", "is_correct": false, "explanation": "搭配：“安静的”一般不修饰菜市场这类热闹场所，搭配不当。"}], "explanations": {"自然环境": "正确。“安静的自然环境”指宁静的山水环境，符合“爷爷喜欢”的语境。", "集市": "语义：集市通常热闹，与“安静的”相矛盾。", "夜市": "语义：夜市是热闹的场所，与“安静”相矛盾。", "菜市场": "搭配：“安静的”一般不修饰菜市场这类热闹场所，搭配不当。"}, "sentence_index": 6, "correct_answer": "自然环境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间教室的自然环境很安静。", "explanation": "这里应该用〈学习环境〉。“自然环境”指自然界的山水草木，不指教室的学习条件。"}, {"text": "这家医院的自然环境很先进，医生的技术也很好。", "explanation": "这里应该用〈医疗环境〉。“自然环境”指山水、树木和动物等自然条件，不指医院的设备和技术。"}, {"text": "这家电视台的自然环境很严格，领导对员工要求很高。", "explanation": "这里应该用〈工作环境〉。“自然环境”指山水草木等自然条件，不指单位的管理和工作条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山里的自然环境们很好。", "corrected_sentence": "山里的自然环境很好。", "error_description": "词缀错误：“自然环境”后不能加“们”，“们”只用于人。正确形式是“自然环境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那座山的一本自然环境很好。", "corrected_sentence": "那座山的一片自然环境很好。", "error_description": "量词错误：“本”用于书册，不能用来计量“自然环境”，应改为“片”，说“一片自然环境”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25464, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b99651-0abe-4b04-920c-e49b01efcde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25464, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b99651-0abe-4b04-920c-e49b01efcde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25464, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可以控制的。", "primary_collocate": null, "pronunciation": "kě kòng", "ipa": "kʰɤ˨˩˦ kʰʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "房间里的灯光亮度是可控的。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "情绪可控的人，做事更冷静。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器人的动作完全可控。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得自己的压力还可控。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的水位现在是可控的。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的开支很可控，不会花太多。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种火是可控的，不会烧到别处。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气我们管不了，但自己的计划可控。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说这个项目的风险可控。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的体重一直可控，没有变胖。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可控性", "label": "复合"}, {"form": "不可控", "label": "复合"}], "register": "书面", "sense_fingerprint": "人可以控制的，不会失去掌握", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd52fbb8a-e422-4bf9-afdc-b8bdbc3cafb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25464, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可控", "is_correct": true, "explanation": "“可控”指灯光亮度能被人调节，与句意相符。"}, {"text": "甜美", "is_correct": false, "explanation": "语义：“甜美”形容味道或声音，灯光亮度不能说甜美，与句意不符。"}, {"text": "易碎", "is_correct": false, "explanation": "语义：亮度不会碎，“易碎”与句意不符。"}, {"text": "可笑", "is_correct": false, "explanation": "语义：灯光亮度不可笑，这个词与句子的意思无关。"}], "explanations": {"可控": "“可控”指灯光亮度能被人调节，与句意相符。", "甜美": "语义：“甜美”形容味道或声音，灯光亮度不能说甜美，与句意不符。", "易碎": "语义：亮度不会碎，“易碎”与句意不符。", "可笑": "语义：灯光亮度不可笑，这个词与句子的意思无关。"}, "sentence_index": 0, "correct_answer": "可控"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一个非常可控的朋友，有事都会找他。", "explanation": "这里应该用〈可靠〉。“可靠”形容人值得信赖；“可控”指能被控制，不用来说人的可信度。"}, {"text": "这个想法很可控，我们下周就去做。", "explanation": "这里应该用〈可行〉。“可行”指方案能够实施；“可控”说能被控制，不用来评价想法能否实施。"}, {"text": "这台电梯很可控，每天都有人检查。", "explanation": "这里应该用〈安全〉。“安全”说不会出事；“可控”强调能被控制，不等于安全。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b99651-0abe-4b04-920c-e49b01efcde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25464, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可控", "is_correct": true, "explanation": "“可控”指火能被控制，与“不会烧到别处”的意思相符。"}, {"text": "易碎", "is_correct": false, "explanation": "语义：火不会“易碎”，与“不会烧到别处”的意思无关。"}, {"text": "易燃", "is_correct": false, "explanation": "语义：“易燃”说明火容易蔓延，与“不会烧到别处”的意思相反。"}, {"text": "可爱", "is_correct": false, "explanation": "语义：火不具有“可爱”的特征，与句意不符。"}], "explanations": {"可控": "“可控”指火能被控制，与“不会烧到别处”的意思相符。", "易碎": "语义：火不会“易碎”，与“不会烧到别处”的意思无关。", "易燃": "语义：“易燃”说明火容易蔓延，与“不会烧到别处”的意思相反。", "可爱": "语义：火不具有“可爱”的特征，与句意不符。"}, "sentence_index": 6, "correct_answer": "可控"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的身体很可控，很少生病。", "explanation": "这里应该用〈健康〉。“健康”形容身体状况好；“可控”说能被控制，不用来形容身体好坏。"}, {"text": "这个问题他解释得很可控。", "explanation": "这里应该用〈清楚〉。“清楚”形容说明得明白；“可控”不表示说明的效果。"}, {"text": "这次比赛的胜负很可控，谁也猜不到结果。", "explanation": "这里应该用〈难料〉。“难料”指难以预料；“可控”说能被控制，与“谁也猜不到”的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b99651-0abe-4b04-920c-e49b01efcde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25464, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个机器人的速度被可控。", "corrected_sentence": "这个机器人的速度可控。", "error_description": "“可控”前多加了“被”。“可控”是形容词，表示“能被控制”，本身不是被动动词，不能再用“被”。应改为“这个机器人的速度可控”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b99651-0abe-4b04-920c-e49b01efcde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25464, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次实验的温度没可控，结果不准。", "corrected_sentence": "这次实验的温度不可控，结果不准。", "error_description": "否定形式错误：修饰形容词“可控”应用“不”，不能用“没”。应改为“不可控”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b99651-0abe-4b04-920c-e49b01efcde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
