INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25470, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个东西很不一样，一眼就能看出来。", "primary_collocate": null, "pronunciation": "xiān míng duì bǐ", "ipa": "ɕjɛn˥ miŋ˧˥ twei˥˩ pi˨˩˦", "syllable_count": 4, "sentences": [{"text": "白雪和黑石头形成鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥很高，弟弟很矮，这是鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天很热，冬天很冷，形成鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红衣服和白墙形成了鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的房间很乱，我的房间很干净，真是鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个孩子的性格形成鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新楼很高，旧房子很矮，两者是鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白天很吵，晚上很安静，是一个鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两杯水一冷一热，形成鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着说话，她哭着回答，形成了鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "两个东西很不一样，一眼就看得出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd52fbb8a-e422-4bf9-afdc-b8bdbc3cafb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鲜明对比", "is_correct": true, "explanation": "“鲜明对比”指两个事物差别清楚，正符合白雪与黑石头的反差。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“形成”后接的是关系或结果，不说“形成颜色”。"}, {"text": "共鸣", "is_correct": false, "explanation": "语义：“共鸣”表示同频回应或认同，与白与黑的对照不符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”是可称量的数值，不能与“形成”搭配。"}], "explanations": {"鲜明对比": "“鲜明对比”指两个事物差别清楚，正符合白雪与黑石头的反差。", "颜色": "搭配：“形成”后接的是关系或结果，不说“形成颜色”。", "共鸣": "语义：“共鸣”表示同频回应或认同，与白与黑的对照不符。", "体重": "搭配：“体重”是可称量的数值，不能与“形成”搭配。"}, "sentence_index": 0, "correct_answer": "鲜明对比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两件外套的颜色几乎一样，却形成了鲜明对比。", "explanation": "这里应该用〈相似〉。“鲜明对比”强调两者差别明显，不能用来说两样东西几乎一样。"}, {"text": "这个花园只有一种颜色，却形成了鲜明对比。", "explanation": "这里应该用〈单一〉。“鲜明对比”需要两个或更多事物互相衬托，只有一种东西时不能说形成鲜明对比。"}, {"text": "这两个数字只差了一点，却被说成鲜明对比。", "explanation": "这里应该用〈细微〉。“鲜明对比”强调差别明显；差别细微时不能说是鲜明对比。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b99651-0abe-4b04-920c-e49b01efcde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鲜明对比", "is_correct": true, "explanation": "“鲜明对比”说明两者差别明显，符合新楼与旧房子一高一矮的描述。"}, {"text": "联系", "is_correct": false, "explanation": "语义：“联系”说明事物相关，不说明高矮的反差。"}, {"text": "相等", "is_correct": false, "explanation": "语义：“相等”指数量或程度一样，与句中一高一矮相冲突。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”用于人或动物，不能用来描述新楼和旧房子。"}], "explanations": {"鲜明对比": "“鲜明对比”说明两者差别明显，符合新楼与旧房子一高一矮的描述。", "联系": "语义：“联系”说明事物相关，不说明高矮的反差。", "相等": "语义：“相等”指数量或程度一样，与句中一高一矮相冲突。", "体重": "搭配：“体重”用于人或动物，不能用来描述新楼和旧房子。"}, "sentence_index": 6, "correct_answer": "鲜明对比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们两人的性格形成了一只鲜明对比。", "explanation": "这里应该用〈种〉或〈个〉。“只”用于动物或成对物品中的一个，不能用来计数抽象的“鲜明对比”。"}, {"text": "这两位同学的答案鲜明对比，老师说他们完全一样。", "explanation": "这里应该用〈一致〉。“一致”说明两者相同；“鲜明对比”强调差别明显，与“完全一样”正好矛盾。"}, {"text": "这首歌只有一种旋律，却被说成鲜明对比。", "explanation": "这里应该用〈单一〉。“鲜明对比”需要两个或更多事物互相衬托，只有一种东西时不能说形成鲜明对比。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b99651-0abe-4b04-920c-e49b01efcde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两幅画的颜色形成了一只鲜明对比。", "corrected_sentence": "这两幅画的颜色形成了一个鲜明对比。", "error_description": "量词错误：“鲜明对比”是抽象名词，应该用“个”或“种”，不用“只”。“只”多用于动物或成对物品中的一个。正确说法是“一个鲜明对比”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b99651-0abe-4b04-920c-e49b01efcde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们两人的性格形成很鲜明对比。", "corrected_sentence": "他们两人的性格形成鲜明对比。", "error_description": "程度副词误用：“鲜明对比”是固定的名词性短语，不能再受“很”修饰。应说“形成鲜明对比”，不说“形成很鲜明对比”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b99651-0abe-4b04-920c-e49b01efcde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25472, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b99651-0abe-4b04-920c-e49b01efcde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25472, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b99651-0abe-4b04-920c-e49b01efcde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25472, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "分子是组成东西的小粒子，分子结构就是这些小粒子怎么连在一起。", "primary_collocate": null, "pronunciation": "fēn zǐ jié gòu", "ipa": "fən˥ tsɹ̩˨˩˦ tɕjɛ˧˥ kou˥˩", "syllable_count": 4, "sentences": [{"text": "水的分子结构很简单，只有三个原子。", "target_word": "分子结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用仪器看清了这种药的分子结构。", "target_word": "分子结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种油的分子结构不同，所以性质也不同。", "target_word": "分子结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画出了水的分子结构。", "target_word": "分子结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改变分子结构，就能得到新的材料。", "target_word": "分子结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正在研究蛋白质的分子结构。", "target_word": "分子结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种塑料的分子结构很稳定，不容易坏。", "target_word": "分子结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用小球和小棍做了一个分子结构的模型。", "target_word": "分子结构", "complexity_tier": "T3", "furigana": "wǒ men yòng xiǎo qiú hé xiǎo gùn zuò le yí gè fēn zǐ jié gòu de mó xíng", "sentence_source": "generated"}, {"text": "药的分子结构一变，效果也会跟着变。", "target_word": "分子结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课本上有一张酒精分子结构的图。", "target_word": "分子结构", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分子结构式", "label": "复合"}, {"form": "分子結構", "label": "繁体"}], "register": "书面", "sense_fingerprint": "物质中分子里原子的连接和排列方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd52fbb8a-e422-4bf9-afdc-b8bdbc3cafb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25472, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分子结构", "is_correct": true, "explanation": "“分子结构”指分子中原子的排列，说水的“很简单，只有三个原子”正合理。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱的数额，与原子的数量无关。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是视觉属性，不能用原子的个数来描述简单程度。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”用于人或动物，不用于水的组成。"}], "explanations": {"分子结构": "“分子结构”指分子中原子的排列，说水的“很简单，只有三个原子”正合理。", "价格": "语义：“价格”指钱的数额，与原子的数量无关。", "颜色": "语义：“颜色”是视觉属性，不能用原子的个数来描述简单程度。", "体重": "搭配：“体重”用于人或动物，不用于水的组成。"}, "sentence_index": 0, "correct_answer": "分子结构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的分子结构很漂亮。", "explanation": "这里应该用〈外形〉。“分子结构”专指分子内原子的排列，不能说汽车的样子；形容外观要用“外形”。"}, {"text": "这瓶饮料的分子结构是水和糖。", "explanation": "这里应该用〈成分〉。“分子结构”说的是原子怎样连接排列，列出由什么组成要用“成分”。"}, {"text": "这家医院的分子结构很完善。", "explanation": "这里应该用〈机构〉。“分子结构”不能形容医院；医院的组织安排要用“机构”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b99651-0abe-4b04-920c-e49b01efcde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25472, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分子结构", "is_correct": true, "explanation": "“分子结构”指原子的排列方式，塑料的分子结构决定它是否稳定。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”属于人或动物，不能用来形容塑料的稳定。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”只用于人或生物，不用于塑料。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”指人或生物的高矮，不说塑料的身高。"}], "explanations": {"分子结构": "“分子结构”指原子的排列方式，塑料的分子结构决定它是否稳定。", "性格": "语义：“性格”属于人或动物，不能用来形容塑料的稳定。", "年龄": "搭配：“年龄”只用于人或生物，不用于塑料。", "身高": "搭配：“身高”指人或生物的高矮，不说塑料的身高。"}, "sentence_index": 6, "correct_answer": "分子结构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的分子结构很光滑。", "explanation": "这里应该用〈皮肤〉。“分子结构”不能形容人的皮肤；形容皮肤光滑要用“皮肤”。"}, {"text": "这个游戏的分子结构很简单。", "explanation": "这里应该用〈规则〉。“分子结构”指物质中原子的排列，不能说游戏的规则。"}, {"text": "这个方案的分子结构很完整。", "explanation": "这里应该用〈方案〉。“分子结构”专指化学物质的原子排列，不能形容方案的完整程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b99651-0abe-4b04-920c-e49b01efcde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种金属有一只特别的分子结构。", "corrected_sentence": "这种金属有一种特别的分子结构。", "error_description": "量词错误：“分子结构”的量词应用“种”，不用“只”。“只”一般用于动物或成对物品中的一个。正确说法是“一种特别的分子结构”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b99651-0abe-4b04-920c-e49b01efcde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她认真研究了蛋白质的很分子结构。", "corrected_sentence": "她认真研究了蛋白质的分子结构。", "error_description": "程度副词误用：“很”不能插在“的”和名词之间修饰“分子结构”。“分子结构”是名词，应直接说“蛋白质的分子结构”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b99651-0abe-4b04-920c-e49b01efcde7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
