INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25482, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "让东西连在一起的小小化学扣子。", "primary_collocate": null, "pronunciation": "zhǐ jiàn", "ipa": "ʈʂɨ˨˩˦ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "酯键像一个小扣子，把两个部分连起来。", "target_word": "酯键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酯键让小分子连在一起。", "target_word": "酯键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酯键断了，大分子就会散开。", "target_word": "酯键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "脂肪里有很多酯键。", "target_word": "酯键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酯键很小，眼睛看不到。", "target_word": "酯键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，酯键是一种化学键。", "target_word": "酯键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个分子上有两个酯键。", "target_word": "酯键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水能把酯键慢慢打开。", "target_word": "酯键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "脂肪分子是靠酯键把甘油和脂肪酸连在一起的。", "target_word": "酯键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在课上学习了什么是酯键。", "target_word": "酯键", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "酯鍵", "label": "繁体"}], "register": "通用", "sense_fingerprint": "把分子扣在一起的小扣子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e0a8f54-0469-4f4e-9eca-99ba31d55a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25482, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "酯键", "is_correct": true, "explanation": "酯键像小扣子，能把两个部分连起来，与句意相符。"}, {"text": "大海", "is_correct": false, "explanation": "体貌：大海很大，不像小扣子，“小扣子”的比喻说不通。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是人，不是扣子，不能“把两个部分连起来”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是电子设备，不是用来连接两个部分的小扣子。"}], "explanations": {"酯键": "酯键像小扣子，能把两个部分连起来，与句意相符。", "大海": "体貌：大海很大，不像小扣子，“小扣子”的比喻说不通。", "老师": "语义：老师是人，不是扣子，不能“把两个部分连起来”。", "手机": "语义：手机是电子设备，不是用来连接两个部分的小扣子。"}, "sentence_index": 0, "correct_answer": "酯键"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个氨基酸靠酯键连在一起。", "explanation": "这里应该用〈酰胺键〉。氨基酸之间靠酰胺键连接，酯键连接的是脂肪酸和甘油。"}, {"text": "碱基对靠酯键连在一起。", "explanation": "这里应该用〈氢键〉。碱基对之间靠氢键相连，酯键是连接脂肪酸与甘油的化学键。"}, {"text": "淀粉分子里的葡萄糖单元靠酯键连接。", "explanation": "这里应该用〈糖苷键〉。葡萄糖单元之间靠糖苷键连接，酯键连接的是脂肪酸和甘油。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49debda0-9f19-4f66-a0be-ab0c14ef49f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25482, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "酯键", "is_correct": true, "explanation": "酯键是分子上的化学键，与“这个分子上有两个”搭配，句意通顺。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜是水果，不会出现在分子上，句子说不通。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间是建筑空间，不是分子的组成部分。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是视觉属性，分子上不能数“两个颜色”，句意说不通。"}], "explanations": {"酯键": "酯键是分子上的化学键，与“这个分子上有两个”搭配，句意通顺。", "西瓜": "语义：西瓜是水果，不会出现在分子上，句子说不通。", "房间": "语义：房间是建筑空间，不是分子的组成部分。", "颜色": "语义：颜色是视觉属性，分子上不能数“两个颜色”，句意说不通。"}, "sentence_index": 6, "correct_answer": "酯键"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天喝一杯酯键，身体很健康。", "explanation": "这里的“酯键”被当成了饮料。酯键是分子中的化学键，不是可以喝的东西。"}, {"text": "爷爷把酯键挂在墙上当装饰。", "explanation": "这里的“酯键”被当成了装饰品。酯键是化学结构，不是可以挂在墙上的物件。"}, {"text": "我用酯键给妹妹煮了一碗面。", "explanation": "这里的“酯键”被当成了食材。酯键是化学键，不能拿来煮面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49debda0-9f19-4f66-a0be-ab0c14ef49f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个分子里有三根酯键。", "corrected_sentence": "这个分子里有三个酯键。", "error_description": "量词错误：“酯键”的量词应为“个”，“根”用于细长的实物，不能说“三根酯键”，应说“三个酯键”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49debda0-9f19-4f66-a0be-ab0c14ef49f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "碱液酯键慢慢打开了。", "corrected_sentence": "碱液把酯键慢慢打开了。", "error_description": "把字句遗漏：处置式中“酯键”须由“把”引出，应说“碱液把酯键慢慢打开了”；省去“把”后“碱液酯键慢慢打开了”结构不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49debda0-9f19-4f66-a0be-ab0c14ef49f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
