INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25484, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "酰胺键是一种把两个小分子连在一起的“小手”，在身体里的蛋白质中很重要。", "primary_collocate": null, "pronunciation": "xiān àn jiàn", "ipa": "ɕjɛn˥ an˥˩ tɕjɛn˥˩", "syllable_count": 3, "sentences": [{"text": "酰胺键像小手，把两个小分子拉在一起。", "target_word": "酰胺键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酰胺键在蛋白质里很重要。", "target_word": "酰胺键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的身体里有很多酰胺键。", "target_word": "酰胺键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酰胺键就像手拉手一样。", "target_word": "酰胺键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酰胺键断了，蛋白质就会散开。", "target_word": "酰胺键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师告诉我们什么是酰胺键。", "target_word": "酰胺键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小分子通过酰胺键连着另一个。", "target_word": "酰胺键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个氨基酸靠酰胺键连在一起。", "target_word": "酰胺键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃肉时，身体要打开蛋白质的酰胺键。", "target_word": "酰胺键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有酰胺键，蛋白质就不能成形。", "target_word": "酰胺键", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "醯胺鍵", "label": "繁体"}], "register": "通用", "sense_fingerprint": "把小分子拉在一起的小手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e0a8f54-0469-4f4e-9eca-99ba31d55a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25484, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "酰胺键", "is_correct": true, "explanation": "酰胺键像小手，能把两个小分子拉在一起，与句意相符。"}, {"text": "大山", "is_correct": false, "explanation": "体貌：大山很大，与“小手”的比喻相反，句子说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以拉住分子的东西，“天气像小手”说不通。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：老鼠是动物，不能比作把分子拉在一起的结构。"}], "explanations": {"酰胺键": "酰胺键像小手，能把两个小分子拉在一起，与句意相符。", "大山": "体貌：大山很大，与“小手”的比喻相反，句子说不通。", "天气": "语义：天气不是可以拉住分子的东西，“天气像小手”说不通。", "老鼠": "语义：老鼠是动物，不能比作把分子拉在一起的结构。"}, "sentence_index": 0, "correct_answer": "酰胺键"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "油脂里的脂肪酸靠酰胺键和甘油相连。", "explanation": "这里应该用〈酯键〉。脂肪酸与甘油靠酯键相连，酰胺键连接的是氨基酸。"}, {"text": "淀粉的葡萄糖分子靠酰胺键连接。", "explanation": "这里应该用〈糖苷键〉。葡萄糖分子之间靠糖苷键连接，酰胺键不连接糖。"}, {"text": "碱基对之间靠酰胺键配对。", "explanation": "这里应该用〈氢键〉。碱基对之间靠氢键配对，酰胺键连接的是碳原子和氮原子，常见于蛋白质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49debda0-9f19-4f66-a0be-ab0c14ef49f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25484, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "酰胺键", "is_correct": true, "explanation": "酰胺键能把两个小分子连在一起，“通过酰胺键连着另一个”句意通顺。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是连接分子的结构，“通过天空连着另一个”说不通。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪是液体，不能把两个小分子连在一起。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“连着”不接“颜色”，颜色不是连接的媒介。"}], "explanations": {"酰胺键": "酰胺键能把两个小分子连在一起，“通过酰胺键连着另一个”句意通顺。", "天空": "语义：天空不是连接分子的结构，“通过天空连着另一个”说不通。", "眼泪": "语义：眼泪是液体，不能把两个小分子连在一起。", "颜色": "搭配：“连着”不接“颜色”，颜色不是连接的媒介。"}, "sentence_index": 6, "correct_answer": "酰胺键"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用酰胺键煮了一锅粥。", "explanation": "这里的“酰胺键”被当成了食材。酰胺键是分子中的连接结构，不能拿来煮粥。"}, {"text": "他把酰胺键带到学校，送给老师。", "explanation": "这里的“酰胺键”被当成了可以送人的物品。酰胺键是化学结构，不是礼物。"}, {"text": "我们在公园里跟酰胺键聊天。", "explanation": "这里的“酰胺键”被当成了可以交谈的对象。酰胺键是化学结构，不会与人聊天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49debda0-9f19-4f66-a0be-ab0c14ef49f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25484, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个分子里有两只酰胺键。", "corrected_sentence": "这个分子里有两个酰胺键。", "error_description": "量词错误：“只”用于动物或成对器官中的一个，不用于酰胺键；应说“两个酰胺键”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49debda0-9f19-4f66-a0be-ab0c14ef49f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蛋白酶切断了一张酰胺键。", "corrected_sentence": "蛋白酶切断了一个酰胺键。", "error_description": "量词错误：“张”用于纸、桌子等平面的东西，酰胺键不能用“张”计量，应说“一个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49debda0-9f19-4f66-a0be-ab0c14ef49f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
