INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25486, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个单独的物体，比如一个积木。", "primary_collocate": null, "pronunciation": "dān tǐ", "ipa": "tan˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "一块积木就是一个单体。", "target_word": "单体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把积木拆成了一个个单体。", "target_word": "单体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟喜欢把单体一个一个放在桌上。", "target_word": "单体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个单体都有自己的颜色。", "target_word": "单体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个单体太小，一只手就能拿住。", "target_word": "单体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有很多单体，没有一个是连着的。", "target_word": "单体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让孩子们数一数有几个单体。", "target_word": "单体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "单体可以自己玩，也可以拼成大房子。", "target_word": "单体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个单体放回盒子里。", "target_word": "单体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盒子里有二十个单体。", "target_word": "单体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "單體", "label": "繁体"}], "register": "中性", "sense_fingerprint": "单体|一个单独的物体，如一块积木", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e0a8f54-0469-4f4e-9eca-99ba31d55a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25486, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "单体", "is_correct": true, "explanation": "“单体”指一个单独的物体，这里说一块积木就是一个单独的物体，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是看不见的气体，不是可以拿在手里的单个物件，不能与积木相比。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能说它“就是一个”积木式的物件。"}, {"text": "海洋", "is_correct": false, "explanation": "搭配：量词“个”不搭“海洋”，海洋应说“一片”。"}], "explanations": {"单体": "“单体”指一个单独的物体，这里说一块积木就是一个单独的物体，符合句意。", "空气": "语义：空气是看不见的气体，不是可以拿在手里的单个物件，不能与积木相比。", "月亮": "语义：月亮是天体，不能说它“就是一个”积木式的物件。", "海洋": "搭配：量词“个”不搭“海洋”，海洋应说“一片”。"}, "sentence_index": 0, "correct_answer": "单体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌上放着一条单体。", "explanation": "这里应该用〈块〉。“条”用于长条形的东西，积木用“块”或“个”。"}, {"text": "这个班级里每个单体都很努力。", "explanation": "这里误把“单体”用于人。“单体”指一个物体，如积木，不能指人；指人应说〈个人〉。"}, {"text": "这种动物的每个单体都很健康。", "explanation": "这里误把“单体”用于动物。“单体”指物体，不能指动物；这里应说〈个体〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49debda0-9f19-4f66-a0be-ab0c14ef49f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25486, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "单体", "is_correct": true, "explanation": "“几个单体”指可以一个一个数的单独物件，符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是背景，不是可以一个一个数的物件。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“几个”搭配的是可数名词，音乐不可数，应说“几首”。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：阳光应说“几束”，不能说“几个”。"}], "explanations": {"单体": "“几个单体”指可以一个一个数的单独物件，符合句意。", "天空": "语义：天空是背景，不是可以一个一个数的物件。", "音乐": "搭配：“几个”搭配的是可数名词，音乐不可数，应说“几首”。", "阳光": "搭配：阳光应说“几束”，不能说“几个”。"}, "sentence_index": 6, "correct_answer": "单体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套玩具是一个单体，必须整套卖。", "explanation": "这里误把“单体”用于整体。“单体”指单独一个物体，“整套”由多个组成，二者不能指同一物。"}, {"text": "盒子里有二十张单体。", "explanation": "这里应该用〈个〉。“张”多用于纸、桌子等平面的东西，单体不能用“张”计量。"}, {"text": "这首曲子是一个单体，不能分开演奏。", "explanation": "这里误把“单体”用于整体。“单体”指单独一个物体，一首曲子是整体，不能说是单体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49debda0-9f19-4f66-a0be-ab0c14ef49f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25486, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "哥哥把玩具拆开，每根单体都洗干净了。", "corrected_sentence": "哥哥把玩具拆开，每个单体都洗干净了。", "error_description": "量词错误：“单体”是独立的物件，应该用“个”，不能用“根”。“根”用于细长条的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49debda0-9f19-4f66-a0be-ab0c14ef49f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25486, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从书包里拿出了三架单体。", "corrected_sentence": "他从书包里拿出了三个单体。", "error_description": "量词错误：“架”用于飞机、机器等大型器械，积木式的单体不能用“架”，应说“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49debda0-9f19-4f66-a0be-ab0c14ef49f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
