INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25504, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "聚乳酸是一种可以做成杯子、瓶子的塑料，它来自玉米等植物，能被土壤分解。", "primary_collocate": null, "pronunciation": "jù rǔ suān", "ipa": "tɕy˥˩ ɻu˨˩˧ swan˥", "syllable_count": 3, "sentences": [{"text": "这个杯子是聚乳酸做的。", "target_word": "聚乳酸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "聚乳酸来自玉米，不是石油。", "target_word": "聚乳酸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "聚乳酸瓶子埋在土里会慢慢烂掉。", "target_word": "聚乳酸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我买了一个聚乳酸的饭盒。", "target_word": "聚乳酸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种瓶子用聚乳酸做，能被土壤分解。", "target_word": "聚乳酸", "complexity_tier": "T3", "furigana": "zhè zhǒng píng zi yòng jù rǔ suān zuò, néng bèi tǔ rǎng fēn jiě.", "sentence_source": "generated"}, {"text": "这种瓶子的原料是聚乳酸。", "target_word": "聚乳酸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店里的环保杯多是聚乳酸做的。", "target_word": "聚乳酸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用过的聚乳酸杯子可以埋进土里。", "target_word": "聚乳酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "聚乳酸是用植物做的塑料。", "target_word": "聚乳酸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们用聚乳酸瓶子做了小花盆。", "target_word": "聚乳酸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聚乳酸塑料", "label": "复合"}], "register": "中性", "sense_fingerprint": "来自植物、可做杯瓶并能被土壤分解的塑料，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a2eef82-e2a5-4921-a402-957c326196e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25504, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聚乳酸", "is_correct": true, "explanation": "正确。“聚乳酸”是一种可以做杯子的植物来源塑料，句中说杯子是它做的。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：面粉是食材，不是能做成杯子的材料，句子读起来不通。"}, {"text": "水泥", "is_correct": false, "explanation": "搭配：“水泥”多用于建筑，不说“水泥做的杯子”，与日用品的材料搭配不符。"}, {"text": "粉笔", "is_correct": false, "explanation": "语义：粉笔是书写用品，易碎，不用来做杯子。"}], "explanations": {"聚乳酸": "正确。“聚乳酸”是一种可以做杯子的植物来源塑料，句中说杯子是它做的。", "面粉": "语义：面粉是食材，不是能做成杯子的材料，句子读起来不通。", "水泥": "搭配：“水泥”多用于建筑，不说“水泥做的杯子”，与日用品的材料搭配不符。", "粉笔": "语义：粉笔是书写用品，易碎，不用来做杯子。"}, "sentence_index": 0, "correct_answer": "聚乳酸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一瓶聚乳酸饮料。", "explanation": "这里应该用〈果汁〉。饮料指可以喝的液体，这里应说果汁一类饮品；聚乳酸是做杯子、瓶子的塑料，不能喝。"}, {"text": "妈妈用聚乳酸包饺子。", "explanation": "这里应该用〈面粉〉。包饺子要用面粉和水做皮；聚乳酸是做杯子、瓶子的塑料，不能用来包饺子。"}, {"text": "我在花园里挖了一些聚乳酸，准备种花。", "explanation": "这里应该用〈泥土〉。挖出来准备种花的是泥土；聚乳酸是做杯子、瓶子的塑料，不是泥土。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '100ba33e-a3e8-451e-9560-f0328b544790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聚乳酸", "is_correct": true, "explanation": "正确。“聚乳酸”是一种可以做环保杯的植物来源塑料，句中说商店里的环保杯多是它做的。"}, {"text": "沥青", "is_correct": false, "explanation": "搭配：“沥青”多用于铺设道路，不用来做杯子，与“环保杯”的材料搭配不符。"}, {"text": "石灰", "is_correct": false, "explanation": "语义：石灰是无机材料，粉状易碎，不能做成环保杯，句子读起来不通。"}, {"text": "煤炭", "is_correct": false, "explanation": "语义：煤炭是燃料，不能用来做杯子，与“环保杯”的说法不符。"}], "explanations": {"聚乳酸": "正确。“聚乳酸”是一种可以做环保杯的植物来源塑料，句中说商店里的环保杯多是它做的。", "沥青": "搭配：“沥青”多用于铺设道路，不用来做杯子，与“环保杯”的材料搭配不符。", "石灰": "语义：石灰是无机材料，粉状易碎，不能做成环保杯，句子读起来不通。", "煤炭": "语义：煤炭是燃料，不能用来做杯子，与“环保杯”的说法不符。"}, "sentence_index": 6, "correct_answer": "聚乳酸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人用聚乳酸砌了一面墙。", "explanation": "这里应该用〈水泥〉。砌墙要用水泥；聚乳酸是做杯子、瓶子的塑料，不能用来砌墙。"}, {"text": "厨师在菜里加了一勺聚乳酸。", "explanation": "这里应该用〈醋〉。给菜调味要用醋；聚乳酸是做杯子、瓶子的塑料，不能当调料。"}, {"text": "孩子们在院子里养了聚乳酸。", "explanation": "这里应该用〈小狗〉。院子里养的是小狗之类的动物；聚乳酸是塑料，不是动物，不能养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '100ba33e-a3e8-451e-9560-f0328b544790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种的聚乳酸杯子很轻。", "corrected_sentence": "这种聚乳酸杯子很轻。", "error_description": "“的”的位置错误：指示词“这种”后直接接名词，不能加“的”，应写成“这种聚乳酸杯子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '100ba33e-a3e8-451e-9560-f0328b544790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小花盆被聚乳酸瓶子做的。", "corrected_sentence": "这个小花盆是用聚乳酸瓶子做的。", "error_description": "介词错误：说明用某种材料制作时应用“用”；“被”表示被动，不能引入制作材料。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '100ba33e-a3e8-451e-9560-f0328b544790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25506, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "散", "is_correct": true, "explanation": "散是“聚”的反义词，指分散、分开，与“聚”（收拢到一起）相对。"}, {"text": "扔", "is_correct": false, "explanation": "扔是丢弃的意思，与“聚”没有反义关系。"}, {"text": "搬", "is_correct": false, "explanation": "搬是移动的意思，与“聚”没有反义关系。"}, {"text": "擦", "is_correct": false, "explanation": "擦是抹去污物的意思，与“聚”没有反义关系。"}], "correct_answer": "散", "explanations": {"散": "散是“聚”的反义词，指分散、分开，与“聚”（收拢到一起）相对。", "扔": "扔是丢弃的意思，与“聚”没有反义关系。", "搬": "搬是移动的意思，与“聚”没有反义关系。", "擦": "擦是抹去污物的意思，与“聚”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ae8a38d-474d-4287-90a5-7a2e2072e722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25506, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "散", "is_correct": true, "explanation": "散是“聚”的反义词，指分散、分开，与“聚”（收拢到一起）相对。"}, {"text": "摆", "is_correct": false, "explanation": "摆是陈列、安放的意思，与“聚”没有反义关系。"}, {"text": "放", "is_correct": false, "explanation": "放是放置的意思，与“聚”没有反义关系。"}, {"text": "抬", "is_correct": false, "explanation": "抬是用力托起的意思，与“聚”没有反义关系。"}], "correct_answer": "散", "explanations": {"散": "散是“聚”的反义词，指分散、分开，与“聚”（收拢到一起）相对。", "摆": "摆是陈列、安放的意思，与“聚”没有反义关系。", "放": "放是放置的意思，与“聚”没有反义关系。", "抬": "抬是用力托起的意思，与“聚”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ae8a38d-474d-4287-90a5-7a2e2072e722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25506, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放在一起。", "primary_collocate": null, "pronunciation": "jù", "ipa": "tɕy˥˩", "syllable_count": 1, "sentences": [{"text": "他把散落的硬币聚在一起，装进盒子里。", "target_word": "聚", "complexity_tier": "T3", "furigana": "tā bǎ sàn luò de yìng bì jù zài yì qǐ, zhuāng jìn hé zi lǐ", "sentence_source": "generated"}, {"text": "我们把零钱聚在一起买了礼物。", "target_word": "聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把地上的碎纸聚在一起，扔进垃圾桶。", "target_word": "聚", "complexity_tier": "T3", "furigana": "tā bǎ dì shang de suì zhǐ jù zài yì qǐ, rēng jìn lā jī tǒng", "sentence_source": "generated"}, {"text": "小孩把石头聚成一堆。", "target_word": "聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把桌上的书都聚到一边，腾出地方。", "target_word": "聚", "complexity_tier": "T3", "furigana": "tā bǎ zhuō shang de shū dōu jù dào yì biān, téng chū dì fang", "sentence_source": "generated"}, {"text": "把这些旧衣服聚在一起捐出去。", "target_word": "聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把沙子聚成一堆。", "target_word": "聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把照片聚在一起做成相册。", "target_word": "聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把桌上的卡片聚到一起，好吗？", "target_word": "聚", "complexity_tier": "T3", "furigana": "qǐng bǎ zhuō shang de kǎ piàn jù dào yì qǐ, hǎo ma", "sentence_source": "generated"}, {"text": "风把落叶聚在墙角。", "target_word": "聚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聚了", "label": "完成体"}, {"form": "聚着", "label": "持续体"}, {"form": "聚过", "label": "经历体"}, {"form": "聚集", "label": "复合"}], "register": "中性", "sense_fingerprint": "把分散的东西收拢、堆放在一处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b7c4d2-eae5-47dc-9765-446b23df0243') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25506, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "聚", "is_correct": true, "explanation": "聚 jù 是本词，意思是把分散的东西收拢在一起。"}, {"text": "居", "is_correct": false, "explanation": "jū（第一声）与 jù（第四声）声调不同，意思是居住。"}, {"text": "举", "is_correct": false, "explanation": "jǔ（第三声）与 jù（第四声）声调不同，意思是举起。"}, {"text": "去", "is_correct": false, "explanation": "qù 与 jù 声母不同（q 与 j），声调相同，意思是去。"}, {"text": "续", "is_correct": false, "explanation": "xù 与 jù 声母不同（x 与 j），声调相同，意思是继续。"}, {"text": "菊", "is_correct": false, "explanation": "jú（第二声）与 jù（第四声）声调不同，意思是菊花。"}], "explanations": {"聚": "聚 jù 是本词，意思是把分散的东西收拢在一起。", "居": "jū（第一声）与 jù（第四声）声调不同，意思是居住。", "举": "jǔ（第三声）与 jù（第四声）声调不同，意思是举起。", "去": "qù 与 jù 声母不同（q 与 j），声调相同，意思是去。", "续": "xù 与 jù 声母不同（x 与 j），声调相同，意思是继续。", "菊": "jú（第二声）与 jù（第四声）声调不同，意思是菊花。"}, "sentence_index": null, "correct_answer": "聚"}, "level_3": {"options": [{"text": "聚", "is_correct": true, "explanation": "正确：“聚在一起”指把散落的硬币收拢到一处，与句中语境吻合。"}, {"text": "分", "is_correct": false, "explanation": "语义：“分”指分开，与句中的“在一起”矛盾。"}, {"text": "散", "is_correct": false, "explanation": "语义：“散”指分散，与句中已有的“散落”重复，且与“在一起”矛盾。"}, {"text": "炒", "is_correct": false, "explanation": "搭配：“炒”用于食物，不能用于硬币。"}], "explanations": {"聚": "正确：“聚在一起”指把散落的硬币收拢到一处，与句中语境吻合。", "分": "语义：“分”指分开，与句中的“在一起”矛盾。", "散": "语义：“散”指分散，与句中已有的“散落”重复，且与“在一起”矛盾。", "炒": "搭配：“炒”用于食物，不能用于硬币。"}, "sentence_index": 0, "correct_answer": "聚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他聚了很多饭。", "explanation": "这里应该用〈吃〉。聚指把分散的东西收拢到一处，吃饭不能说聚。"}, {"text": "她把衣服聚整齐了。", "explanation": "这里应该用〈叠〉。衣服整理要说“叠”，“聚”指把分散的东西收拢在一起，不能用来说把衣服弄整齐。"}, {"text": "他把一支笔聚在桌上。", "explanation": "这里应该用〈搁〉。聚指收拢多个分散的东西，只有一支笔时不说“聚”，应说“搁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ae8a38d-474d-4287-90a5-7a2e2072e722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25506, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "聚", "is_correct": true, "explanation": "聚 jù 是本词，意思是把分散的东西收拢在一起。"}, {"text": "局", "is_correct": false, "explanation": "jú（第二声）与 jù（第四声）声调不同，意思是局面。"}, {"text": "橘", "is_correct": false, "explanation": "jú（第二声）与 jù（第四声）声调不同，意思是橘子。"}, {"text": "趣", "is_correct": false, "explanation": "qù 与 jù 声母不同（q 与 j），声调相同，意思是兴趣。"}, {"text": "叙", "is_correct": false, "explanation": "xù 与 jù 声母不同（x 与 j），声调相同，意思是叙述。"}], "explanations": {"聚": "聚 jù 是本词，意思是把分散的东西收拢在一起。", "局": "jú（第二声）与 jù（第四声）声调不同，意思是局面。", "橘": "jú（第二声）与 jù（第四声）声调不同，意思是橘子。", "趣": "qù 与 jù 声母不同（q 与 j），声调相同，意思是兴趣。", "叙": "xù 与 jù 声母不同（x 与 j），声调相同，意思是叙述。"}, "sentence_index": null, "correct_answer": "聚"}, "level_3": {"options": [{"text": "聚", "is_correct": true, "explanation": "正确：“聚成一堆”表示把沙子收拢堆成一堆，与句中语境吻合。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”指拆开，与“成一堆”的结果矛盾。"}, {"text": "撒", "is_correct": false, "explanation": "语义：“撒”指向四周散开，与“成一堆”的结果矛盾。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象应是可食用的东西，不能与“成一堆”搭配，“吃沙子成一堆”不成立。"}], "explanations": {"聚": "正确：“聚成一堆”表示把沙子收拢堆成一堆，与句中语境吻合。", "拆": "语义：“拆”指拆开，与“成一堆”的结果矛盾。", "撒": "语义：“撒”指向四周散开，与“成一堆”的结果矛盾。", "吃": "搭配：“吃”的对象应是可食用的东西，不能与“成一堆”搭配，“吃沙子成一堆”不成立。"}, "sentence_index": 6, "correct_answer": "聚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小孩把一块石头聚在路边。", "explanation": "这里应该用〈放〉。聚指把两个以上分散的东西收拢到一起，只有一块石头时不说聚，应说放。"}, {"text": "他把一只碗聚在桌上。", "explanation": "这里应该用〈摆〉。聚要求收拢多个分散的东西，只有一只碗时不能说“聚”。"}, {"text": "她把一把钥匙聚进包里。", "explanation": "这里应该用〈放〉。聚要求收拢多个分散的东西，只有一把钥匙时应说“放”，不说“聚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ae8a38d-474d-4287-90a5-7a2e2072e722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把钥匙聚得一起，放进口袋里。", "corrected_sentence": "我把钥匙聚在一起，放进口袋里。", "error_description": "错误：“聚”后表示结果的“在一起”中，“在”误写成“得”。正确：“聚在一起”，应改为“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ae8a38d-474d-4287-90a5-7a2e2072e722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把钱聚成一起，买了一件礼物。", "corrected_sentence": "我们把钱聚在一起，买了一件礼物。", "error_description": "错误：补语用了“成一起”。正确：“聚在一起”。“聚成”表示结果变成某种形态（如“聚成一堆”），不能与“一起”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ae8a38d-474d-4287-90a5-7a2e2072e722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
