INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25508, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "湿度就是空气里有多少水。", "primary_collocate": null, "pronunciation": "shī dù", "ipa": "ʂʅ˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "海边的湿度比较大。", "target_word": "湿度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天暖气房里的湿度很低。", "target_word": "湿度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气预报会告诉我们温度和湿度。", "target_word": "湿度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿度大的时候，人会觉得很闷。", "target_word": "湿度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器能显示室内的湿度。", "target_word": "湿度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的湿度一般很高。", "target_word": "湿度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠的湿度非常低。", "target_word": "湿度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿度太高，面包很容易发霉。", "target_word": "湿度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天看天气预报里的湿度。", "target_word": "湿度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天下雨，今天的湿度还是很高。", "target_word": "湿度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相对湿度", "label": "复合"}, {"form": "空气湿度", "label": "复合"}, {"form": "湿度计", "label": "复合"}, {"form": "濕度", "label": "繁体"}], "register": "中性", "sense_fingerprint": "空气里水分的多少，天气和生活中常说的干湿程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de9a87f-9352-48aa-a1f5-bcc350764b12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25508, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "湿度", "is_correct": true, "explanation": "正确答案：湿度（shī dù），指空气中水蒸气的含量。"}, {"text": "十度", "is_correct": false, "explanation": "shí dù（第二声）与 shī dù（第一声）声调不同，意思是十度。"}, {"text": "适度", "is_correct": false, "explanation": "shì dù（第四声）与 shī dù（第一声）声调不同，意思是适度。"}, {"text": "试读", "is_correct": false, "explanation": "shì dú（第四、第二声）与 shī dù（第一、第四声）声调不同，意思是试读。"}, {"text": "四度", "is_correct": false, "explanation": "sì dù（第四声）与 shī dù（第一声）声母（s 与 sh）和声调都不同，意思是四度（音乐中的四度音程）。"}], "explanations": {"湿度": "正确答案：湿度（shī dù），指空气中水蒸气的含量。", "十度": "shí dù（第二声）与 shī dù（第一声）声调不同，意思是十度。", "适度": "shì dù（第四声）与 shī dù（第一声）声调不同，意思是适度。", "试读": "shì dú（第四、第二声）与 shī dù（第一、第四声）声调不同，意思是试读。", "四度": "sì dù（第四声）与 shī dù（第一声）声母（s 与 sh）和声调都不同，意思是四度（音乐中的四度音程）。"}, "sentence_index": null, "correct_answer": "湿度"}, "level_3": {"options": [{"text": "湿度", "is_correct": true, "explanation": "湿度：指空气中水蒸气的含量，海边空气的湿度可以说“比较大”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色用“深”“浅”描述，不说“比较大”。"}, {"text": "硬度", "is_correct": false, "explanation": "语义：硬度指固体材料的坚硬程度，“海边的硬度”不成立。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔指地面高出海平面的高度，海边海拔接近零，不能说“比较大”。"}], "explanations": {"湿度": "湿度：指空气中水蒸气的含量，海边空气的湿度可以说“比较大”。", "颜色": "搭配：颜色用“深”“浅”描述，不说“比较大”。", "硬度": "语义：硬度指固体材料的坚硬程度，“海边的硬度”不成立。", "海拔": "语义：海拔指地面高出海平面的高度，海边海拔接近零，不能说“比较大”。"}, "sentence_index": 0, "correct_answer": "湿度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地下室湿度很重，住在里面很闷。", "explanation": "这里应该用〈湿气〉。“湿气重”说屋里的潮气；湿度是测得的数值，应说“高”或“大”，不说“重”。"}, {"text": "这块面包的湿度太多，容易发霉。", "explanation": "这里应该用〈水分〉。“水分多”说的是食物里的水；湿度说的是空气中水蒸气的含量，不说“多”。"}, {"text": "这瓶水的湿度是一升，喝完就没了。", "explanation": "这里应该用〈容量〉。湿度指空气中水蒸气的含量，不用“升”计量；瓶装水的多少要说容量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湿度", "is_correct": true, "explanation": "湿度：指空气中水蒸气的含量，沙漠空气干燥，湿度低，句意相符。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：味道用“淡”“浓”描述，不说“低”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：沙漠是地点，没有体重，句意不通。"}, {"text": "视力", "is_correct": false, "explanation": "语义：沙漠不具备视力，“视力非常低”指的是人，句意不合。"}], "explanations": {"湿度": "湿度：指空气中水蒸气的含量，沙漠空气干燥，湿度低，句意相符。", "味道": "搭配：味道用“淡”“浓”描述，不说“低”。", "体重": "语义：沙漠是地点，没有体重，句意不通。", "视力": "语义：沙漠不具备视力，“视力非常低”指的是人，句意不合。"}, "sentence_index": 6, "correct_answer": "湿度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "仪器显示屏上有一把湿度，数字是六十。", "explanation": "量词错误：“把”用于有柄的器具，湿度不能用“把”来数，应说“一个湿度值”。"}, {"text": "我在报告里看到一块湿度，数字很高。", "explanation": "量词错误：“块”用于成块的东西，湿度是抽象数值，应说“一个湿度值”。"}, {"text": "今天测了一只湿度，数字很高。", "explanation": "量词错误：“只”用于动物或成对物件中的一个，湿度应说“一个湿度值”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间屋子的一根湿度是百分之七十。", "corrected_sentence": "这间屋子的湿度是百分之七十。", "error_description": "量词错误：“根”用于细长的东西，“湿度”是抽象数值，不能加“一根”来修饰；应说“这间屋子的湿度是百分之七十”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬天的湿度很干，皮肤容易干。", "corrected_sentence": "冬天的湿度很低，皮肤容易干。", "error_description": "词性误用：“干”是形容词，描述的是空气或皮肤的状态，不能直接形容“湿度”这个数值；应说“湿度很低”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
