INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25510, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "脂肪酸是构成脂肪和油脂的一类有机酸，能为身体提供能量。", "primary_collocate": null, "pronunciation": "zhī fáng suān", "ipa": "ʈʂɨ˥ fɑŋ˧˥ swan˥", "syllable_count": 3, "sentences": [{"text": "脂肪酸能给身体提供能量。", "target_word": "脂肪酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼油里含有很多脂肪酸。", "target_word": "脂肪酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，我们每天都需要一点脂肪酸。", "target_word": "脂肪酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "脂肪酸是构成油脂的一种有机酸。", "target_word": "脂肪酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动的时候，身体会用脂肪酸来产生能量。", "target_word": "脂肪酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "橄榄油中的脂肪酸对心脏很好。", "target_word": "脂肪酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种牛奶含有脂肪酸，也含有蛋白质。", "target_word": "脂肪酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身体缺少脂肪酸，会影响健康。", "target_word": "脂肪酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给孩子吃鱼，因为鱼里有脂肪酸。", "target_word": "脂肪酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，脂肪酸可以变成身体需要的能量。", "target_word": "脂肪酸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "科技", "sense_fingerprint": "构成脂肪、能为身体提供能量的物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b7c4d2-eae5-47dc-9765-446b23df0243') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25510, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脂肪酸", "is_correct": true, "explanation": "正确：脂肪酸是能给身体提供能量的物质，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能给身体提供能量。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能给身体提供能量。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能给身体提供能量。"}], "explanations": {"脂肪酸": "正确：脂肪酸是能给身体提供能量的物质，符合句意。", "石头": "语义：石头不能给身体提供能量。", "手机": "语义：手机不能给身体提供能量。", "椅子": "语义：椅子不能给身体提供能量。"}, "sentence_index": 0, "correct_answer": "脂肪酸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "脂肪酸是身体里的一种矿物质。", "explanation": "这里应该用〈有机酸〉。脂肪酸是有机物，不是矿物质，不能这样归类。"}, {"text": "脂肪酸是身体里的一种糖。", "explanation": "这里应该用〈有机酸〉。脂肪酸属于有机酸，不属于糖类，不能说成一种糖。"}, {"text": "脂肪酸是身体里的一种维生素。", "explanation": "这里应该用〈有机酸〉。脂肪酸属于有机酸，不是维生素，不能这样归类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ae8a38d-474d-4287-90a5-7a2e2072e722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25510, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脂肪酸", "is_correct": true, "explanation": "正确：牛奶含有脂肪酸，与后面“也含有蛋白质”并列，符合句意。"}, {"text": "石油", "is_correct": false, "explanation": "语义：牛奶里不会含有石油。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：牛奶里不会含有汽油。"}, {"text": "笑容", "is_correct": false, "explanation": "搭配：“含有”后面要接物质，“笑容”不能被“含有”。"}], "explanations": {"脂肪酸": "正确：牛奶含有脂肪酸，与后面“也含有蛋白质”并列，符合句意。", "石油": "语义：牛奶里不会含有石油。", "汽油": "语义：牛奶里不会含有汽油。", "笑容": "搭配：“含有”后面要接物质，“笑容”不能被“含有”。"}, "sentence_index": 6, "correct_answer": "脂肪酸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "脂肪酸是一种饮料。", "explanation": "这里应该用〈有机酸〉。脂肪酸属于有机酸，不是饮料，不能这样归类。"}, {"text": "脂肪酸是一种水果。", "explanation": "这里应该用〈有机酸〉。脂肪酸属于有机酸，不是水果，不能这样归类。"}, {"text": "脂肪酸是一种蔬菜。", "explanation": "这里应该用〈有机酸〉。脂肪酸属于有机酸，不是蔬菜，不能这样归类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ae8a38d-474d-4287-90a5-7a2e2072e722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种食用油里含有一条脂肪酸。", "corrected_sentence": "这种食用油里含有一种脂肪酸。", "error_description": "量词错误：脂肪酸应该用“种”，不用“条”。“条”一般用于长形物件，不能用来修饰脂肪酸。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ae8a38d-474d-4287-90a5-7a2e2072e722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种牛奶里含有很多条脂肪酸。", "corrected_sentence": "这种牛奶里含有很多脂肪酸。", "error_description": "量词错误：脂肪酸前不能用“条”，应直接说“很多脂肪酸”。“条”一般用于长形物件，不能用来修饰脂肪酸。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ae8a38d-474d-4287-90a5-7a2e2072e722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
