INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25514, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "己二酸是一种化学物质，可以用来做塑料和尼龙。", "primary_collocate": null, "pronunciation": "jǐ èr suān", "ipa": "tɕi˨˩ ɑɻ˥˩ swan˥", "syllable_count": 3, "sentences": [{"text": "己二酸可以用来做尼龙。", "target_word": "己二酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种己二酸是白色的粉末。", "target_word": "己二酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂买了很多己二酸做塑料。", "target_word": "己二酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说己二酸是一种化学物质。", "target_word": "己二酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "己二酸放在实验室的架子上。", "target_word": "己二酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把己二酸倒进了水里。", "target_word": "己二酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尼龙的原料里有己二酸。", "target_word": "己二酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶己二酸是昨天刚买的。", "target_word": "己二酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "己二酸不能直接喝，很危险。", "target_word": "己二酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用一袋己二酸做出了新的塑料。", "target_word": "己二酸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "己二酸：可用来做塑料和尼龙的化学物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea56e5e-7c24-45c0-acbd-cd48719e98b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25514, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "己二酸", "is_correct": true, "explanation": "正确：己二酸是尼龙的重要原料，可以用来制造尼龙。"}, {"text": "木材", "is_correct": false, "explanation": "语义：木材是天然材料，不是化工原料，不能用来做尼龙。"}, {"text": "白糖", "is_correct": false, "explanation": "搭配：“做尼龙”需要化工原料，不能与食品“白糖”搭配。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是无机材料，与尼龙的制造无关，句子读起来不成立。"}], "explanations": {"己二酸": "正确：己二酸是尼龙的重要原料，可以用来制造尼龙。", "木材": "语义：木材是天然材料，不是化工原料，不能用来做尼龙。", "白糖": "搭配：“做尼龙”需要化工原料，不能与食品“白糖”搭配。", "玻璃": "语义：玻璃是无机材料，与尼龙的制造无关，句子读起来不成立。"}, "sentence_index": 0, "correct_answer": "己二酸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈买了一只己二酸。", "explanation": "这里应该用〈公斤〉或〈袋〉。己二酸是化工原料，不用“只”，“只”指动物或独立的小物件。"}, {"text": "工厂用己二酸生产尼龙6。", "explanation": "这里应该用〈己内酰胺〉。己内酰胺是尼龙6的原料，己二酸用于生产尼龙66，两者不能互换。"}, {"text": "医生用己二酸给标本防腐。", "explanation": "这里应该用〈甲醛〉。甲醛能使标本防腐，己二酸没有这种用途，不能代替它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de4db2d-b451-4256-9725-b5daa27bb953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "己二酸", "is_correct": true, "explanation": "正确：尼龙的原料之一就是己二酸，句中说的是尼龙的原料。"}, {"text": "食盐", "is_correct": false, "explanation": "语义：食盐是调味品，不是尼龙的化工原料，句子读起来不成立。"}, {"text": "棉花", "is_correct": false, "explanation": "语义：棉花是天然纤维，不是尼龙的化学原料，与“原料里有”的语境不符。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“原料里有”通常指化工原料，不能与“石头”搭配。"}], "explanations": {"己二酸": "正确：尼龙的原料之一就是己二酸，句中说的是尼龙的原料。", "食盐": "语义：食盐是调味品，不是尼龙的化工原料，句子读起来不成立。", "棉花": "语义：棉花是天然纤维，不是尼龙的化学原料，与“原料里有”的语境不符。", "石头": "搭配：“原料里有”通常指化工原料，不能与“石头”搭配。"}, "sentence_index": 6, "correct_answer": "己二酸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一张己二酸。", "explanation": "这里应该用〈袋〉或〈公斤〉。〈张〉用于纸张、桌面等扁平的东西，己二酸是粉末，不能用“张”计量。"}, {"text": "妹妹给我看了一本己二酸。", "explanation": "这里应该用〈袋〉或〈公斤〉。〈本〉用于书籍、本子，己二酸是化学原料，不能用“本”计量。"}, {"text": "他从柜子里拿出一支己二酸。", "explanation": "这里应该用〈袋〉或〈公斤〉。〈支〉用于笔、烟等细长的棍状物，己二酸是粉末，不能用“支”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de4db2d-b451-4256-9725-b5daa27bb953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂买了一只己二酸做塑料。", "corrected_sentence": "工厂买了一吨己二酸做塑料。", "error_description": "量词错误：“己二酸”是化工原料，应说“一吨”（或“一袋”），不能说“一只”。“只”用于独立的个体，如动物或小物件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de4db2d-b451-4256-9725-b5daa27bb953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25514, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人己二酸搬进了仓库。", "corrected_sentence": "工人把己二酸搬进了仓库。", "error_description": "处置式错误：“己二酸”作“搬”的受事，需用“把”引出，省略“把”后句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de4db2d-b451-4256-9725-b5daa27bb953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
