INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25516, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水解酶是一种能帮助把大东西变成小东西的帮手。", "primary_collocate": null, "pronunciation": "shuǐ jiě méi", "ipa": "ʂuei˨˩˦ tɕjɛ˨˩˦ mei˧˥", "syllable_count": 3, "sentences": [{"text": "水解酶是帮助分解食物的小帮手。", "target_word": "水解酶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身体里的水解酶能把大块食物变小。", "target_word": "水解酶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水解酶帮我们消化米饭。", "target_word": "水解酶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有水解酶，身体很难消化肉。", "target_word": "水解酶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶洗衣液里有水解酶，能洗掉油渍。", "target_word": "水解酶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水解酶像剪刀，把长长的东西剪短。", "target_word": "水解酶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "嘴里的水解酶会把米饭变甜。", "target_word": "水解酶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友的肚子里也有水解酶。", "target_word": "水解酶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水解酶让大块的食物变成小块。", "target_word": "水解酶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，水解酶是很小的帮手。", "target_word": "水解酶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "口语", "sense_fingerprint": "帮助把大块东西分解成小块的帮手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a93ff8a0-dccc-4164-8da0-3eeb65b61e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25516, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "钢琴", "is_correct": false, "explanation": "搭配：“帮助分解食物”的主体应是能起催化作用的物质或器官，钢琴与这一用法搭配不上。"}, {"text": "卡车", "is_correct": false, "explanation": "语义：卡车是运输工具，不能帮助分解食物。"}, {"text": "教科书", "is_correct": false, "explanation": "语义：教科书是知识的载体，不能帮助分解食物，与句意不符。"}, {"text": "水解酶", "is_correct": true, "explanation": "正确：水解酶就是帮助分解食物的物质，与“帮助分解食物的小帮手”的解释一致。"}], "explanations": {"钢琴": "搭配：“帮助分解食物”的主体应是能起催化作用的物质或器官，钢琴与这一用法搭配不上。", "卡车": "语义：卡车是运输工具，不能帮助分解食物。", "教科书": "语义：教科书是知识的载体，不能帮助分解食物，与句意不符。", "水解酶": "正确：水解酶就是帮助分解食物的物质，与“帮助分解食物的小帮手”的解释一致。"}, "sentence_index": 0, "correct_answer": "水解酶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冬天我们用水解酶取暖。", "explanation": "水解酶的作用是把大块食物变成小块，它不会产生热量，这里误把它当成取暖用的东西了。"}, {"text": "天黑以后，他用水解酶照亮了路。", "explanation": "水解酶的作用是帮助分解食物，它不会发光，这里误把它当成照明用的东西了。"}, {"text": "把剩菜放进水解酶，就能保鲜很久。", "explanation": "水解酶的作用是帮助分解食物，它不能保存食物，这里误把它当成盛放食物、用来保鲜的东西了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7e65d75-8f0e-4a7a-a1d4-4c175ee14a6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25516, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "盐", "is_correct": false, "explanation": "语义：盐会让食物变咸，不能让米饭变甜，与句中的作用不符。"}, {"text": "醋", "is_correct": false, "explanation": "语义：醋会让食物变酸，不能让米饭变甜。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“会把米饭变甜”的主语应是能促成变化的东西，石头不具备这种作用。"}, {"text": "水解酶", "is_correct": true, "explanation": "正确：水解酶能把淀粉分解成糖，所以能让嘴里的米饭变甜，与句意相符。"}], "explanations": {"盐": "语义：盐会让食物变咸，不能让米饭变甜，与句中的作用不符。", "醋": "语义：醋会让食物变酸，不能让米饭变甜。", "石头": "搭配：“会把米饭变甜”的主语应是能促成变化的东西，石头不具备这种作用。", "水解酶": "正确：水解酶能把淀粉分解成糖，所以能让嘴里的米饭变甜，与句意相符。"}, "sentence_index": 6, "correct_answer": "水解酶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在超市买了一条水解酶，放进了冰箱。", "explanation": "量词用错：「条」用于细长的东西，酶不能用「条」来数，应说「一种水解酶」。"}, {"text": "厨房的桌上放着一根水解酶。", "explanation": "量词用错：「根」用于细长的条状物，酶不能用「根」来数，应说「一种水解酶」。"}, {"text": "药店里有一只水解酶。", "explanation": "量词用错：「只」用于动物或成对的物件，酶不能用「只」来数，应说「一种水解酶」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7e65d75-8f0e-4a7a-a1d4-4c175ee14a6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些水解酶们都能帮我们消化饭菜。", "corrected_sentence": "这些水解酶都能帮我们消化饭菜。", "error_description": "错误在于“水解酶”后面多加了“们”。“们”只用于指人的名词，水解酶是物质，应去掉“们”，说“这些水解酶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7e65d75-8f0e-4a7a-a1d4-4c175ee14a6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家新买了一位水解酶。", "corrected_sentence": "我家新买了一种水解酶。", "error_description": "错误在于量词。“位”用于指人的名词，水解酶是物质，应使用量词“种”，说“一种水解酶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7e65d75-8f0e-4a7a-a1d4-4c175ee14a6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
