INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25524, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由一个氧原子和一个氢原子组成的原子团（-OH），存在于醇、糖等有机化合物的分子中。", "primary_collocate": null, "pronunciation": "qiǎng jī", "ipa": "tɕʰiɑŋ˨˩˦ tɕi˥", "syllable_count": 2, "sentences": [{"text": "羟基由一个氧原子和一个氢原子组成。", "target_word": "羟基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒精分子里有羟基，所以它能溶于水。", "target_word": "羟基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化学课上，老师在黑板上画了羟基的结构。", "target_word": "羟基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "羟基里有氧也有氢。", "target_word": "羟基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "醇类的分子里都含有羟基。", "target_word": "羟基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化学书上说，羟基是氧和氢组成的原子团。", "target_word": "羟基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糖的分子上有很多羟基，所以它容易溶于水。", "target_word": "羟基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种化合物少了一个羟基，性质就不同了。", "target_word": "羟基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生把羟基的模型放在桌子上。", "target_word": "羟基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问：氧和氢组成的原子团叫什么？我说是羟基。", "target_word": "羟基", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "科技", "sense_fingerprint": "由氧原子和氢原子组成的原子团，化学名词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b7c4d2-eae5-47dc-9765-446b23df0243') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25524, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "羟基", "is_correct": true, "explanation": "羟基 qiǎng jī 是本词，指由一个氧原子和一个氢原子组成的原子团。"}, {"text": "枪击", "is_correct": false, "explanation": "qiāng（第一声）与 qiǎng（第三声）声调不同，“枪击”意思是开枪射击。"}, {"text": "枪机", "is_correct": false, "explanation": "qiāng（第一声）与 qiǎng（第三声）声调不同，“枪机”意思是枪的机械部件。"}, {"text": "墙基", "is_correct": false, "explanation": "qiáng（第二声）与 qiǎng（第三声）声调不同，“墙基”意思是墙的地基。"}], "explanations": {"羟基": "羟基 qiǎng jī 是本词，指由一个氧原子和一个氢原子组成的原子团。", "枪击": "qiāng（第一声）与 qiǎng（第三声）声调不同，“枪击”意思是开枪射击。", "枪机": "qiāng（第一声）与 qiǎng（第三声）声调不同，“枪机”意思是枪的机械部件。", "墙基": "qiáng（第二声）与 qiǎng（第三声）声调不同，“墙基”意思是墙的地基。"}, "sentence_index": null, "correct_answer": "羟基"}, "level_3": {"options": [{"text": "羟基", "is_correct": true, "explanation": "正确：句中说明由一个氧原子和一个氢原子组成的，正是羟基。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是由原子组成的化学成分，不能由一个氧原子和一个氢原子组成。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，不适合科技语境，且不能由原子组成。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能由氧原子和氢原子组成。"}], "explanations": {"羟基": "正确：句中说明由一个氧原子和一个氢原子组成的，正是羟基。", "冰箱": "语义：冰箱不是由原子组成的化学成分，不能由一个氧原子和一个氢原子组成。", "玩意儿": "语域：“玩意儿”是口语说法，不适合科技语境，且不能由原子组成。", "窗户": "语义：窗户是建筑部件，不能由氧原子和氢原子组成。"}, "sentence_index": 0, "correct_answer": "羟基"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "羟基是一种化合物。", "explanation": "这里的“羟基”是原子团，不是“化合物”，说成“一种化合物”不对。"}, {"text": "羟基是一种元素。", "explanation": "这里应该用〈原子团〉。羟基由氧和氢组成，是原子团，不是元素。"}, {"text": "羟基是一种酸。", "explanation": "这里应该用〈原子团〉。羟基是原子团，不是一类酸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ae8a38d-474d-4287-90a5-7a2e2072e722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25524, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "羟基", "is_correct": true, "explanation": "正确：糖分子上有很多羟基，这些羟基使糖容易溶于水。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块不是糖分子的组成部分，“糖的分子上有很多冰块”不成立。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不存在于分子上，也不能说明糖为什么容易溶于水。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“分子上有很多颜色”不搭配，“颜色”不能说明糖容易溶于水。"}], "explanations": {"羟基": "正确：糖分子上有很多羟基，这些羟基使糖容易溶于水。", "冰块": "语义：冰块不是糖分子的组成部分，“糖的分子上有很多冰块”不成立。", "石头": "语义：石头不存在于分子上，也不能说明糖为什么容易溶于水。", "颜色": "搭配：“分子上有很多颜色”不搭配，“颜色”不能说明糖容易溶于水。"}, "sentence_index": 6, "correct_answer": "羟基"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "甲醇是一种羟基。", "explanation": "这里应该用〈醇〉。甲醇属于醇类，羟基只是原子团，不是一类化合物。"}, {"text": "丙酮是一种羟基。", "explanation": "这里应该用〈酮〉。丙酮属于酮类，羟基不是一类化合物。"}, {"text": "甲酸是一种羟基。", "explanation": "这里应该用〈羧酸〉。甲酸属于羧酸，羟基不是一类化合物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ae8a38d-474d-4287-90a5-7a2e2072e722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25524, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个化合物里有一只羟基，所以它很活泼。", "corrected_sentence": "这个化合物里有一个羟基，所以它很活泼。", "error_description": "量词错误：羟基是原子团，应该用“个”，不用“只”。“只”一般用于动物等，不能用来修饰羟基。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ae8a38d-474d-4287-90a5-7a2e2072e722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25524, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种药的分子里有很多只羟基，所以它能溶于水。", "corrected_sentence": "这种药的分子里有很多羟基，所以它能溶于水。", "error_description": "量词错误：“羟基”前不能用“只”，应直接说“很多羟基”。“只”一般用于动物等，不能用来修饰羟基。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ae8a38d-474d-4287-90a5-7a2e2072e722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25526, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆分", "is_correct": true, "explanation": "正确答案：拆分，与“聚合”是反义词，指把一个整体分成几部分。"}, {"text": "散步", "is_correct": false, "explanation": "散步与“聚合”没有反义关系，指随意地慢慢走。"}, {"text": "煮饭", "is_correct": false, "explanation": "煮饭与“聚合”没有反义关系，指把米加水做成饭。"}, {"text": "举起", "is_correct": false, "explanation": "举起与“聚合”没有反义关系，指向上托起。"}], "correct_answer": "拆分", "explanations": {"拆分": "正确答案：拆分，与“聚合”是反义词，指把一个整体分成几部分。", "散步": "散步与“聚合”没有反义关系，指随意地慢慢走。", "煮饭": "煮饭与“聚合”没有反义关系，指把米加水做成饭。", "举起": "举起与“聚合”没有反义关系，指向上托起。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ca2cfbf-e3e8-48b8-b2c2-e98554d74ffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
